[
  {
    "function_json": {
      "function_name": "add_activitypub_keys_to_user",
      "return_type": "boolean",
      "arguments": "p_user_id uuid",
      "definition": "CREATE OR REPLACE FUNCTION public.add_activitypub_keys_to_user(p_user_id uuid)\n RETURNS boolean\n LANGUAGE plpgsql\n SECURITY DEFINER\nAS $function$\nDECLARE\n    v_profile RECORD;\n    v_metadata RECORD;\nBEGIN\n    -- Get user profile\n    SELECT username, domain, is_local \n    INTO v_profile\n    FROM profiles \n    WHERE id = p_user_id AND is_local = true;\n    \n    IF NOT FOUND THEN\n        RAISE EXCEPTION 'Local user not found: %', p_user_id;\n    END IF;\n    \n    -- Generate ActivityPub metadata (this will store private key securely)\n    SELECT * INTO v_metadata\n    FROM generate_activitypub_metadata(\n        p_user_id,\n        v_profile.username,\n        v_profile.domain\n    );\n    \n    -- Update the profile with ActivityPub data (NO private_key stored here)\n    UPDATE profiles SET\n        federated_id = v_metadata.federated_id,\n        inbox_url = v_metadata.inbox_url,\n        outbox_url = v_metadata.outbox_url,\n        followers_url = v_metadata.followers_url,\n        following_url = v_metadata.following_url,\n        featured_url = v_metadata.featured_url,\n        public_key = v_metadata.public_key,\n        -- private_key = v_metadata.private_key, -- REMOVED: No longer stored in profiles\n        last_synced_at = NOW()\n    WHERE id = p_user_id;\n    \n    RAISE NOTICE 'Generated ActivityPub keys for user: % (ID: %) - Private key stored securely', v_profile.username, p_user_id;\n    \n    RETURN TRUE;\nEND;\n$function$\n"
    }
  },
  {
    "function_json": {
      "function_name": "add_activitypub_to_new_local_user",
      "return_type": "void",
      "arguments": "p_user_id uuid, p_username text",
      "definition": "CREATE OR REPLACE FUNCTION public.add_activitypub_to_new_local_user(p_user_id uuid, p_username text)\n RETURNS void\n LANGUAGE plpgsql\n SECURITY DEFINER\nAS $function$\nDECLARE\n    v_domain TEXT;\n    v_metadata RECORD;\n    v_is_local BOOLEAN;\nBEGIN\n    -- Check if user is local\n    SELECT is_local INTO v_is_local FROM profiles WHERE id = p_user_id;\n    \n    IF v_is_local = true OR v_is_local IS NULL THEN\n        \n        -- Get the instance domain (cast JSONB to TEXT and remove quotes if present)\n        SELECT trim(both '\"' from config_value::text) INTO v_domain \n        FROM instance_config \n        WHERE config_key = 'domain' \n        LIMIT 1;\n        \n        IF v_domain IS NOT NULL AND v_domain != '' THEN\n            \n            -- Generate ActivityPub metadata\n            SELECT * INTO v_metadata\n            FROM generate_activitypub_metadata(\n                p_user_id,\n                p_username,\n                v_domain\n            );\n            \n            -- Update the profile\n            UPDATE profiles SET\n                domain = v_domain,\n                federated_id = v_metadata.federated_id,\n                inbox_url = v_metadata.inbox_url,\n                outbox_url = v_metadata.outbox_url,\n                followers_url = v_metadata.followers_url,\n                following_url = v_metadata.following_url,\n                featured_url = v_metadata.featured_url,\n                public_key = v_metadata.public_key,\n                private_key = v_metadata.private_key,\n                last_synced_at = NOW()\n            WHERE id = p_user_id;\n            \n            RAISE NOTICE 'Added ActivityPub federation to user: %', p_username;\n            \n        END IF;\n    END IF;\nEND;\n$function$\n"
    }
  },
  {
    "function_json": {
      "function_name": "add_existing_posts_to_new_follower_timeline",
      "return_type": "trigger",
      "arguments": "",
      "definition": "CREATE OR REPLACE FUNCTION public.add_existing_posts_to_new_follower_timeline()\n RETURNS trigger\n LANGUAGE plpgsql\nAS $function$\nDECLARE\n    post_record RECORD;\n    added_count INTEGER := 0;\nBEGIN\n    -- Only process accepted follows\n    IF NEW.status = 'accepted' THEN\n        -- Add recent public posts from the followed user to follower's home timeline\n        FOR post_record IN \n            SELECT id, created_at\n            FROM posts \n            WHERE author_id = NEW.following_id\n              AND visibility = 'public'\n              AND NOT COALESCE(is_deleted, false)\n              AND created_at > NOW() - INTERVAL '7 days'  -- Only last 7 days for new follows\n            ORDER BY created_at DESC\n            LIMIT 50  -- Reasonable limit to avoid overwhelming\n        LOOP\n            INSERT INTO timeline_entries (user_id, post_id, timeline_type, position)\n            VALUES (\n                NEW.follower_id,\n                post_record.id,\n                'home',\n                EXTRACT(epoch FROM post_record.created_at) * 1000000\n            )\n            ON CONFLICT (user_id, post_id, timeline_type) DO NOTHING;\n            \n            added_count := added_count + 1;\n        END LOOP;\n        \n        RAISE NOTICE 'Added % recent posts to new follower timeline', added_count;\n    END IF;\n    \n    RETURN NEW;\nEND;\n$function$\n"
    }
  },
  {
    "function_json": {
      "function_name": "add_post_emoji_reaction",
      "return_type": "uuid",
      "arguments": "p_user_id uuid, p_post_id uuid, p_emoji_id uuid DEFAULT NULL::uuid, p_custom_emoji_content text DEFAULT NULL::text",
      "definition": "CREATE OR REPLACE FUNCTION public.add_post_emoji_reaction(p_user_id uuid, p_post_id uuid, p_emoji_id uuid DEFAULT NULL::uuid, p_custom_emoji_content text DEFAULT NULL::text)\n RETURNS uuid\n LANGUAGE plpgsql\n SECURITY DEFINER\nAS $function$\nDECLARE\n    v_interaction_id uuid;\nBEGIN\n    -- Must provide either emoji_id or custom_emoji_content\n    IF p_emoji_id IS NULL AND p_custom_emoji_content IS NULL THEN\n        RAISE EXCEPTION 'Must provide either emoji_id or custom_emoji_content';\n    END IF;\n    \n    -- Insert emoji reaction\n    INSERT INTO post_interactions (\n        user_id,\n        post_id,\n        interaction_type,\n        emoji_id,\n        custom_emoji_content,\n        is_local,\n        metadata\n    ) VALUES (\n        p_user_id,\n        p_post_id,\n        'emoji_reaction',\n        p_emoji_id,\n        p_custom_emoji_content,\n        true,\n        jsonb_build_object(\n            'reaction_type', CASE WHEN p_emoji_id IS NOT NULL THEN 'custom_emoji' ELSE 'unicode_emoji' END,\n            'created_at', NOW()\n        )\n    ) RETURNING id INTO v_interaction_id;\n    \n    RETURN v_interaction_id;\nEND;\n$function$\n"
    }
  },
  {
    "function_json": {
      "function_name": "add_user_to_conversation",
      "return_type": "uuid",
      "arguments": "conversation_uuid uuid, user_uuid uuid, user_role text DEFAULT 'member'::text",
      "definition": "CREATE OR REPLACE FUNCTION public.add_user_to_conversation(conversation_uuid uuid, user_uuid uuid, user_role text DEFAULT 'member'::text)\n RETURNS uuid\n LANGUAGE plpgsql\nAS $function$\nDECLARE\n  participant_id UUID;\nBEGIN\n  INSERT INTO conversation_participants (conversation_id, user_id, role)\n  VALUES (conversation_uuid, user_uuid, user_role)\n  ON CONFLICT (conversation_id, user_id) \n  DO UPDATE SET \n    left_at = NULL,\n    role = user_role,\n    updated_at = CURRENT_TIMESTAMP\n  RETURNING id INTO participant_id;\n  \n  RETURN participant_id;\nEND;\n$function$\n"
    }
  },
  {
    "function_json": {
      "function_name": "archive_popular_hashtags",
      "return_type": "integer",
      "arguments": "",
      "definition": "CREATE OR REPLACE FUNCTION public.archive_popular_hashtags()\n RETURNS integer\n LANGUAGE plpgsql\nAS $function$\nDECLARE\n    archived_count INTEGER := 0;\nBEGIN\n    -- Create hashtag_archive table if it doesn't exist\n    CREATE TABLE IF NOT EXISTS hashtag_archive (\n        id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n        archived_at TIMESTAMPTZ DEFAULT NOW(),\n        original_hashtag_id UUID,\n        tag TEXT NOT NULL,\n        total_uses INTEGER,\n        peak_daily_uses INTEGER,\n        peak_daily_date DATE,\n        first_used_at TIMESTAMPTZ,\n        last_used_at TIMESTAMPTZ,\n        archive_reason TEXT\n    );\n    \n    -- Archive hashtags that had significant usage but are now inactive\n    INSERT INTO hashtag_archive (\n        original_hashtag_id, tag, total_uses, peak_daily_uses, \n        peak_daily_date, first_used_at, last_used_at, archive_reason\n    )\n    SELECT \n        id, tag, total_uses, peak_daily_uses, \n        peak_daily_date, first_used_at, last_used_at,\n        'Archived due to 6+ months inactivity but high historical usage'\n    FROM hashtags \n    WHERE last_used_at < NOW() - INTERVAL '6 months'\n      AND total_uses >= 100\n      AND id NOT IN (SELECT original_hashtag_id FROM hashtag_archive WHERE original_hashtag_id IS NOT NULL);\n    \n    GET DIAGNOSTICS archived_count = ROW_COUNT;\n    \n    RAISE NOTICE 'Archived % popular but inactive hashtags.', archived_count;\n    RETURN archived_count;\nEND;\n$function$\n"
    }
  },
  {
    "function_json": {
      "function_name": "backfill_timeline_entries",
      "return_type": "integer",
      "arguments": "",
      "definition": "CREATE OR REPLACE FUNCTION public.backfill_timeline_entries()\n RETURNS integer\n LANGUAGE plpgsql\nAS $function$\nDECLARE\n    processed_count INTEGER := 0;\n    post_record RECORD;\n    follower_record RECORD;\nBEGIN\n    RAISE NOTICE 'Starting timeline backfill for existing posts...';\n    \n    -- Process all public posts that might be missing from follower timelines\n    FOR post_record IN \n        SELECT id, author_id, created_at\n        FROM posts \n        WHERE visibility = 'public' \n          AND NOT COALESCE(is_deleted, false)\n          AND created_at > NOW() - INTERVAL '30 days'  -- Only last 30 days to avoid overwhelming\n        ORDER BY created_at DESC\n    LOOP\n        -- Add to all current followers' home timelines\n        FOR follower_record IN \n            SELECT f.follower_id \n            FROM follows f \n            WHERE f.following_id = post_record.author_id \n              AND f.status = 'accepted'\n        LOOP\n            INSERT INTO timeline_entries (user_id, post_id, timeline_type, position)\n            VALUES (\n                follower_record.follower_id, \n                post_record.id, \n                'home', \n                EXTRACT(epoch FROM post_record.created_at) * 1000000\n            )\n            ON CONFLICT (user_id, post_id, timeline_type) DO NOTHING;\n        END LOOP;\n        \n        processed_count := processed_count + 1;\n        \n        -- Progress logging every 100 posts\n        IF processed_count % 100 = 0 THEN\n            RAISE NOTICE 'Processed % posts...', processed_count;\n        END IF;\n    END LOOP;\n    \n    RAISE NOTICE 'Timeline backfill completed. Processed % posts.', processed_count;\n    RETURN processed_count;\nEND;\n$function$\n"
    }
  },
  {
    "function_json": {
      "function_name": "calculate_hashtag_trending_score",
      "return_type": "numeric",
      "arguments": "p_daily_uses integer, p_weekly_uses integer, p_total_uses integer, p_last_used_hours_ago numeric DEFAULT 0",
      "definition": "CREATE OR REPLACE FUNCTION public.calculate_hashtag_trending_score(p_daily_uses integer, p_weekly_uses integer, p_total_uses integer, p_last_used_hours_ago numeric DEFAULT 0)\n RETURNS numeric\n LANGUAGE plpgsql\n IMMUTABLE\nAS $function$\nDECLARE\n    v_velocity_score DECIMAL;\n    v_popularity_score DECIMAL;\n    v_recency_score DECIMAL;\n    v_trending_score DECIMAL;\nBEGIN\n    -- Velocity: daily vs weekly ratio\n    v_velocity_score := CASE \n        WHEN p_weekly_uses > 0 THEN (p_daily_uses::DECIMAL / p_weekly_uses::DECIMAL) * 10\n        ELSE p_daily_uses::DECIMAL\n    END;\n    \n    -- Popularity: logarithmic scale of daily uses\n    v_popularity_score := CASE \n        WHEN p_daily_uses > 0 THEN ln(p_daily_uses + 1) * 2\n        ELSE 0\n    END;\n    \n    -- Recency: decay based on time since last use\n    v_recency_score := CASE \n        WHEN p_last_used_hours_ago <= 1 THEN 10\n        WHEN p_last_used_hours_ago <= 6 THEN 8\n        WHEN p_last_used_hours_ago <= 12 THEN 6\n        WHEN p_last_used_hours_ago <= 24 THEN 4\n        ELSE 1\n    END;\n    \n    -- Combined trending score\n    v_trending_score := (v_velocity_score * 0.4) + (v_popularity_score * 0.4) + (v_recency_score * 0.2);\n    \n    RETURN GREATEST(v_trending_score, 0);\nEND;\n$function$\n"
    }
  },
  {
    "function_json": {
      "function_name": "calculate_post_engagement_score",
      "return_type": "numeric",
      "arguments": "p_favorites_count integer, p_reblogs_count integer, p_replies_count integer, p_hours_since_creation numeric",
      "definition": "CREATE OR REPLACE FUNCTION public.calculate_post_engagement_score(p_favorites_count integer, p_reblogs_count integer, p_replies_count integer, p_hours_since_creation numeric)\n RETURNS numeric\n LANGUAGE plpgsql\n IMMUTABLE\nAS $function$\nDECLARE\n    v_engagement_score DECIMAL;\n    v_time_decay DECIMAL;\nBEGIN\n    -- Base engagement (weighted: favorites=1, reblogs=2, replies=1.5)\n    v_engagement_score := (p_favorites_count * 1.0) + (p_reblogs_count * 2.0) + (p_replies_count * 1.5);\n    \n    -- Time decay factor (fresher content gets higher scores)\n    v_time_decay := CASE \n        WHEN p_hours_since_creation <= 1 THEN 1.0\n        WHEN p_hours_since_creation <= 6 THEN 0.8\n        WHEN p_hours_since_creation <= 24 THEN 0.6\n        WHEN p_hours_since_creation <= 72 THEN 0.4\n        ELSE 0.2\n    END;\n    \n    RETURN v_engagement_score * v_time_decay;\nEND;\n$function$\n"
    }
  },
  {
    "function_json": {
      "function_name": "can_manage_group_icon",
      "return_type": "boolean",
      "arguments": "conversation_uuid uuid, user_profile_id uuid",
      "definition": "CREATE OR REPLACE FUNCTION public.can_manage_group_icon(conversation_uuid uuid, user_profile_id uuid)\n RETURNS boolean\n LANGUAGE plpgsql\n SECURITY DEFINER\nAS $function$\nBEGIN\n  -- Check if user is a participant in the conversation\n  RETURN EXISTS (\n    SELECT 1 FROM conversation_participants cp\n    WHERE cp.conversation_id = conversation_uuid\n      AND cp.user_id = user_profile_id\n      AND cp.left_at IS NULL\n  );\nEND;\n$function$\n"
    }
  },
  {
    "function_json": {
      "function_name": "check_emoji_reaction_limit",
      "return_type": "trigger",
      "arguments": "",
      "definition": "CREATE OR REPLACE FUNCTION public.check_emoji_reaction_limit()\n RETURNS trigger\n LANGUAGE plpgsql\nAS $function$\nDECLARE\n    v_emoji_count integer;\nBEGIN\n    IF NEW.interaction_type = 'emoji_reaction' THEN\n        -- Count unique emoji reactions for this post\n        SELECT COUNT(DISTINCT COALESCE(emoji_id::text, custom_emoji_content))\n        INTO v_emoji_count\n        FROM post_interactions \n        WHERE post_id = NEW.post_id \n          AND interaction_type = 'emoji_reaction';\n        \n        -- Allow max 20 different emoji types per post\n        IF v_emoji_count >= 20 THEN\n            RAISE EXCEPTION 'Maximum of 20 different emoji types allowed per post';\n        END IF;\n    END IF;\n    \n    RETURN NEW;\nEND;\n$function$\n"
    }
  },
  {
    "function_json": {
      "function_name": "check_message_emoji_reaction_limit",
      "return_type": "trigger",
      "arguments": "",
      "definition": "CREATE OR REPLACE FUNCTION public.check_message_emoji_reaction_limit()\n RETURNS trigger\n LANGUAGE plpgsql\nAS $function$\nDECLARE\n    v_emoji_count integer;\nBEGIN\n    -- Count unique emoji reactions for this message\n    SELECT COUNT(DISTINCT emoji_id)\n    INTO v_emoji_count\n    FROM reactions \n    WHERE message_id = NEW.message_id;\n    \n    -- Allow max 20 different emoji types per message\n    IF v_emoji_count >= 20 THEN\n        RAISE EXCEPTION 'Maximum of 20 different emoji types allowed per message';\n    END IF;\n    \n    RETURN NEW;\nEND;\n$function$\n"
    }
  },
  {
    "function_json": {
      "function_name": "check_timeline_health",
      "return_type": "record",
      "arguments": "p_user_id uuid",
      "definition": "CREATE OR REPLACE FUNCTION public.check_timeline_health(p_user_id uuid)\n RETURNS TABLE(timeline_type text, total_entries integer, recent_entries integer, following_count integer, recommendations text)\n LANGUAGE plpgsql\nAS $function$\nBEGIN\n    RETURN QUERY\n    WITH timeline_stats AS (\n        SELECT \n            'home' as timeline_type,\n            COUNT(*)::INTEGER as total_entries,\n            COUNT(*) FILTER (WHERE te.created_at > NOW() - INTERVAL '7 days')::INTEGER as recent_entries\n        FROM timeline_entries te\n        WHERE te.user_id = p_user_id AND te.timeline_type = 'home'\n    ),\n    follow_stats AS (\n        SELECT COUNT(*)::INTEGER as following_count\n        FROM follows f\n        WHERE f.follower_id = p_user_id AND f.status = 'accepted'\n    )\n    SELECT \n        ts.timeline_type,\n        ts.total_entries,\n        ts.recent_entries,\n        fs.following_count,\n        CASE \n            WHEN ts.total_entries = 0 THEN 'No timeline entries found - run backfill'\n            WHEN ts.recent_entries < fs.following_count / 2 THEN 'Low recent activity - check if followed users are posting'\n            ELSE 'Timeline looks healthy'\n        END as recommendations\n    FROM timeline_stats ts, follow_stats fs;\nEND;\n$function$\n"
    }
  },
  {
    "function_json": {
      "function_name": "classify_activitypub_activity",
      "return_type": "record",
      "arguments": "p_activity_data jsonb, p_instance_domain text",
      "definition": "CREATE OR REPLACE FUNCTION public.classify_activitypub_activity(p_activity_data jsonb, p_instance_domain text)\n RETURNS TABLE(is_direct_message boolean, confidence numeric)\n LANGUAGE plpgsql\n STABLE\nAS $function$\nDECLARE\n  v_object JSONB;\n  v_to JSONB;\n  v_cc JSONB;\n  v_all_recipients TEXT[];\nBEGIN\n  v_object := CASE \n    WHEN jsonb_typeof(p_activity_data->'object') = 'string' THEN \n      jsonb_build_object('to', '[]'::jsonb, 'cc', '[]'::jsonb)\n    ELSE \n      p_activity_data->'object'\n  END;\n  \n  v_to := COALESCE(v_object->'to', '[]'::jsonb);\n  v_cc := COALESCE(v_object->'cc', '[]'::jsonb);\n  \n  -- Extract all recipients\n  SELECT array_agg(value::text)\n  INTO v_all_recipients\n  FROM jsonb_array_elements_text(v_to || v_cc);\n  \n  -- Rule 1: Contains 'Public' in 'to' → Public Post\n  IF v_to ? 'https://www.w3.org/ns/activitystreams#Public' THEN\n    RETURN QUERY SELECT false::boolean, 1.0::numeric;\n    RETURN;\n  END IF;\n  \n  -- Rule 2: Contains 'Public' in 'cc' → Unlisted Post (still public)\n  IF v_cc ? 'https://www.w3.org/ns/activitystreams#Public' THEN\n    RETURN QUERY SELECT false::boolean, 1.0::numeric;\n    RETURN;\n  END IF;\n  \n  -- Rule 3: Contains followers collection URL → Followers-only Post\n  IF EXISTS (\n    SELECT 1 FROM unnest(v_all_recipients) AS addr\n    WHERE addr LIKE '%/followers'\n  ) THEN\n    RETURN QUERY SELECT false::boolean, 1.0::numeric;\n    RETURN;\n  END IF;\n  \n  -- Rule 4: Check for local recipients (direct message)\n  IF EXISTS (\n    SELECT 1 FROM unnest(v_all_recipients) AS addr\n    WHERE addr LIKE '%' || p_instance_domain || '%'\n  ) THEN\n    RETURN QUERY SELECT true::boolean, 1.0::numeric;\n    RETURN;\n  END IF;\n  \n  -- Rule 5: No local recipients → Not our concern (treat as public)\n  RETURN QUERY SELECT false::boolean, 0.1::numeric;\nEND;\n$function$\n"
    }
  },
  {
    "function_json": {
      "function_name": "cleanup_inactive_hashtags",
      "return_type": "integer",
      "arguments": "",
      "definition": "CREATE OR REPLACE FUNCTION public.cleanup_inactive_hashtags()\n RETURNS integer\n LANGUAGE plpgsql\nAS $function$\nDECLARE\n    deleted_count INTEGER := 0;\n    temp_count INTEGER;\nBEGIN\n    -- Log cleanup start\n    RAISE NOTICE 'Starting hashtag cleanup process...';\n    \n    -- Delete hashtags that meet ALL of these criteria:\n    -- 1. Haven't been used in the last 90 days\n    -- 2. Have very low total usage (< 5 total uses)\n    -- 3. No trending activity (trending_score = 0 or NULL)\n    -- 4. Not currently in trending ranks\n    DELETE FROM hashtags \n    WHERE last_used_at < NOW() - INTERVAL '90 days'\n      AND total_uses < 5\n      AND (trending_score <= 0 OR trending_score IS NULL)\n      AND trending_rank IS NULL;\n    \n    GET DIAGNOSTICS deleted_count = ROW_COUNT;\n    \n    -- Also clean up hashtags that haven't been used in 6 months regardless of usage\n    -- (but keep a minimum threshold for very popular hashtags)\n    DELETE FROM hashtags \n    WHERE last_used_at < NOW() - INTERVAL '6 months'\n      AND total_uses < 100; -- Keep historically popular hashtags\n    \n    GET DIAGNOSTICS temp_count = ROW_COUNT;\n    deleted_count := deleted_count + temp_count;\n    \n    -- Clean up orphaned post_hashtags (hashtags that no longer exist)\n    DELETE FROM post_hashtags \n    WHERE hashtag_id NOT IN (SELECT id FROM hashtags);\n    \n    RAISE NOTICE 'Hashtag cleanup completed. Deleted % inactive hashtags.', deleted_count;\n    RETURN deleted_count;\nEND;\n$function$\n"
    }
  },
  {
    "function_json": {
      "function_name": "cleanup_old_federation_deliveries",
      "return_type": "integer",
      "arguments": "",
      "definition": "CREATE OR REPLACE FUNCTION public.cleanup_old_federation_deliveries()\n RETURNS integer\n LANGUAGE plpgsql\nAS $function$\nDECLARE\n    cleanup_count INTEGER := 0;\n    delivered_count INTEGER;\n    failed_count INTEGER;\nBEGIN\n    -- Delete delivered items older than 7 days\n    DELETE FROM federation_delivery_queue \n    WHERE status = 'delivered' \n    AND delivered_at < NOW() - INTERVAL '7 days';\n    \n    GET DIAGNOSTICS delivered_count = ROW_COUNT;\n    cleanup_count := delivered_count;\n    \n    -- Delete permanently failed items older than 30 days\n    DELETE FROM federation_delivery_queue \n    WHERE status = 'failed' \n    AND updated_at < NOW() - INTERVAL '30 days';\n    \n    GET DIAGNOSTICS failed_count = ROW_COUNT;\n    cleanup_count := cleanup_count + failed_count;\n    \n    RAISE NOTICE 'Cleaned up % delivered and % failed federation delivery records', delivered_count, failed_count;\n    \n    RETURN cleanup_count;\nEND;\n$function$\n"
    }
  },
  {
    "function_json": {
      "function_name": "cleanup_old_notifications",
      "return_type": "void",
      "arguments": "",
      "definition": "CREATE OR REPLACE FUNCTION public.cleanup_old_notifications()\n RETURNS void\n LANGUAGE plpgsql\nAS $function$\nBEGIN\n    DELETE FROM notifications \n    WHERE expires_at < NOW() \n    OR (is_read = true AND created_at < NOW() - INTERVAL '7 days');\nEND;\n$function$\n"
    }
  },
  {
    "function_json": {
      "function_name": "cleanup_old_trending_data",
      "return_type": "integer",
      "arguments": "",
      "definition": "CREATE OR REPLACE FUNCTION public.cleanup_old_trending_data()\n RETURNS integer\n LANGUAGE plpgsql\nAS $function$\nDECLARE\n    deleted_count INTEGER := 0;\n    temp_count INTEGER;\nBEGIN\n    -- Clean up trending posts older than 30 days\n    DELETE FROM trending_posts \n    WHERE period_start < NOW() - INTERVAL '30 days';\n    \n    GET DIAGNOSTICS deleted_count = ROW_COUNT;\n    \n    -- Clean up trending users older than 30 days\n    DELETE FROM trending_users \n    WHERE period_start < NOW() - INTERVAL '30 days';\n    \n    GET DIAGNOSTICS temp_count = ROW_COUNT;\n    deleted_count := deleted_count + temp_count;\n    \n    RAISE NOTICE 'Trending data cleanup completed. Deleted % old records.', deleted_count;\n    RETURN deleted_count;\nEND;\n$function$\n"
    }
  },
  {
    "function_json": {
      "function_name": "cleanup_trending_queue",
      "return_type": "integer",
      "arguments": "",
      "definition": "CREATE OR REPLACE FUNCTION public.cleanup_trending_queue()\n RETURNS integer\n LANGUAGE plpgsql\nAS $function$\nDECLARE\n    cleaned_count INTEGER := 0;\nBEGIN\n    -- Reset stuck processing items\n    UPDATE trending_refresh_queue \n    SET \n        is_processing = false,\n        processing_started_at = NULL\n    WHERE is_processing = true \n    AND processing_started_at < NOW() - INTERVAL '30 minutes';\n    \n    GET DIAGNOSTICS cleaned_count = ROW_COUNT;\n    \n    RETURN cleaned_count;\nEND;\n$function$\n"
    }
  },
  {
    "function_json": {
      "function_name": "collect_federation_stats",
      "return_type": "void",
      "arguments": "",
      "definition": "CREATE OR REPLACE FUNCTION public.collect_federation_stats()\n RETURNS void\n LANGUAGE plpgsql\n SECURITY DEFINER\nAS $function$\nBEGIN\n    INSERT INTO federation_delivery_stats (\n        period_start,\n        period_end,\n        total_deliveries,\n        successful_deliveries,\n        failed_deliveries,\n        avg_delivery_time_ms\n    )\n    SELECT \n        DATE_TRUNC('hour', NOW() - INTERVAL '6 hours') as period_start,\n        DATE_TRUNC('hour', NOW()) as period_end,\n        COUNT(*) as total_deliveries,\n        COUNT(*) FILTER (WHERE status = 'delivered') as successful_deliveries,\n        COUNT(*) FILTER (WHERE status = 'failed') as failed_deliveries,\n        AVG(delivery_duration_ms) as avg_delivery_time_ms\n    FROM federation_delivery_queue\n    WHERE created_at >= NOW() - INTERVAL '6 hours'\n    AND created_at < NOW()\n    AND status IN ('delivered', 'failed');\n    \n    RAISE NOTICE 'Federation stats collected for last 6 hours';\nEND;\n$function$\n"
    }
  },
  {
    "function_json": {
      "function_name": "convert_ap_to_jsonb",
      "return_type": "jsonb",
      "arguments": "html_content text, tags jsonb DEFAULT NULL::jsonb",
      "definition": "CREATE OR REPLACE FUNCTION public.convert_ap_to_jsonb(html_content text, tags jsonb DEFAULT NULL::jsonb)\n RETURNS jsonb\n LANGUAGE plpgsql\n IMMUTABLE\nAS $function$\nDECLARE\n    v_result JSONB := '[]'::jsonb;\n    v_working_content TEXT;\n    v_tag JSONB;\n    v_username TEXT;\n    v_mention_text TEXT;\n    v_pos INTEGER;\n    v_before_text TEXT;\n    v_after_text TEXT;\n    v_emoji_name TEXT;\n    v_emoji_url TEXT;\nBEGIN\n    -- If no content, return empty array\n    IF html_content IS NULL OR html_content = '' THEN\n        RETURN '[]'::jsonb;\n    END IF;\n\n    -- Clean HTML thoroughly\n    v_working_content := html_content;\n    WHILE v_working_content ~ '<[^>]*>' LOOP\n        v_working_content := regexp_replace(v_working_content, '<[^>]*>', '', 'g');\n    END LOOP;\n    v_working_content := regexp_replace(v_working_content, '&[a-zA-Z0-9#]+;', ' ', 'g');\n    v_working_content := regexp_replace(v_working_content, '\\s+', ' ', 'g');\n    v_working_content := trim(v_working_content);\n\n    -- If no tags, just return the cleaned text\n    IF tags IS NULL OR jsonb_typeof(tags) != 'array' THEN\n        IF v_working_content != '' THEN\n            v_result := v_result || jsonb_build_object(\n                'type', 'text',\n                'text', v_working_content\n            );\n        END IF;\n        RETURN v_result;\n    END IF;\n\n    -- Process all tags in a single pass to maintain proper order\n    DECLARE\n        tag_positions JSONB := '[]'::jsonb;\n        v_tag_data JSONB;\n        i INTEGER;\n    BEGIN\n        -- Find positions of all tags in content\n        FOR v_tag IN SELECT * FROM jsonb_array_elements(tags)\n        LOOP\n            v_mention_text := NULL;\n            v_pos := 0;\n            \n            IF v_tag->>'type' = 'Emoji' THEN\n                -- Extract emoji name (remove colons if present)\n                v_emoji_name := v_tag->>'name';\n                IF v_emoji_name LIKE ':%' AND v_emoji_name LIKE '%:' THEN\n                    v_emoji_name := substring(v_emoji_name from 2 for length(v_emoji_name) - 2);\n                END IF;\n                \n                v_mention_text := ':' || v_emoji_name || ':';\n                v_pos := position(v_mention_text in v_working_content);\n                \n            ELSIF v_tag->>'type' = 'Mention' THEN\n                v_username := v_tag->>'name';\n                IF v_username LIKE '@%' THEN\n                    v_username := substring(v_username from 2);\n                END IF;\n                \n                -- Try @username@domain format first\n                IF v_username LIKE '%@%' THEN\n                    v_mention_text := '@' || v_username;\n                    v_pos := position(v_mention_text in v_working_content);\n                END IF;\n                \n                -- If not found, try @username format\n                IF v_pos = 0 THEN\n                    v_mention_text := '@' || split_part(v_username, '@', 1);\n                    v_pos := position(v_mention_text in v_working_content);\n                END IF;\n                \n                -- If still not found, try just username\n                IF v_pos = 0 THEN\n                    v_mention_text := split_part(v_username, '@', 1);\n                    v_pos := position(v_mention_text in v_working_content);\n                END IF;\n                \n            ELSIF v_tag->>'type' = 'Hashtag' THEN\n                v_mention_text := '#' || (v_tag->>'name');\n                v_pos := position(v_mention_text in v_working_content);\n            END IF;\n            \n            -- Store tag position and data if found\n            IF v_pos > 0 THEN\n                tag_positions := tag_positions || jsonb_build_object(\n                    'position', v_pos,\n                    'length', length(v_mention_text),\n                    'tag', v_tag,\n                    'text', v_mention_text\n                );\n            END IF;\n        END LOOP;\n        \n        -- Sort tags by position\n        SELECT jsonb_agg(value ORDER BY (value->>'position')::integer)\n        INTO tag_positions\n        FROM jsonb_array_elements(tag_positions);\n        \n        -- Process tags in order\n        i := 0;\n        FOR v_tag_data IN SELECT * FROM jsonb_array_elements(COALESCE(tag_positions, '[]'::jsonb))\n        LOOP\n            v_pos := (v_tag_data->>'position')::integer - i;\n            v_mention_text := v_tag_data->>'text';\n            v_tag := v_tag_data->'tag';\n            \n            -- Adjust position for previous removals\n            v_before_text := substring(v_working_content from 1 for v_pos - 1);\n            v_after_text := substring(v_working_content from v_pos + length(v_mention_text));\n            \n            -- Add text before this tag\n            IF trim(v_before_text) != '' THEN\n                v_result := v_result || jsonb_build_object(\n                    'type', 'text',\n                    'text', v_before_text\n                );\n            END IF;\n            \n            -- Add the tag based on its type - USING UNIVERSAL FORMAT\n            IF v_tag->>'type' = 'Emoji' THEN\n                v_emoji_name := v_tag->>'name';\n                IF v_emoji_name LIKE ':%' AND v_emoji_name LIKE '%:' THEN\n                    v_emoji_name := substring(v_emoji_name from 2 for length(v_emoji_name) - 2);\n                END IF;\n                v_emoji_url := COALESCE(v_tag->'icon'->>'url', v_tag->>'icon');\n                \n                v_result := v_result || jsonb_build_object(\n                    'type', 'emoji',\n                    'emoji', jsonb_build_object(\n                        'name', v_emoji_name,\n                        'url', v_emoji_url,\n                        'id', COALESCE(v_tag->>'id', 'remote-' || v_emoji_name),\n                        'server_id', 'remote'\n                    )\n                );\n                \n            ELSIF v_tag->>'type' = 'Mention' THEN\n                v_username := v_tag->>'name';\n                IF v_username LIKE '@%' THEN\n                    v_username := substring(v_username from 2);\n                END IF;\n                \n                -- UNIVERSAL MENTION FORMAT - matches your examples\n                v_result := v_result || jsonb_build_object(\n                    'type', 'mention',\n                    'username', split_part(v_username, '@', 1),\n                    'domain', CASE \n                        WHEN position('@' in v_username) > 0 THEN split_part(v_username, '@', 2)\n                        ELSE NULL \n                    END,\n                    'url', v_tag->>'href',\n                    'userId', CASE \n                        WHEN position('@' in v_username) > 0 THEN 'remote-' || v_username\n                        ELSE NULL\n                    END,\n                    'isLocal', CASE \n                        WHEN position('@' in v_username) > 0 THEN false\n                        ELSE true\n                    END\n                );\n                \n            ELSIF v_tag->>'type' = 'Hashtag' THEN\n                v_result := v_result || jsonb_build_object(\n                    'type', 'hashtag',\n                    'hashtag', v_tag->>'name'\n                );\n            END IF;\n            \n            -- Update working content for next iteration\n            v_working_content := v_after_text;\n            i := i + length(v_mention_text);\n        END LOOP;\n        \n        -- Add any remaining text\n        IF trim(v_working_content) != '' THEN\n            v_result := v_result || jsonb_build_object(\n                'type', 'text',\n                'text', v_working_content\n            );\n        END IF;\n    END;\n\n    RETURN v_result;\nEND;\n$function$\n"
    }
  },
  {
    "function_json": {
      "function_name": "convert_jsonb_to_ap",
      "return_type": "text",
      "arguments": "content jsonb",
      "definition": "CREATE OR REPLACE FUNCTION public.convert_jsonb_to_ap(content jsonb)\n RETURNS text\n LANGUAGE plpgsql\n IMMUTABLE\nAS $function$\nDECLARE\n    content_part JSONB;\n    html_content TEXT := '';\n    part_type TEXT;\n    part_text TEXT;\n    part_url TEXT;\n    part_shortcode TEXT;\n    -- Variables for mention handling\n    mention_username TEXT;\n    mention_domain TEXT;\n    mention_href TEXT;\n    mention_text TEXT;\n    current_instance_domain TEXT;\nBEGIN\n    -- Handle null or empty content\n    IF content IS NULL THEN\n        RETURN '';\n    END IF;\n    \n    -- Handle string content (legacy format)\n    IF jsonb_typeof(content) = 'string' THEN\n        RETURN content #>> '{}';\n    END IF;\n    \n    -- Get current instance domain for local mention detection\n    SELECT trim(both '\"' from config_value::text) INTO current_instance_domain \n    FROM instance_config WHERE config_key = 'domain' LIMIT 1;\n    \n    -- Handle array content (your universal format)\n    IF jsonb_typeof(content) = 'array' THEN\n        FOR content_part IN SELECT jsonb_array_elements(content)\n        LOOP\n            part_type := content_part->>'type';\n            \n            CASE part_type\n                WHEN 'text' THEN\n                    part_text := content_part->>'text';\n                    IF part_text IS NOT NULL THEN\n                        -- Escape HTML entities in text content for safety\n                        part_text := replace(replace(replace(part_text, '&', '&amp;'), '<', '&lt;'), '>', '&gt;');\n                        html_content := html_content || part_text;\n                    END IF;\n                    \n                WHEN 'mention' THEN\n                    -- Extract mention data from your universal format\n                    mention_username := content_part->>'username';\n                    mention_domain := content_part->>'domain';\n                    \n                    IF mention_username IS NOT NULL THEN\n                        -- Always build full mention format for federation compatibility\n                        IF mention_domain IS NOT NULL THEN\n                            -- Use provided domain\n                            mention_href := 'https://' || mention_domain || '/@' || mention_username;\n                            mention_text := '@' || mention_username || '@' || mention_domain;\n                        ELSE\n                            -- Fallback to current instance domain for local users\n                            mention_href := 'https://' || current_instance_domain || '/@' || mention_username;\n                            mention_text := '@' || mention_username || '@' || current_instance_domain;\n                        END IF;\n                        \n                        -- Create the HTML mention link\n                        html_content := html_content || format('<a href=\"%s\" class=\"mention\">%s</a>', \n                            mention_href, mention_text);\n                    END IF;\n                    \n                WHEN 'emoji' THEN\n                    -- Handle custom emojis - use shortcode format for ActivityPub compatibility\n                    part_shortcode := content_part->'emoji'->>'name';\n                    \n                    IF part_shortcode IS NOT NULL THEN\n                        -- Always render as shortcode - emoji metadata goes in ActivityPub tags\n                        html_content := html_content || ':' || part_shortcode || ':';\n                    END IF;\n                    \n                WHEN 'file' THEN\n                    -- Files should not be inline in ActivityPub content (handled as attachments)\n                    CONTINUE;\n                    \n                WHEN 'url' THEN\n                    -- Handle URLs\n                    part_url := content_part->>'url';\n                    IF part_url IS NOT NULL THEN\n                        -- Escape URL for safety and create link\n                        part_url := replace(replace(replace(part_url, '&', '&amp;'), '<', '&lt;'), '>', '&gt;');\n                        html_content := html_content || format('<a href=\"%s\" rel=\"noopener noreferrer\" target=\"_blank\">%s</a>', \n                            part_url, part_url);\n                    END IF;\n                    \n                ELSE\n                    -- Unknown type, try to extract text and escape it\n                    part_text := content_part->>'text';\n                    IF part_text IS NOT NULL THEN\n                        part_text := replace(replace(replace(part_text, '&', '&amp;'), '<', '&lt;'), '>', '&gt;');\n                        html_content := html_content || part_text;\n                    END IF;\n            END CASE;\n        END LOOP;\n        \n        RETURN html_content;\n    END IF;\n    \n    -- Fallback: convert to text and escape\n    part_text := content::TEXT;\n    part_text := replace(replace(replace(part_text, '&', '&amp;'), '<', '&lt;'), '>', '&gt;');\n    RETURN part_text;\nEND;\n$function$\n"
    }
  },
  {
    "function_json": {
      "function_name": "convert_unified_content_to_plain_text",
      "return_type": "text",
      "arguments": "content jsonb",
      "definition": "CREATE OR REPLACE FUNCTION public.convert_unified_content_to_plain_text(content jsonb)\n RETURNS text\n LANGUAGE plpgsql\n IMMUTABLE\nAS $function$\nDECLARE\n    content_part JSONB;\n    plain_text TEXT := '';\n    part_type TEXT;\n    part_text TEXT;\n    part_name TEXT;\n    part_shortcode TEXT;\n    part_url TEXT;\nBEGIN\n    -- Handle null or empty content\n    IF content IS NULL THEN\n        RETURN '';\n    END IF;\n    \n    -- Handle string content (legacy format)\n    IF jsonb_typeof(content) = 'string' THEN\n        RETURN content #>> '{}';\n    END IF;\n    \n    -- Handle array content (MessagePart[])\n    IF jsonb_typeof(content) = 'array' THEN\n        FOR content_part IN SELECT jsonb_array_elements(content)\n        LOOP\n            part_type := content_part->>'type';\n            \n            CASE part_type\n                WHEN 'text' THEN\n                    part_text := content_part->>'text';\n                    IF part_text IS NOT NULL THEN\n                        plain_text := plain_text || part_text;\n                    END IF;\n                    \n                WHEN 'mention' THEN\n                    part_name := content_part->>'name';\n                    IF part_name IS NOT NULL THEN\n                        plain_text := plain_text || '@' || part_name;\n                    END IF;\n                    \n                WHEN 'emoji' THEN\n                    part_shortcode := content_part->>'shortcode';\n                    IF part_shortcode IS NOT NULL THEN\n                        plain_text := plain_text || ':' || part_shortcode || ':';\n                    END IF;\n                    \n                WHEN 'file' THEN\n                    -- Skip files in plain text\n                    CONTINUE;\n                    \n                WHEN 'url' THEN\n                    part_url := content_part->>'url';\n                    part_text := content_part->>'text';\n                    IF part_url IS NOT NULL THEN\n                        plain_text := plain_text || COALESCE(part_text, part_url);\n                    END IF;\n                    \n                ELSE\n                    -- Unknown type, try to extract text\n                    part_text := content_part->>'text';\n                    IF part_text IS NOT NULL THEN\n                        plain_text := plain_text || part_text;\n                    END IF;\n            END CASE;\n        END LOOP;\n        \n        RETURN plain_text;\n    END IF;\n    \n    -- Fallback: convert to text\n    RETURN content::TEXT;\nEND;\n$function$\n"
    }
  },
  {
    "function_json": {
      "function_name": "create_activitypub_note_activity",
      "return_type": "jsonb",
      "arguments": "post_id uuid",
      "definition": "CREATE OR REPLACE FUNCTION public.create_activitypub_note_activity(post_id uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\nAS $function$\nDECLARE\n    v_post posts%ROWTYPE;\n    v_sender_url text;\n    v_post_url text;\n    v_activity_id text;\n    v_mentioned_actor_urls text[];\n    v_note_object jsonb;\n    v_activity jsonb;\n    v_followers_url text;\nBEGIN\n    -- Get post data\n    SELECT * INTO v_post FROM posts WHERE id = post_id;\n    \n    IF NOT FOUND THEN\n        RETURN NULL;\n    END IF;\n    \n    -- Build sender and post URLs (FIXED: profiles instead of users)\n    SELECT 'https://' || trim(both '\"' from config_value::text) || '/users/' || p.id\n    INTO v_sender_url\n    FROM profiles p, instance_config \n    WHERE p.id = v_post.author_id AND config_key = 'domain';\n    \n    SELECT 'https://' || trim(both '\"' from config_value::text) || '/posts/' || v_post.id\n    INTO v_post_url\n    FROM instance_config \n    WHERE config_key = 'domain';\n    \n    v_activity_id := v_post_url || '#activity';\n    v_followers_url := v_sender_url || '/followers';\n    \n    -- Extract mentioned actor URLs for addressing\n    SELECT array_agg(mention->>'href') \n    INTO v_mentioned_actor_urls\n    FROM jsonb_array_elements(v_post.content) content_item,\n         jsonb_array_elements(COALESCE(content_item->'mentions', '[]'::jsonb)) mention\n    WHERE mention->>'href' IS NOT NULL;\n    \n    -- Create Note object with unified content processing\n    SELECT convert_jsonb_to_ap(v_post.content) INTO v_note_object;\n    \n    -- Add standard ActivityPub Note fields\n    v_note_object := v_note_object || jsonb_build_object(\n        'id', v_post_url,\n        'type', 'Note',\n        'published', v_post.created_at::text,\n        'attributedTo', v_sender_url,\n        'content', v_note_object->>'content',\n        'url', v_post_url,\n        'to', CASE \n            WHEN v_post.visibility = 'public' THEN '[\"https://www.w3.org/ns/activitystreams#Public\"]'::jsonb\n            WHEN v_post.visibility = 'followers' THEN jsonb_build_array(v_followers_url)\n            ELSE '[]'::jsonb\n        END,\n        'cc', CASE \n            WHEN v_post.visibility = 'public' THEN jsonb_build_array(v_followers_url)\n            ELSE '[]'::jsonb\n        END || COALESCE(to_jsonb(v_mentioned_actor_urls), '[]'::jsonb)\n    );\n    \n    -- Add reply context if this is a reply\n    IF v_post.in_reply_to IS NOT NULL THEN\n        v_note_object := v_note_object || jsonb_build_object(\n            'inReplyTo', (SELECT 'https://' || trim(both '\"' from config_value::text) || '/posts/' || v_post.in_reply_to FROM instance_config WHERE config_key = 'domain')\n        );\n    END IF;\n    \n    -- Create Activity wrapper\n    v_activity := jsonb_build_object(\n        'id', v_activity_id,\n        'type', 'Create',\n        'actor', v_sender_url,\n        'published', v_post.created_at::text,\n        'object', v_note_object,\n        'to', v_note_object->'to',\n        'cc', v_note_object->'cc'\n    );\n    \n    RETURN v_activity;\nEND;\n$function$\n"
    }
  },
  {
    "function_json": {
      "function_name": "create_comprehensive_timeline_entries",
      "return_type": "trigger",
      "arguments": "",
      "definition": "CREATE OR REPLACE FUNCTION public.create_comprehensive_timeline_entries()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\nAS $function$\nDECLARE\n    follower_record RECORD;\n    recipient_count INTEGER := 0;\nBEGIN\n    -- Always add to author's own timeline first\n    INSERT INTO timeline_entries (user_id, post_id, timeline_type, position)\n    VALUES (NEW.author_id, NEW.id, 'home', EXTRACT(epoch FROM NEW.created_at) * 1000000)\n    ON CONFLICT (user_id, post_id, timeline_type) DO NOTHING;\n    \n    -- For public posts, add to all followers' home timelines\n    IF NEW.visibility = 'public' AND NOT COALESCE(NEW.is_deleted, false) THEN\n        \n        -- Add to home timelines of all followers\n        FOR follower_record IN \n            SELECT f.follower_id \n            FROM follows f \n            WHERE f.following_id = NEW.author_id \n              AND f.status = 'accepted'\n              AND f.follower_id != NEW.author_id  -- Don't duplicate author's own timeline\n        LOOP\n            INSERT INTO timeline_entries (user_id, post_id, timeline_type, position)\n            VALUES (follower_record.follower_id, NEW.id, 'home', EXTRACT(epoch FROM NEW.created_at) * 1000000)\n            ON CONFLICT (user_id, post_id, timeline_type) DO NOTHING;\n            \n            recipient_count := recipient_count + 1;\n        END LOOP;\n        \n        RAISE NOTICE 'Timeline: Added post % to % follower home timelines', NEW.id, recipient_count;\n    END IF;\n    \n    RETURN NEW;\nEND;\n$function$\n"
    }
  },
  {
    "function_json": {
      "function_name": "create_default_notification_preferences",
      "return_type": "void",
      "arguments": "p_user_id uuid",
      "definition": "CREATE OR REPLACE FUNCTION public.create_default_notification_preferences(p_user_id uuid)\n RETURNS void\n LANGUAGE sql\n SECURITY DEFINER\nAS $function$\nINSERT INTO notification_preferences (user_id)\nVALUES (p_user_id)\nON CONFLICT (user_id) DO NOTHING;\n$function$\n"
    }
  },
  {
    "function_json": {
      "function_name": "create_default_server_structure",
      "return_type": "trigger",
      "arguments": "",
      "definition": "CREATE OR REPLACE FUNCTION public.create_default_server_structure()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\nAS $function$\nDECLARE\n    text_category_id UUID;\n    voice_category_id UUID;\n    general_channel_id UUID;\n    voice_channel_id UUID;\nBEGIN\n    -- Create Text Channels category\n    INSERT INTO channel_categories (name, server_id, \"order\")\n    VALUES ('Text Channels', NEW.id, 0)\n    RETURNING id INTO text_category_id;\n    \n    -- Create Voice Channels category\n    INSERT INTO channel_categories (name, server_id, \"order\")\n    VALUES ('Voice Channels', NEW.id, 1)\n    RETURNING id INTO voice_category_id;\n    \n    -- Create general text channel (type 0 = text)\n    INSERT INTO channels (name, type, server_id, category, \"order\")\n    VALUES ('general', 0, NEW.id, text_category_id, 0)\n    RETURNING id INTO general_channel_id;\n    \n    -- Create voice chat channel (type 1 = voice)\n    INSERT INTO channels (name, type, server_id, category, \"order\")\n    VALUES ('voice-chat', 1, NEW.id, voice_category_id, 0)\n    RETURNING id INTO voice_channel_id;\n    \n    -- Return the NEW record to continue the INSERT\n    RETURN NEW;\nEND;\n$function$\n"
    }
  },
  {
    "function_json": {
      "function_name": "create_federated_dm",
      "return_type": "uuid",
      "arguments": "sender_profile_id uuid, recipient_profile_id uuid, message_content text, activity_pub_id text DEFAULT NULL::text, metadata jsonb DEFAULT NULL::jsonb",
      "definition": "CREATE OR REPLACE FUNCTION public.create_federated_dm(sender_profile_id uuid, recipient_profile_id uuid, message_content text, activity_pub_id text DEFAULT NULL::text, metadata jsonb DEFAULT NULL::jsonb)\n RETURNS uuid\n LANGUAGE plpgsql\n SECURITY DEFINER\nAS $function$\nDECLARE\n    conversation_id uuid;\n    message_id uuid;\nBEGIN\n    -- Ensure both profiles exist\n    IF NOT EXISTS (SELECT 1 FROM public.profiles WHERE id = sender_profile_id) THEN\n        RAISE EXCEPTION 'Sender profile does not exist: %', sender_profile_id;\n    END IF;\n    \n    IF NOT EXISTS (SELECT 1 FROM public.profiles WHERE id = recipient_profile_id) THEN\n        RAISE EXCEPTION 'Recipient profile does not exist: %', recipient_profile_id;\n    END IF;\n    \n    -- UPDATED: Get or create conversation using participant system\n    SELECT c.id INTO conversation_id\n    FROM conversations c\n    WHERE c.type = 'direct'\n      AND EXISTS (\n        SELECT 1 FROM conversation_participants cp1\n        WHERE cp1.conversation_id = c.id \n          AND cp1.user_id = sender_profile_id \n          AND cp1.left_at IS NULL\n      )\n      AND EXISTS (\n        SELECT 1 FROM conversation_participants cp2\n        WHERE cp2.conversation_id = c.id \n          AND cp2.user_id = recipient_profile_id \n          AND cp2.left_at IS NULL\n      )\n      -- Ensure it's exactly 2 participants (direct conversation)\n      AND (\n        SELECT COUNT(*) FROM conversation_participants cp3\n        WHERE cp3.conversation_id = c.id \n          AND cp3.left_at IS NULL\n      ) = 2;\n    \n    -- If no conversation exists, create one using new structure\n    IF conversation_id IS NULL THEN\n        INSERT INTO public.conversations (type, created_by, is_active)\n        VALUES ('direct', sender_profile_id, TRUE)\n        RETURNING id INTO conversation_id;\n        \n        -- Add both participants\n        INSERT INTO conversation_participants (conversation_id, user_id, role, joined_at)\n        VALUES \n          (conversation_id, sender_profile_id, 'member', NOW()),\n          (conversation_id, recipient_profile_id, 'member', NOW());\n    END IF;\n    \n    -- Create the message\n    INSERT INTO public.messages (\n        conversation_id,\n        user_id,\n        content,\n        metadata\n    ) VALUES (\n        conversation_id,\n        sender_profile_id,\n        convert_ap_to_jsonb(message_content),\n        COALESCE(metadata, '{}'::jsonb)\n    ) RETURNING id INTO message_id;\n    \n    RETURN message_id;\nEND;\n$function$\n"
    }
  },
  {
    "function_json": {
      "function_name": "create_federated_profile",
      "return_type": "uuid",
      "arguments": "p_username text, p_display_name text DEFAULT NULL::text, p_domain text DEFAULT NULL::text, p_avatar_url text DEFAULT NULL::text, p_banner_url text DEFAULT NULL::text, p_bio text DEFAULT NULL::text, p_federated_id text DEFAULT NULL::text, p_inbox_url text DEFAULT NULL::text, p_outbox_url text DEFAULT NULL::text, p_followers_url text DEFAULT NULL::text, p_following_url text DEFAULT NULL::text, p_public_key text DEFAULT NULL::text",
      "definition": "CREATE OR REPLACE FUNCTION public.create_federated_profile(p_username text, p_display_name text DEFAULT NULL::text, p_domain text DEFAULT NULL::text, p_avatar_url text DEFAULT NULL::text, p_banner_url text DEFAULT NULL::text, p_bio text DEFAULT NULL::text, p_federated_id text DEFAULT NULL::text, p_inbox_url text DEFAULT NULL::text, p_outbox_url text DEFAULT NULL::text, p_followers_url text DEFAULT NULL::text, p_following_url text DEFAULT NULL::text, p_public_key text DEFAULT NULL::text)\n RETURNS uuid\n LANGUAGE plpgsql\n SECURITY DEFINER\nAS $function$\nDECLARE\n    new_profile_id UUID;\nBEGIN\n    -- Generate a new UUID for the federated profile\n    new_profile_id := gen_random_uuid();\n    \n    -- Insert the federated profile\n    INSERT INTO profiles (\n        id,\n        username,\n        display_name,\n        domain,\n        avatar_url,\n        banner_url,\n        bio,\n        federated_id,\n        inbox_url,\n        outbox_url,\n        followers_url,\n        following_url,\n        public_key,\n        is_local,\n        auth_user_id,\n        last_synced_at\n    ) VALUES (\n        new_profile_id,\n        p_username,\n        COALESCE(p_display_name, p_username),\n        COALESCE(p_domain, 'unknown'),\n        p_avatar_url,\n        p_banner_url,\n        p_bio,\n        p_federated_id,\n        p_inbox_url,\n        p_outbox_url,\n        p_followers_url,\n        p_following_url,\n        p_public_key,\n        false, -- is_local = false for federated profiles\n        NULL,  -- auth_user_id = NULL for federated profiles\n        NOW()\n    );\n    \n    RETURN new_profile_id;\nEND;\n$function$\n"
    }
