    "function_json": {
      "function_name": "create_group_conversation",
      "return_type": "uuid",
      "arguments": "creator_user_id uuid, conversation_name text DEFAULT NULL::text, participant_ids uuid[] DEFAULT '{}'::uuid[], initial_metadata jsonb DEFAULT '{}'::jsonb",
      "definition": "CREATE OR REPLACE FUNCTION public.create_group_conversation(creator_user_id uuid, conversation_name text DEFAULT NULL::text, participant_ids uuid[] DEFAULT '{}'::uuid[], initial_metadata jsonb DEFAULT '{}'::jsonb)\n RETURNS uuid\n LANGUAGE plpgsql\n SECURITY DEFINER\nAS $function$\nDECLARE\n  new_conversation_id UUID;\n  participant_id UUID;\nBEGIN\n  -- Create the conversation\n  INSERT INTO conversations (\n    created_by,\n    name,\n    type,\n    metadata,\n    is_active\n  ) VALUES (\n    creator_user_id,\n    conversation_name,\n    'group',\n    initial_metadata,\n    true\n  )\n  RETURNING id INTO new_conversation_id;\n\n  -- Add creator as participant\n  INSERT INTO conversation_participants (\n    conversation_id,\n    user_id,\n    joined_at\n  ) VALUES (\n    new_conversation_id,\n    creator_user_id,\n    CURRENT_TIMESTAMP\n  );\n\n  -- Add other participants\n  FOREACH participant_id IN ARRAY participant_ids\n  LOOP\n    -- Skip creator (already added)\n    IF participant_id != creator_user_id THEN\n      INSERT INTO conversation_participants (\n        conversation_id,\n        user_id,\n        joined_at\n      ) VALUES (\n        new_conversation_id,\n        participant_id,\n        CURRENT_TIMESTAMP\n      );\n    END IF;\n  END LOOP;\n\n  RETURN new_conversation_id;\nEND;\n$function$\n"
    }
