    "function_json": {
      "function_name": "create_group_conversation",
      "return_type": "uuid",
      "arguments": "creator_user_id uuid, participant_user_ids uuid[], conversation_name text DEFAULT NULL::text, is_private boolean DEFAULT true",
      "definition": "CREATE OR REPLACE FUNCTION public.create_group_conversation(creator_user_id uuid, participant_user_ids uuid[], conversation_name text DEFAULT NULL::text, is_private boolean DEFAULT true)\n RETURNS uuid\n LANGUAGE plpgsql\n SECURITY DEFINER\nAS $function$\nDECLARE\n  conversation_uuid UUID;\n  participant_id UUID;\nBEGIN\n  -- Create the conversation\n  INSERT INTO conversations (type, name, created_by, is_active, metadata)\n  VALUES (\n    'group',\n    conversation_name,\n    creator_user_id,\n    TRUE,\n    jsonb_build_object('is_private', is_private)\n  )\n  RETURNING id INTO conversation_uuid;\n  \n  -- Add all participants\n  FOREACH participant_id IN ARRAY participant_user_ids\n  LOOP\n    INSERT INTO conversation_participants (conversation_id, user_id, role, joined_at)\n    VALUES (conversation_uuid, participant_id, 'member', CURRENT_TIMESTAMP)\n    ON CONFLICT (conversation_id, user_id) DO NOTHING;\n  END LOOP;\n  \n  RETURN conversation_uuid;\nEND;\n$function$\n"
    }
