  {
    "function_json": {
      "function_name": "create_notification_structured",
      "return_type": "uuid",
      "arguments": "p_user_id uuid, p_type character varying, p_data jsonb DEFAULT '{}'::jsonb, p_channel_id uuid DEFAULT NULL::uuid, p_conversation_id uuid DEFAULT NULL::uuid",
      "definition": "CREATE OR REPLACE FUNCTION public.create_notification_structured(p_user_id uuid, p_type character varying, p_data jsonb DEFAULT '{}'::jsonb, p_channel_id uuid DEFAULT NULL::uuid, p_conversation_id uuid DEFAULT NULL::uuid)\n RETURNS uuid\n LANGUAGE plpgsql\n SECURITY DEFINER\nAS $function$\nDECLARE\n    v_notification_id UUID;\n    v_should_create BOOLEAN;\n    v_existing_count INTEGER;\n    v_time_threshold TIMESTAMP WITH TIME ZONE;\nBEGIN\n    -- Set appropriate time threshold based on notification type\n    v_time_threshold := CASE p_type\n        WHEN 'mention' THEN NOW() - INTERVAL '5 minutes'\n        WHEN 'reply' THEN NOW() - INTERVAL '5 minutes'\n        WHEN 'dm' THEN NOW() - INTERVAL '2 minutes'\n        WHEN 'follow' THEN NOW() - INTERVAL '10 minutes'\n        ELSE NOW() - INTERVAL '1 minute'\n    END;\n\n    -- Check for spam/duplicate notifications\n    SELECT COUNT(*) INTO v_existing_count\n    FROM notifications n\n    WHERE n.user_id = p_user_id\n      AND n.type = p_type\n      AND n.created_at > v_time_threshold\n      AND (\n          -- For mentions/replies, check if same source mentioned/replied to same target\n          (p_type IN ('mention', 'reply') AND \n           n.data->>'sender'->>'user_id' = p_data->'sender'->>'user_id') OR\n          -- For DMs, check if same conversation\n          (p_type = 'dm' AND \n           n.data->'conversation'->>'id' = p_data->'conversation'->>'id') OR\n          -- For follows, check if same follower\n          (p_type = 'follow' AND \n           n.data->'follower'->>'user_id' = p_data->'follower'->>'user_id')\n      );\n\n    -- Don't create notification if too many recent similar notifications\n    IF v_existing_count >= 3 THEN\n        RAISE NOTICE 'Suppressing duplicate notification: type=%, user=%, recent_count=%', \n            p_type, p_user_id, v_existing_count;\n        RETURN NULL;\n    END IF;\n\n    -- ✅ FIX: Insert notification without server_id column\n    INSERT INTO notifications (\n        user_id,\n        type,\n        data\n    ) VALUES (\n        p_user_id,\n        p_type,\n        p_data\n    ) RETURNING id INTO v_notification_id;\n\n    RAISE NOTICE '✅ Created notification: id=%, type=%, user=%', \n        v_notification_id, p_type, p_user_id;\n\n    RETURN v_notification_id;\nEND;\n$function$\n"
    }
  },
  {
    "function_json": {
      "function_name": "create_notification_structured",
      "return_type": "uuid",
      "arguments": "p_user_id uuid, p_type character varying, p_data jsonb DEFAULT '{}'::jsonb, p_server_id uuid DEFAULT NULL::uuid, p_channel_id uuid DEFAULT NULL::uuid, p_conversation_id uuid DEFAULT NULL::uuid",
      "definition": "CREATE OR REPLACE FUNCTION public.create_notification_structured(p_user_id uuid, p_type character varying, p_data jsonb DEFAULT '{}'::jsonb, p_server_id uuid DEFAULT NULL::uuid, p_channel_id uuid DEFAULT NULL::uuid, p_conversation_id uuid DEFAULT NULL::uuid)\n RETURNS uuid\n LANGUAGE sql\nAS $function$\n    SELECT send_notification_to_user(\n        p_type,\n        p_user_id,\n        p_data,\n        p_server_id,\n        p_channel_id,\n        p_conversation_id,\n        NULL,\n        'normal'\n    );\n$function$\n"
    }
  },
  {
    "function_json": {
      "function_name": "create_notification_with_spam_prevention",
      "return_type": "uuid",
      "arguments": "p_user_id uuid, p_type text, p_source_user_id uuid, p_title text DEFAULT NULL::text, p_message text DEFAULT NULL::text, p_data jsonb DEFAULT '{}'::jsonb, p_server_id uuid DEFAULT NULL::uuid, p_channel_id uuid DEFAULT NULL::uuid, p_conversation_id uuid DEFAULT NULL::uuid",
      "definition": "CREATE OR REPLACE FUNCTION public.create_notification_with_spam_prevention(p_user_id uuid, p_type text, p_source_user_id uuid, p_title text DEFAULT NULL::text, p_message text DEFAULT NULL::text, p_data jsonb DEFAULT '{}'::jsonb, p_server_id uuid DEFAULT NULL::uuid, p_channel_id uuid DEFAULT NULL::uuid, p_conversation_id uuid DEFAULT NULL::uuid)\n RETURNS uuid\n LANGUAGE plpgsql\n SECURITY DEFINER\nAS $function$\nDECLARE\n    v_notification_id uuid;\n    v_rate_limit RECORD;\n    v_should_suppress boolean := false;\n    v_time_threshold timestamp with time zone := NOW() - INTERVAL '2 minutes';\nBEGIN\n    -- Check for rate limiting (only for reaction notifications for now)\n    IF p_type = 'reaction' AND p_source_user_id IS NOT NULL THEN\n        \n        -- Get or create rate limit record\n        INSERT INTO notification_rate_limits (user_id, notification_type, source_user_id)\n        VALUES (p_user_id, p_type, p_source_user_id)\n        ON CONFLICT (user_id, notification_type, source_user_id)\n        DO UPDATE SET \n            notification_count = notification_rate_limits.notification_count + 1,\n            last_notification_at = NOW()\n        RETURNING * INTO v_rate_limit;\n        \n        -- Check if we should suppress (more than 3 notifications or within 2 minute window)\n        SELECT \n            (notification_count > 3) OR \n            (notification_count > 1 AND last_notification_at > v_time_threshold) OR\n            (suppressed_until IS NOT NULL AND suppressed_until > NOW())\n        INTO v_should_suppress\n        FROM notification_rate_limits\n        WHERE user_id = p_user_id AND notification_type = p_type AND source_user_id = p_source_user_id;\n        \n        IF v_should_suppress THEN\n            -- Update suppression time\n            UPDATE notification_rate_limits \n            SET suppressed_until = NOW() + INTERVAL '2 minutes'\n            WHERE user_id = p_user_id AND notification_type = p_type AND source_user_id = p_source_user_id;\n            \n            RETURN NULL; -- Suppress notification\n        END IF;\n    END IF;\n    \n    -- Create notification normally using the unified send_notification_to_user function\n    SELECT send_notification_to_user(\n        p_type,\n        p_user_id,\n        p_data,\n        p_server_id,\n        p_channel_id,\n        p_conversation_id,\n        p_source_user_id,\n        'normal'\n    ) INTO v_notification_id;\n    \n    RETURN v_notification_id;\nEND;\n$function$\n"
    }
  },
  {
    "function_json": {
      "function_name": "create_or_get_direct_conversation",
      "return_type": "uuid",
      "arguments": "user1_uuid uuid, user2_uuid uuid",
      "definition": "CREATE OR REPLACE FUNCTION public.create_or_get_direct_conversation(user1_uuid uuid, user2_uuid uuid)\n RETURNS uuid\n LANGUAGE plpgsql\nAS $function$\nDECLARE\n  conversation_uuid UUID;\nBEGIN\n  -- Try to find existing direct conversation between these two users\n  SELECT c.id INTO conversation_uuid\n  FROM conversations c\n  WHERE c.type = 'direct'\n    AND EXISTS (\n      SELECT 1 FROM conversation_participants cp1 \n      WHERE cp1.conversation_id = c.id \n        AND cp1.user_id = user1_uuid \n        AND cp1.left_at IS NULL\n    )\n    AND EXISTS (\n      SELECT 1 FROM conversation_participants cp2 \n      WHERE cp2.conversation_id = c.id \n        AND cp2.user_id = user2_uuid \n        AND cp2.left_at IS NULL\n    )\n    -- Ensure it's exactly 2 participants\n    AND (\n      SELECT COUNT(*) FROM conversation_participants cp3 \n      WHERE cp3.conversation_id = c.id \n        AND cp3.left_at IS NULL\n    ) = 2;\n  \n  -- If not found, create new conversation\n  IF conversation_uuid IS NULL THEN\n    INSERT INTO conversations (type, created_by, is_active)\n    VALUES ('direct', user1_uuid, TRUE)\n    RETURNING id INTO conversation_uuid;\n    \n    -- Add both users as participants\n    PERFORM add_user_to_conversation(conversation_uuid, user1_uuid, 'member');\n    PERFORM add_user_to_conversation(conversation_uuid, user2_uuid, 'member');\n  END IF;\n  \n  RETURN conversation_uuid;\nEND;\n$function$\n"
    }
  },
  {
    "function_json": {
      "function_name": "create_or_get_multi_conversation",
      "return_type": "uuid",
      "arguments": "participant_ids uuid[], conversation_type text DEFAULT 'direct'::text, conversation_name text DEFAULT NULL::text, created_by_id uuid DEFAULT NULL::uuid",
      "definition": "CREATE OR REPLACE FUNCTION public.create_or_get_multi_conversation(participant_ids uuid[], conversation_type text DEFAULT 'direct'::text, conversation_name text DEFAULT NULL::text, created_by_id uuid DEFAULT NULL::uuid)\n RETURNS uuid\n LANGUAGE plpgsql\nAS $function$\nDECLARE\n    v_conversation_id UUID;\n    participant_id UUID;\nBEGIN\n    -- Validate inputs\n    IF participant_ids IS NULL OR array_length(participant_ids, 1) < 2 THEN\n        RAISE EXCEPTION 'At least 2 participants required for conversation';\n    END IF;\n    \n    -- Try to find existing conversation with exact same participants\n    SELECT DISTINCT c.id INTO v_conversation_id\n    FROM conversations c\n    WHERE (\n        -- Count must match exactly\n        (SELECT COUNT(*) FROM conversation_participants cp WHERE cp.conversation_id = c.id AND cp.left_at IS NULL) = array_length(participant_ids, 1)\n        AND\n        -- All participants must be present\n        NOT EXISTS (\n            SELECT 1 FROM unnest(participant_ids) AS required_participant(participant_id)\n            WHERE NOT EXISTS (\n                SELECT 1 FROM conversation_participants cp \n                WHERE cp.conversation_id = c.id \n                  AND cp.user_id = required_participant.participant_id \n                  AND cp.left_at IS NULL\n            )\n        )\n    )\n    LIMIT 1;\n\n    -- Create new conversation if not found\n    IF v_conversation_id IS NULL THEN\n        INSERT INTO conversations (\n            name,\n            type,\n            created_by,\n            created_at\n        ) VALUES (\n            CASE \n                WHEN array_length(participant_ids, 1) = 2 AND conversation_name IS NULL THEN NULL\n                ELSE COALESCE(conversation_name, 'Group Chat')\n            END,\n            CASE \n                WHEN array_length(participant_ids, 1) = 2 THEN 'direct'\n                ELSE COALESCE(conversation_type, 'group')\n            END,\n            COALESCE(created_by_id, participant_ids[1]),\n            NOW()\n        )\n        RETURNING id INTO v_conversation_id;\n        \n        -- Add all participants\n        INSERT INTO conversation_participants (conversation_id, user_id, joined_at, role)\n        SELECT v_conversation_id, participant_id, NOW(), 'member'\n        FROM unnest(participant_ids) AS participants(participant_id);\n        \n        RAISE NOTICE '🆕 Created new % conversation % with % participants', \n            CASE WHEN array_length(participant_ids, 1) = 2 THEN 'direct' ELSE 'group' END,\n            v_conversation_id, \n            array_length(participant_ids, 1);\n    END IF;\n\n    RETURN v_conversation_id;\nEND;\n$function$\n"
    }
  },
  {
    "function_json": {
      "function_name": "create_system_message",
      "return_type": "uuid",
      "arguments": "p_channel_id uuid, p_user_id uuid, p_event_type text, p_initiated_by uuid DEFAULT NULL::uuid",
      "definition": "CREATE OR REPLACE FUNCTION public.create_system_message(p_channel_id uuid, p_user_id uuid, p_event_type text, p_initiated_by uuid DEFAULT NULL::uuid)\n RETURNS uuid\n LANGUAGE plpgsql\n SECURITY DEFINER\nAS $function$\nDECLARE\n    message_id UUID;\n    user_profile RECORD;\n    initiator_profile RECORD;\n    message_content JSONB;\n    initiated_by_data JSONB;\nBEGIN\n    -- Get user profile\n    SELECT username, display_name, avatar_url \n    INTO user_profile \n    FROM profiles \n    WHERE id = p_user_id;\n    \n    -- Handle initiator profile data\n    IF p_initiated_by IS NOT NULL THEN\n        SELECT username, display_name, avatar_url \n        INTO initiator_profile \n        FROM profiles \n        WHERE id = p_initiated_by;\n        \n        initiated_by_data := jsonb_build_object(\n            'id', p_initiated_by,\n            'username', initiator_profile.username,\n            'display_name', initiator_profile.display_name,\n            'avatar_url', initiator_profile.avatar_url\n        );\n    ELSE\n        initiated_by_data := NULL;\n    END IF;\n    \n    -- Build system message content\n    message_content := jsonb_build_array(\n        jsonb_build_object(\n            'type', 'system',\n            'event_type', p_event_type,\n            'user', jsonb_build_object(\n                'id', p_user_id,\n                'username', user_profile.username,\n                'display_name', user_profile.display_name,\n                'avatar_url', user_profile.avatar_url\n            ),\n            'initiated_by', initiated_by_data,\n            'timestamp', NOW()\n        )\n    );\n    \n    -- Insert system message\n    INSERT INTO messages (channel_id, user_id, content, is_system)\n    VALUES (p_channel_id, p_user_id, message_content, true)\n    RETURNING id INTO message_id;\n    \n    RETURN message_id;\nEND;\n$function$\n"
    }
  },
  {
    "function_json": {
      "function_name": "delete_server_with_cleanup",
      "return_type": "void",
      "arguments": "p_server_id uuid, p_owner_id uuid",
      "definition": "CREATE OR REPLACE FUNCTION public.delete_server_with_cleanup(p_server_id uuid, p_owner_id uuid)\n RETURNS void\n LANGUAGE plpgsql\n SECURITY DEFINER\nAS $function$\nBEGIN\n    -- Verify ownership\n    IF NOT EXISTS(SELECT 1 FROM servers WHERE id = p_server_id AND owner = p_owner_id) THEN\n        RAISE EXCEPTION 'Server not found or you are not the owner';\n    END IF;\n    \n    -- Delete in proper order to avoid foreign key issues\n    -- The CASCADE constraints will handle most cleanup, but we'll be explicit about the order\n    \n    -- 1. Delete server membership events first (to avoid trigger issues)\n    DELETE FROM server_membership_events WHERE server_id = p_server_id;\n    \n    -- 2. Delete the server (CASCADE will handle the rest)\n    DELETE FROM servers WHERE id = p_server_id AND owner = p_owner_id;\n    \n    -- If we get here, everything succeeded\nEND;$function$\n"
    }
  },
  {
    "function_json": {
      "function_name": "determine_message_federation_type",
      "return_type": "text",
      "arguments": "p_message_id uuid",
      "definition": "CREATE OR REPLACE FUNCTION public.determine_message_federation_type(p_message_id uuid)\n RETURNS text\n LANGUAGE plpgsql\n STABLE\nAS $function$\nDECLARE\n  v_message_type TEXT;\n  v_channel_id UUID;\n  v_conversation_id UUID;\n  v_remote_participant_count INTEGER := 0;\nBEGIN\n  -- Get message context\n  SELECT channel_id, conversation_id \n  INTO v_channel_id, v_conversation_id\n  FROM messages \n  WHERE id = p_message_id;\n  \n  -- Classification logic\n  IF v_channel_id IS NOT NULL THEN\n    -- Server chat message → Never federate\n    v_message_type := 'chat_local_only';\n    \n  ELSIF v_conversation_id IS NOT NULL THEN\n    -- DM message → Check for remote participants\n    SELECT COUNT(DISTINCT cp.user_id)\n    INTO v_remote_participant_count\n    FROM conversation_participants cp\n    JOIN profiles p ON cp.user_id = p.id\n    WHERE cp.conversation_id = v_conversation_id\n      AND NOT p.is_local\n      AND cp.left_at IS NULL;\n    \n    IF v_remote_participant_count > 0 THEN\n      v_message_type := 'dm_federated';\n    ELSE\n      v_message_type := 'dm_local_only';\n    END IF;\n    \n  ELSE\n    -- Orphaned message\n    v_message_type := 'unknown';\n  END IF;\n  \n  RETURN v_message_type;\nEND;\n$function$\n"
    }
  },
  {
    "function_json": {
      "function_name": "extract_activitypub_attachments",
      "return_type": "jsonb",
      "arguments": "content jsonb",
      "definition": "CREATE OR REPLACE FUNCTION public.extract_activitypub_attachments(content jsonb)\n RETURNS jsonb\n LANGUAGE plpgsql\n IMMUTABLE\nAS $function$\nDECLARE\n    content_part JSONB;\n    attachments JSONB := '[]'::JSONB;\n    part_type TEXT;\n    part_url TEXT;\n    part_name TEXT;\n    part_size INTEGER;\n    part_type_attr TEXT;\n    attachment JSONB;\nBEGIN\n    -- Handle null or empty content\n    IF content IS NULL OR jsonb_typeof(content) != 'array' THEN\n        RETURN '[]'::JSONB;\n    END IF;\n    \n    FOR content_part IN SELECT jsonb_array_elements(content)\n    LOOP\n        part_type := content_part->>'type';\n        \n        IF part_type = 'file' THEN\n            part_url := content_part->>'url';\n            part_name := content_part->>'name';\n            part_size := (content_part->>'size')::INTEGER;\n            part_type_attr := content_part->>'mimeType';\n            \n            IF part_url IS NOT NULL THEN\n                attachment := jsonb_build_object(\n                    'type', 'Document',\n                    'url', part_url,\n                    'mediaType', COALESCE(part_type_attr, 'application/octet-stream')\n                );\n                \n                IF part_name IS NOT NULL THEN\n                    attachment := attachment || jsonb_build_object('name', part_name);\n                END IF;\n                \n                IF part_size IS NOT NULL THEN\n                    attachment := attachment || jsonb_build_object('size', part_size);\n                END IF;\n                \n                attachments := attachments || jsonb_build_array(attachment);\n            END IF;\n        END IF;\n    END LOOP;\n    \n    RETURN attachments;\nEND;\n$function$\n"
    }
  },
  {
    "function_json": {
      "function_name": "extract_activitypub_emoji_tags",
      "return_type": "jsonb",
      "arguments": "content jsonb",
      "definition": "CREATE OR REPLACE FUNCTION public.extract_activitypub_emoji_tags(content jsonb)\n RETURNS jsonb\n LANGUAGE plpgsql\n IMMUTABLE\nAS $function$\nDECLARE\n    content_part JSONB;\n    emoji_tags JSONB := '[]'::JSONB;\n    part_type TEXT;\n    emoji_name TEXT;\n    emoji_url TEXT;\n    emoji_id TEXT;\n    emoji_tag JSONB;\n    current_instance_domain TEXT;\nBEGIN\n    -- Handle null or empty content\n    IF content IS NULL OR jsonb_typeof(content) != 'array' THEN\n        RETURN '[]'::JSONB;\n    END IF;\n    \n    -- Get current instance domain\n    SELECT trim(both '\"' from config_value::text) INTO current_instance_domain \n    FROM instance_config WHERE config_key = 'domain' LIMIT 1;\n    \n    FOR content_part IN SELECT jsonb_array_elements(content)\n    LOOP\n        part_type := content_part->>'type';\n        \n        IF part_type = 'emoji' THEN\n            emoji_name := content_part->'emoji'->>'name';\n            emoji_url := content_part->'emoji'->>'url';\n            emoji_id := content_part->'emoji'->>'id';\n            \n            IF emoji_name IS NOT NULL AND emoji_url IS NOT NULL THEN\n                -- Build the ActivityPub Emoji tag\n                emoji_tag := jsonb_build_object(\n                    'type', 'Emoji',\n                    'name', ':' || emoji_name || ':',\n                    'icon', jsonb_build_object(\n                        'type', 'Image',\n                        'url', emoji_url\n                    )\n                );\n                \n                -- Add id if available\n                IF emoji_id IS NOT NULL THEN\n                    emoji_tag := emoji_tag || jsonb_build_object('id', 'https://' || current_instance_domain || '/emojis/' || emoji_id);\n                END IF;\n                \n                -- Add to tags array\n                emoji_tags := emoji_tags || jsonb_build_array(emoji_tag);\n            END IF;\n        END IF;\n    END LOOP;\n    \n    RETURN emoji_tags;\nEND;\n$function$\n"
    }
  },
  {
    "function_json": {
      "function_name": "extract_activitypub_hashtag_tags",
      "return_type": "jsonb",
      "arguments": "content jsonb",
      "definition": "CREATE OR REPLACE FUNCTION public.extract_activitypub_hashtag_tags(content jsonb)\n RETURNS jsonb\n LANGUAGE plpgsql\n IMMUTABLE\nAS $function$\nDECLARE\n    content_part JSONB;\n    hashtag_tags JSONB := '[]'::JSONB;\n    part_type TEXT;\n    hashtag_name TEXT;\n    hashtag_href TEXT;\n    hashtag_tag JSONB;\n    current_instance_domain TEXT;\nBEGIN\n    -- Handle null or empty content\n    IF content IS NULL OR jsonb_typeof(content) != 'array' THEN\n        RETURN '[]'::JSONB;\n    END IF;\n    \n    -- Get current instance domain for hashtag URLs\n    SELECT trim(both '\"' from config_value::text) INTO current_instance_domain \n    FROM instance_config WHERE config_key = 'domain' LIMIT 1;\n    \n    FOR content_part IN SELECT jsonb_array_elements(content)\n    LOOP\n        part_type := content_part->>'type';\n        \n        IF part_type = 'hashtag' THEN\n            hashtag_name := content_part->>'name';\n            \n            IF hashtag_name IS NOT NULL THEN\n                -- Build hashtag URL - ActivityPub standard format\n                hashtag_href := 'https://' || current_instance_domain || '/tags/' || hashtag_name;\n                \n                -- Ensure hashtag name starts with # for ActivityPub format\n                IF NOT starts_with(hashtag_name, '#') THEN\n                    hashtag_name := '#' || hashtag_name;\n                END IF;\n                \n                -- Build the ActivityPub Hashtag tag\n                hashtag_tag := jsonb_build_object(\n                    'type', 'Hashtag',\n                    'href', hashtag_href,\n                    'name', hashtag_name\n                );\n                \n                -- Add to tags array\n                hashtag_tags := hashtag_tags || jsonb_build_array(hashtag_tag);\n            END IF;\n        END IF;\n    END LOOP;\n    \n    RETURN hashtag_tags;\nEND;\n$function$\n"
    }
  },
  {
    "function_json": {
      "function_name": "extract_activitypub_mention_tags",
      "return_type": "jsonb",
      "arguments": "content_data jsonb, recipient_urls text[], instance_domain text",
      "definition": "CREATE OR REPLACE FUNCTION public.extract_activitypub_mention_tags(content_data jsonb, recipient_urls text[], instance_domain text)\n RETURNS jsonb\n LANGUAGE plpgsql\n IMMUTABLE\n SET search_path TO 'extensions', 'public', 'pg_temp'\nAS $function$\nDECLARE\n    mention_tags JSONB := '[]'::JSONB;\n    recipient_url TEXT;\n    url_parts TEXT[];\n    domain TEXT;\n    username TEXT;\n    mention_name TEXT;\nBEGIN\n    -- Handle null or empty inputs\n    IF content_data IS NULL OR recipient_urls IS NULL OR array_length(recipient_urls, 1) = 0 THEN\n        RETURN mention_tags;\n    END IF;\n    \n    -- Process each recipient URL to create mention tags\n    -- This ensures every DM recipient is mentioned in ActivityPub\n    -- This is critical for proper DM delivery regardless of whether users explicitly @mention each other in chat\n    -- Critical for Mastodon compatibility and proper DM delivery\n    FOREACH recipient_url IN ARRAY recipient_urls\n    LOOP\n        -- Parse recipient URL to extract username and domain\n        -- Expected format: https://domain.com/@username or https://domain.com/users/username\n        IF recipient_url LIKE 'https://%' THEN\n            -- Remove https:// prefix\n            recipient_url := substring(recipient_url from 9);\n            \n            -- Split by / to get domain and path\n            url_parts := string_to_array(recipient_url, '/');\n            \n            IF array_length(url_parts, 1) >= 2 THEN\n                domain := url_parts[1];\n                \n                -- Extract username from path (handles both /@username and /users/username formats)\n                IF url_parts[2] LIKE '@%' THEN\n                    username := substring(url_parts[2] from 2);  -- Remove @ prefix\n                ELSIF array_length(url_parts, 1) >= 3 AND url_parts[2] = 'users' THEN\n                    username := url_parts[3];\n                ELSE\n                    username := url_parts[2];\n                END IF;\n                \n                -- Build mention name\n                mention_name := '@' || username;\n                IF domain != instance_domain THEN\n                    mention_name := mention_name || '@' || domain;\n                END IF;\n                \n                -- ✅ FIX: Use /users/ format instead of /@\n                -- Check if this mention is already in tags (avoid duplicates)\n                IF NOT EXISTS (\n                    SELECT 1 FROM jsonb_array_elements(mention_tags) AS tag\n                    WHERE tag->>'href' = 'https://' || domain || '/users/' || username\n                ) THEN\n                    mention_tags := mention_tags || jsonb_build_array(jsonb_build_object(\n                        'type', 'Mention',\n                        'href', 'https://' || domain || '/users/' || username,\n                        'name', mention_name\n                    ));\n                END IF;\n            END IF;\n        END IF;\n    END LOOP;\n    \n    RETURN mention_tags;\nEND;\n$function$\n"
    }
  },
  {
    "function_json": {
      "function_name": "extract_activitypub_mention_tags",
      "return_type": "jsonb",
      "arguments": "content jsonb",
      "definition": "CREATE OR REPLACE FUNCTION public.extract_activitypub_mention_tags(content jsonb)\n RETURNS jsonb\n LANGUAGE plpgsql\n IMMUTABLE\nAS $function$\nDECLARE\n    content_part JSONB;\n    mention_tags JSONB := '[]'::JSONB;\n    part_type TEXT;\n    mention_username TEXT;\n    mention_domain TEXT;\n    mention_href TEXT;\n    mention_name TEXT;\n    mention_tag JSONB;\n    current_instance_domain TEXT;\n    user_record RECORD;\nBEGIN\n    -- Handle null or empty content\n    IF content IS NULL OR jsonb_typeof(content) != 'array' THEN\n        RETURN '[]'::JSONB;\n    END IF;\n    \n    -- Get current instance domain\n    SELECT trim(both '\"' from config_value::text) INTO current_instance_domain \n    FROM instance_config WHERE config_key = 'domain' LIMIT 1;\n    \n    FOR content_part IN SELECT jsonb_array_elements(content)\n    LOOP\n        part_type := content_part->>'type';\n        \n        IF part_type = 'mention' THEN\n            mention_username := content_part->>'username';\n            mention_domain := content_part->>'domain';\n            \n            IF mention_username IS NOT NULL THEN\n                -- ✅ FIX: Look up actual user to get federated_id\n                IF mention_domain IS NOT NULL THEN\n                    -- Remote user: lookup by username + domain\n                    SELECT username, domain, federated_id \n                    INTO user_record\n                    FROM profiles \n                    WHERE username = mention_username \n                    AND domain = mention_domain \n                    AND NOT is_local\n                    LIMIT 1;\n                    \n                    IF user_record.federated_id IS NOT NULL THEN\n                        -- Use actual federated_id (correct ActivityPub actor URL)\n                        mention_href := user_record.federated_id;\n                        mention_name := '@' || mention_username || '@' || mention_domain;\n                    ELSE\n                        -- Fallback: construct URL (but this should be rare)\n                        mention_href := 'https://' || mention_domain || '/users/' || mention_username;\n                        mention_name := '@' || mention_username || '@' || mention_domain;\n                        RAISE WARNING 'Missing federated_id for user %@%, using constructed URL', mention_username, mention_domain;\n                    END IF;\n                ELSE\n                    -- Local user: use our domain\n                    mention_href := 'https://' || current_instance_domain || '/users/' || mention_username;\n                    mention_name := '@' || mention_username || '@' || current_instance_domain;\n                END IF;\n                \n                -- Build the ActivityPub Mention tag\n                mention_tag := jsonb_build_object(\n                    'type', 'Mention',\n                    'href', mention_href,\n                    'name', mention_name\n                );\n                \n                -- Add to tags array\n                mention_tags := mention_tags || jsonb_build_array(mention_tag);\n            END IF;\n        END IF;\n    END LOOP;\n    \n    RETURN mention_tags;\nEND;\n$function$\n"
    }
  },
  {
    "function_json": {
      "function_name": "extract_activitypub_tags",
      "return_type": "jsonb",
      "arguments": "content jsonb",
      "definition": "CREATE OR REPLACE FUNCTION public.extract_activitypub_tags(content jsonb)\n RETURNS jsonb\n LANGUAGE plpgsql\n IMMUTABLE\nAS $function$\nDECLARE\n    mention_tags JSONB;\n    emoji_tags JSONB;\n    all_tags JSONB := '[]'::JSONB;\nBEGIN\n    -- Get mention tags\n    mention_tags := extract_activitypub_mention_tags(content);\n    \n    -- Get emoji tags  \n    emoji_tags := extract_activitypub_emoji_tags(content);\n    \n    -- Combine them\n    IF jsonb_array_length(mention_tags) > 0 THEN\n        all_tags := all_tags || mention_tags;\n    END IF;\n    \n    IF jsonb_array_length(emoji_tags) > 0 THEN\n        all_tags := all_tags || emoji_tags;\n    END IF;\n    \n    RETURN all_tags;\nEND;\n$function$\n"
    }
  },
  {
    "function_json": {
      "function_name": "extract_all_activitypub_tags",
      "return_type": "jsonb",
      "arguments": "content jsonb",
      "definition": "CREATE OR REPLACE FUNCTION public.extract_all_activitypub_tags(content jsonb)\n RETURNS jsonb\n LANGUAGE plpgsql\n IMMUTABLE\nAS $function$\nDECLARE\n    mention_tags JSONB;\n    emoji_tags JSONB;\n    all_tags JSONB := '[]'::JSONB;\n    tag_item JSONB;\nBEGIN\n    -- Extract mention tags (using updated function with full domain format)\n    mention_tags := extract_activitypub_mention_tags(content);\n    FOR tag_item IN SELECT jsonb_array_elements(mention_tags)\n    LOOP\n        all_tags := all_tags || jsonb_build_array(tag_item);\n    END LOOP;\n    \n    -- Extract emoji tags (using updated function with correct data structure)\n    emoji_tags := extract_misskey_emoji_tags(content);\n    FOR tag_item IN SELECT jsonb_array_elements(emoji_tags)\n    LOOP\n        all_tags := all_tags || jsonb_build_array(tag_item);\n    END LOOP;\n    \n    RETURN all_tags;\nEND;\n$function$\n"
    }
