  {
    "function_json": {
      "function_name": "extract_custom_emoji_for_federation",
      "return_type": "record",
      "arguments": "content_text text",
      "definition": "CREATE OR REPLACE FUNCTION public.extract_custom_emoji_for_federation(content_text text)\n RETURNS TABLE(emoji_id uuid, emoji_name text, emoji_url text)\n LANGUAGE plpgsql\n STABLE\nAS $function$\nBEGIN\n    RETURN QUERY\n    SELECT \n        e.id,\n        e.name,\n        e.url\n    FROM emojis e\n    WHERE content_text ~ (':' || e.name || ':') \n       OR content_text ~ (':' || e.id::text || ':');\nEND;\n$function$\n"
    }
  },
  {
    "function_json": {
      "function_name": "extract_hashtags_from_content",
      "return_type": "text[]",
      "arguments": "content jsonb",
      "definition": "CREATE OR REPLACE FUNCTION public.extract_hashtags_from_content(content jsonb)\n RETURNS text[]\n LANGUAGE plpgsql\nAS $function$\nDECLARE\n    text_content TEXT := '';\n    hashtags TEXT[];\nBEGIN\n    -- Handle different content formats safely\n    IF content IS NULL THEN\n        RETURN ARRAY[]::TEXT[];\n    END IF;\n    \n    -- Check if content is an array (expected format)\n    IF jsonb_typeof(content) = 'array' THEN\n        -- Extract text from JSONB array elements\n        SELECT string_agg(elem->>'text', ' ')\n        INTO text_content\n        FROM jsonb_array_elements(content) AS elem\n        WHERE elem->>'type' = 'text';\n    ELSIF jsonb_typeof(content) = 'string' THEN\n        -- Handle simple string content\n        text_content := content #>> '{}';\n    ELSIF jsonb_typeof(content) = 'object' AND content ? 'text' THEN\n        -- Handle single object with text field\n        text_content := content->>'text';\n    ELSE\n        -- Try to extract any text value from the JSONB\n        text_content := content #>> '{}';\n    END IF;\n    \n    -- Return empty array if no text content found\n    IF text_content IS NULL OR text_content = '' THEN\n        RETURN ARRAY[]::TEXT[];\n    END IF;\n    \n    -- Extract hashtags using regex\n    SELECT array_agg(DISTINCT lower(substring(match, 2)))\n    INTO hashtags\n    FROM regexp_split_to_table(text_content, '\\s+') AS match\n    WHERE match ~ '^#[a-zA-Z0-9_]+$'\n      AND length(match) > 1\n      AND length(match) <= 50; -- Reasonable hashtag length limit\n    \n    -- Return empty array if no hashtags found\n    RETURN COALESCE(hashtags, ARRAY[]::TEXT[]);\nEND;\n$function$\n"
    }
  },
  {
    "function_json": {
      "function_name": "extract_mentions",
      "return_type": "text[]",
      "arguments": "content jsonb",
      "definition": "CREATE OR REPLACE FUNCTION public.extract_mentions(content jsonb)\n RETURNS text[]\n LANGUAGE plpgsql\nAS $function$\nDECLARE\n    mentions TEXT[] := '{}';\n    item JSONB;\nBEGIN\n    -- Handle array content (rich text)\n    IF jsonb_typeof(content) = 'array' THEN\n        FOR item IN SELECT jsonb_array_elements(content)\n        LOOP\n            IF item->>'type' = 'mention' AND item->>'mention' IS NOT NULL THEN\n                mentions := array_append(mentions, item->>'mention');\n            END IF;\n        END LOOP;\n    END IF;\n    \n    RETURN mentions;\nEND;\n$function$\n"
    }
  },
  {
    "function_json": {
      "function_name": "extract_misskey_emoji_tags",
      "return_type": "jsonb",
      "arguments": "content jsonb",
      "definition": "CREATE OR REPLACE FUNCTION public.extract_misskey_emoji_tags(content jsonb)\n RETURNS jsonb\n LANGUAGE plpgsql\n IMMUTABLE\nAS $function$\nDECLARE\n    content_part JSONB;\n    emoji_tags JSONB := '[]'::JSONB;\n    part_type TEXT;\n    emoji_name TEXT;\n    emoji_url TEXT;\n    emoji_id TEXT;\n    emoji_tag JSONB;\n    current_instance_domain TEXT;\nBEGIN\n    -- Handle null or empty content\n    IF content IS NULL OR jsonb_typeof(content) != 'array' THEN\n        RETURN '[]'::JSONB;\n    END IF;\n    \n    -- Get current instance domain for emoji ID URLs\n    SELECT trim(both '\"' from config_value::text) INTO current_instance_domain \n    FROM instance_config WHERE config_key = 'domain' LIMIT 1;\n    \n    FOR content_part IN SELECT jsonb_array_elements(content)\n    LOOP\n        part_type := content_part->>'type';\n        \n        IF part_type = 'emoji' THEN\n            -- Extract from our actual data structure: {\"type\": \"emoji\", \"emoji\": {\"name\": \"...\", \"url\": \"...\", \"id\": \"...\"}}\n            emoji_name := content_part->'emoji'->>'name';\n            emoji_url := content_part->'emoji'->>'url';\n            emoji_id := content_part->'emoji'->>'id';\n            \n            IF emoji_name IS NOT NULL AND emoji_url IS NOT NULL THEN\n                -- Build ActivityPub Emoji tag\n                emoji_tag := jsonb_build_object(\n                    'type', 'Emoji',\n                    'name', ':' || emoji_name || ':',\n                    'icon', jsonb_build_object(\n                        'type', 'Image',\n                        'mediaType', \n                            CASE \n                                WHEN right(lower(emoji_url), 4) = '.png' THEN 'image/png'\n                                WHEN right(lower(emoji_url), 5) = '.webp' THEN 'image/webp'\n                                WHEN right(lower(emoji_url), 4) = '.jpg' THEN 'image/jpeg'\n                                WHEN right(lower(emoji_url), 5) = '.jpeg' THEN 'image/jpeg'\n                                WHEN right(lower(emoji_url), 4) = '.gif' THEN 'image/gif'\n                                ELSE 'image/webp' -- fallback, most common for supabase\n                            END,\n                        'url', emoji_url\n                    )\n                );\n                \n                -- Add emoji ID if available (for proper ActivityPub identification)\n                -- Note: The 'id' field is optional and used for object identification, not image serving\n                -- It doesn't need to resolve to a real endpoint - it's just a unique identifier\n                -- The actual image is served from the 'icon.url' field above\n                IF emoji_id IS NOT NULL AND current_instance_domain IS NOT NULL THEN\n                    emoji_tag := emoji_tag || jsonb_build_object(\n                        'id', 'https://' || current_instance_domain || '/emojis/' || emoji_id\n                    );\n                END IF;\n                \n                emoji_tags := emoji_tags || jsonb_build_array(emoji_tag);\n            END IF;\n        END IF;\n    END LOOP;\n    \n    RETURN emoji_tags;\nEND;\n$function$\n"
    }
  },
  {
    "function_json": {
      "function_name": "generate_activitypub_metadata",
      "return_type": "record",
      "arguments": "p_user_id uuid, p_username text, p_domain text",
      "definition": "CREATE OR REPLACE FUNCTION public.generate_activitypub_metadata(p_user_id uuid, p_username text, p_domain text)\n RETURNS TABLE(federated_id text, inbox_url text, outbox_url text, followers_url text, following_url text, featured_url text, public_key text, private_key text)\n LANGUAGE plpgsql\n SECURITY DEFINER\nAS $function$\nDECLARE\n    v_base_url TEXT;\n    v_user_url TEXT;\n    v_private_key TEXT;\n    v_public_key TEXT;\nBEGIN\n    -- Build base URLs\n    v_base_url := 'https://' || p_domain;\n    v_user_url := v_base_url || '/users/' || p_username;\n    \n    -- Generate RSA key pair\n    SELECT rsa.private_key, rsa.public_key \n    INTO v_private_key, v_public_key\n    FROM generate_rsa_keypair() AS rsa;\n    \n    -- Store private key securely in user_private_keys table\n    INSERT INTO user_private_keys (user_id, private_key, created_at)\n    VALUES (p_user_id, v_private_key, NOW())\n    ON CONFLICT (user_id) DO UPDATE SET \n        private_key = EXCLUDED.private_key,\n        created_at = EXCLUDED.created_at;\n    \n    -- Return all ActivityPub metadata (private_key returned for compatibility but should not be stored in profiles)\n    RETURN QUERY SELECT\n        v_user_url,                              -- federated_id\n        v_user_url || '/inbox',                  -- inbox_url\n        v_user_url || '/outbox',                 -- outbox_url\n        v_user_url || '/followers',              -- followers_url\n        v_user_url || '/following',              -- following_url\n        v_user_url || '/featured',               -- featured_url\n        v_public_key,                            -- public_key\n        v_private_key;                           -- private_key (for compatibility)\nEND;\n$function$\n"
    }
  },
  {
    "function_json": {
      "function_name": "generate_rsa_keypair",
      "return_type": "record",
      "arguments": "",
      "definition": "CREATE OR REPLACE FUNCTION public.generate_rsa_keypair()\n RETURNS TABLE(private_key text, public_key text)\n LANGUAGE plpgsql\n SECURITY DEFINER\nAS $function$\nDECLARE\n    v_url TEXT := 'http://kong:8000/functions/v1/generate-keys'; -- Update to your edge function endpoint if needed\n    v_status INTEGER;\n    v_response TEXT;\n    v_data JSONB;\nBEGIN\n    -- Call the edge function to generate real keys\n    SELECT status, content INTO v_status, v_response\n      FROM http((\n        'POST',\n        v_url,\n        ARRAY[ ('Content-Type','application/json') ]::http_header[],\n        'application/json',\n        '{}' -- empty POST body\n      )::http_request);\n\n    IF v_status != 200 THEN\n      RAISE EXCEPTION 'Failed to fetch keys: HTTP %: %', v_status, v_response;\n    END IF;\n\n    v_data := v_response::jsonb;\n\n    RETURN QUERY SELECT\n      v_data->>'private_key',\n      v_data->>'public_key';\nEND;\n$function$\n"
    }
  },
  {
    "function_json": {
      "function_name": "get_activitypub_conversation_context",
      "return_type": "record",
      "arguments": "in_post_id uuid",
      "definition": "CREATE OR REPLACE FUNCTION public.get_activitypub_conversation_context(in_post_id uuid)\n RETURNS TABLE(post_id uuid, conversation_root_id uuid, total_posts integer, max_depth integer, root_published_at timestamp with time zone, latest_activity timestamp with time zone)\n LANGUAGE plpgsql\nAS $function$\nDECLARE\n  root_id UUID;\nBEGIN\n  -- First, find the conversation root\n  SELECT cr.root_id INTO root_id\n  FROM get_activitypub_conversation_root(in_post_id) cr;\n\n  -- Get conversation context statistics from the posts table\n  RETURN QUERY\n  WITH conversation_stats AS (\n      SELECT \n          COUNT(*) as total_posts,\n          MAX(CASE \n              WHEN p.in_reply_to IS NULL THEN 0\n              ELSE (\n                  WITH RECURSIVE depth_calc AS (\n                      SELECT id, in_reply_to, 1 as depth\n                      FROM posts \n                      WHERE id = p.id\n                      \n                      UNION ALL\n                      \n                      SELECT parent.id, parent.in_reply_to, dc.depth + 1\n                      FROM posts parent\n                      INNER JOIN depth_calc dc ON parent.id = dc.in_reply_to\n                      WHERE dc.depth < 20\n                  )\n                  SELECT COALESCE(MAX(depth), 0) FROM depth_calc\n              )\n          END) as max_depth,\n          MIN(p.created_at) as root_published_at,\n          MAX(p.updated_at) as latest_activity\n      FROM posts p\n      WHERE (p.id = root_id OR p.conversation_root_id = root_id)\n         AND p.deleted_at IS NULL\n  )\n  SELECT \n      in_post_id,\n      root_id,\n      cs.total_posts::INTEGER,\n      cs.max_depth::INTEGER,\n      cs.root_published_at,\n      cs.latest_activity\n  FROM conversation_stats cs;\nEND;\n$function$\n"
    }
  },
  {
    "function_json": {
      "function_name": "get_activitypub_conversation_root",
      "return_type": "uuid",
      "arguments": "post_id uuid",
      "definition": "CREATE OR REPLACE FUNCTION public.get_activitypub_conversation_root(post_id uuid)\n RETURNS TABLE(root_id uuid)\n LANGUAGE plpgsql\nAS $function$\nBEGIN\n    RETURN QUERY\n    SELECT COALESCE(p.conversation_root_id, p.id) as root_id\n    FROM posts p\n    WHERE p.id = post_id\n      AND p.deleted_at IS NULL;\nEND;\n$function$\n"
    }
  },
  {
    "function_json": {
      "function_name": "get_activitypub_conversation_thread",
      "return_type": "record",
      "arguments": "in_conversation_root_id uuid",
      "definition": "CREATE OR REPLACE FUNCTION public.get_activitypub_conversation_thread(in_conversation_root_id uuid)\n RETURNS TABLE(id uuid, uri text, content jsonb, content_type text, actor_uri text, actor_name text, actor_preferred_username text, actor_icon text, reply_to_id uuid, conversation_root_id uuid, likes_count integer, shares_count integer, replies_count integer, published_at timestamp with time zone, updated_at timestamp with time zone, depth integer, path text)\n LANGUAGE plpgsql\nAS $function$\nBEGIN\n    RETURN QUERY\n    WITH RECURSIVE conversation_thread AS (\n        -- Base case: get the root post(s)\n        SELECT \n            p.id,\n            COALESCE(p.ap_id, p.url, '/posts/' || p.id::text) AS uri,\n            p.content,\n            'text/html' AS content_type,\n            COALESCE(\n                prof.federated_id, \n                'https://' || prof.domain || '/users/' || prof.username\n            ) AS actor_uri,\n            COALESCE(prof.display_name, prof.username) AS actor_name,\n            prof.username AS actor_preferred_username,\n            prof.avatar_url AS actor_icon,\n            p.in_reply_to AS reply_to_id,\n            p.conversation_root_id,\n            p.favorites_count AS likes_count,\n            p.reblogs_count AS shares_count,\n            p.replies_count,\n            p.created_at AS published_at,\n            p.updated_at,\n            0 AS depth,\n            LPAD(ROW_NUMBER() OVER (ORDER BY p.created_at)::TEXT, 10, '0') AS path\n        FROM posts p\n        LEFT JOIN profiles prof ON p.author_id = prof.id\n        WHERE (p.id = in_conversation_root_id OR p.conversation_root_id = in_conversation_root_id)\n            AND p.in_reply_to IS NULL\n            AND p.deleted_at IS NULL\n\n        UNION ALL\n\n        -- Recursive case: get replies ordered by publication time\n        SELECT \n            reply.id,\n            COALESCE(reply.ap_id, reply.url, '/posts/' || reply.id::text) AS uri,\n            reply.content,\n            'text/html' AS content_type,\n            COALESCE(\n                prof.federated_id, \n                'https://' || prof.domain || '/users/' || prof.username\n            ) AS actor_uri,\n            COALESCE(prof.display_name, prof.username) AS actor_name,\n            prof.username AS actor_preferred_username,\n            prof.avatar_url AS actor_icon,\n            reply.in_reply_to AS reply_to_id,\n            reply.conversation_root_id,\n            reply.favorites_count AS likes_count,\n            reply.reblogs_count AS shares_count,\n            reply.replies_count,\n            reply.created_at AS published_at,\n            reply.updated_at,\n            ct.depth + 1,\n            ct.path || '.' || LPAD(ROW_NUMBER() OVER (ORDER BY reply.created_at)::TEXT, 10, '0')\n        FROM posts reply\n        LEFT JOIN profiles prof ON reply.author_id = prof.id\n        INNER JOIN conversation_thread ct ON reply.in_reply_to = ct.id\n        WHERE ct.depth < 20\n            AND reply.deleted_at IS NULL\n    )\n    SELECT \n        ct.id,\n        ct.uri,\n        ct.content,\n        ct.content_type,\n        ct.actor_uri,\n        ct.actor_name,\n        ct.actor_preferred_username,\n        ct.actor_icon,\n        ct.reply_to_id,\n        ct.conversation_root_id,\n        ct.likes_count,\n        ct.shares_count,\n        ct.replies_count,\n        ct.published_at,\n        ct.updated_at,\n        ct.depth,\n        ct.path\n    FROM conversation_thread ct\n    ORDER BY ct.path;\nEND;\n$function$\n"
    }
  },
  {
    "function_json": {
      "function_name": "get_batch_message_reactions",
      "return_type": "record",
      "arguments": "message_ids uuid[]",
      "definition": "CREATE OR REPLACE FUNCTION public.get_batch_message_reactions(message_ids uuid[])\n RETURNS TABLE(message_id uuid, emoji_id uuid, emoji_name character varying, emoji_url character varying, reaction_count bigint, users jsonb)\n LANGUAGE plpgsql\n STABLE\nAS $function$\nBEGIN\n    RETURN QUERY\n    SELECT \n        r.message_id,\n        r.emoji_id,\n        e.name as emoji_name,  -- No cast needed - already character varying\n        e.url as emoji_url,    -- No cast needed - already character varying\n        COUNT(r.user_id) as reaction_count,  -- Match existing function behavior\n        COALESCE(\n            jsonb_agg(\n                jsonb_build_object(\n                    'reaction_id', r.id::text,\n                    'user_id', r.user_id::text\n                ) ORDER BY r.created_at\n            ) FILTER (WHERE r.user_id IS NOT NULL),\n            '[]'::jsonb\n        ) as users\n    FROM reactions r\n    LEFT JOIN emojis e ON r.emoji_id = e.id\n    WHERE r.message_id = ANY(get_batch_message_reactions.message_ids)\n    GROUP BY r.message_id, r.emoji_id, e.name, e.url\n    ORDER BY r.message_id, MIN(r.created_at);\nEND;\n$function$\n"
    }
  },
  {
    "function_json": {
      "function_name": "get_batch_post_reactions",
      "return_type": "record",
      "arguments": "post_ids uuid[]",
      "definition": "CREATE OR REPLACE FUNCTION public.get_batch_post_reactions(post_ids uuid[])\n RETURNS TABLE(post_id uuid, emoji_id uuid, emoji_name character varying, emoji_url character varying, reaction_count bigint, users jsonb)\n LANGUAGE plpgsql\n STABLE\nAS $function$\nBEGIN\n    RETURN QUERY\n    SELECT \n        pi.post_id,\n        pi.emoji_id,\n        e.name as emoji_name,\n        e.url as emoji_url,\n        COUNT(pi.user_id) as reaction_count,\n        jsonb_agg(\n            jsonb_build_object(\n                'id', p.id,\n                'username', p.username,\n                'display_name', p.display_name,\n                'avatar_url', p.avatar_url\n            ) ORDER BY pi.created_at\n        ) as users\n    FROM post_interactions pi\n    INNER JOIN emojis e ON pi.emoji_id = e.id\n    INNER JOIN profiles p ON pi.user_id = p.id\n    WHERE pi.post_id = ANY(post_ids)\n    AND pi.interaction_type = 'emoji_reaction'\n    GROUP BY pi.post_id, pi.emoji_id, e.name, e.url\n    ORDER BY pi.post_id, MIN(pi.created_at);\nEND;\n$function$\n"
    }
  },
  {
    "function_json": {
      "function_name": "get_cached_timeline",
      "return_type": "jsonb",
      "arguments": "p_user_id uuid, p_timeline_type text DEFAULT 'home'::text, p_limit integer DEFAULT 20",
      "definition": "CREATE OR REPLACE FUNCTION public.get_cached_timeline(p_user_id uuid, p_timeline_type text DEFAULT 'home'::text, p_limit integer DEFAULT 20)\n RETURNS jsonb\n LANGUAGE plpgsql\nAS $function$\nDECLARE\n  cached_posts jsonb;\nBEGIN\n  -- Get from cache\n  SELECT posts_data \n  INTO cached_posts\n  FROM user_timeline_cache \n  WHERE user_id = p_user_id \n    AND timeline_type = p_timeline_type;\n  \n  -- Return limited posts\n  IF cached_posts IS NOT NULL THEN\n    RETURN jsonb_build_object(\n      'posts', (\n        SELECT jsonb_agg(post_data)\n        FROM (\n          SELECT value as post_data\n          FROM jsonb_array_elements(cached_posts) \n          LIMIT p_limit\n        ) limited_posts\n      ),\n      'cached', true,\n      'count', jsonb_array_length(cached_posts)\n    );\n  END IF;\n  \n  -- Return empty if no cache\n  RETURN jsonb_build_object('posts', '[]'::jsonb, 'cached', false);\nEND;\n$function$\n"
    }
  },
  {
    "function_json": {
      "function_name": "get_conversation_context",
      "return_type": "jsonb",
      "arguments": "in_post_id uuid, in_user_id uuid",
      "definition": "CREATE OR REPLACE FUNCTION public.get_conversation_context(in_post_id uuid, in_user_id uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\nAS $function$\nDECLARE\n    conversation_root_id uuid;\n    result jsonb;\nBEGIN\n    -- Get the conversation root ID for this post\n    SELECT COALESCE(p.conversation_root_id, p.id)\n    INTO conversation_root_id\n    FROM posts p\n    WHERE p.id = in_post_id\n      AND p.deleted_at IS NULL;\n    \n    -- If post not found, return empty object\n    IF conversation_root_id IS NULL THEN\n        RETURN '{}'::jsonb;\n    END IF;\n    \n    -- Get all posts in conversation ordered chronologically\n    WITH conversation_posts AS (\n        SELECT \n            p.id,\n            p.content,\n            p.created_at,\n            p.in_reply_to,\n            jsonb_build_object(\n                'id', pr.id,\n                'username', pr.username,\n                'display_name', pr.display_name,\n                'avatar_url', pr.avatar_url,\n                'domain', pr.domain\n            ) as author,\n            p.visibility,\n            p.favorites_count,\n            p.reblogs_count,\n            p.replies_count,\n            p.media_attachments,\n            p.content_warning,\n            p.is_sensitive,\n            p.url,\n            CASE \n                WHEN pi_fav.user_id IS NOT NULL THEN true \n                ELSE false \n            END as is_favorited,\n            CASE \n                WHEN pi_reb.user_id IS NOT NULL THEN true \n                ELSE false \n            END as is_reblogged,\n            CASE \n                WHEN pi_book.user_id IS NOT NULL THEN true \n                ELSE false \n            END as is_bookmarked\n        FROM posts p\n        JOIN profiles pr ON p.author_id = pr.id\n        LEFT JOIN post_interactions pi_fav ON p.id = pi_fav.post_id \n            AND pi_fav.user_id = in_user_id \n            AND pi_fav.interaction_type = 'favorite'\n        LEFT JOIN post_interactions pi_reb ON p.id = pi_reb.post_id \n            AND pi_reb.user_id = in_user_id \n            AND pi_reb.interaction_type = 'reblog'\n        LEFT JOIN post_interactions pi_book ON p.id = pi_book.post_id \n            AND pi_book.user_id = in_user_id \n            AND pi_book.interaction_type = 'bookmark'\n        WHERE COALESCE(p.conversation_root_id, p.id) = conversation_root_id\n          AND p.deleted_at IS NULL\n        ORDER BY p.created_at ASC\n    )\n    SELECT jsonb_build_object(\n        'ancestors', COALESCE(jsonb_agg(\n            jsonb_build_object(\n                'id', cp.id,\n                'content', cp.content,\n                'created_at', cp.created_at,\n                'author', cp.author,\n                'visibility', cp.visibility,\n                'favorites_count', cp.favorites_count,\n                'reblogs_count', cp.reblogs_count,\n                'replies_count', cp.replies_count,\n                'media_attachments', cp.media_attachments,\n                'content_warning', cp.content_warning,\n                'is_sensitive', cp.is_sensitive,\n                'url', cp.url,\n                'is_favorited', cp.is_favorited,\n                'is_reblogged', cp.is_reblogged,\n                'is_bookmarked', cp.is_bookmarked\n            )\n        ) FILTER (WHERE cp.created_at < (SELECT created_at FROM posts WHERE id = in_post_id)), '[]'::jsonb),\n        'descendants', COALESCE(jsonb_agg(\n            jsonb_build_object(\n                'id', cp.id,\n                'content', cp.content,\n                'created_at', cp.created_at,\n                'author', cp.author,\n                'visibility', cp.visibility,\n                'favorites_count', cp.favorites_count,\n                'reblogs_count', cp.reblogs_count,\n                'replies_count', cp.replies_count,\n                'media_attachments', cp.media_attachments,\n                'content_warning', cp.content_warning,\n                'is_sensitive', cp.is_sensitive,\n                'url', cp.url,\n                'is_favorited', cp.is_favorited,\n                'is_reblogged', cp.is_reblogged,\n                'is_bookmarked', cp.is_bookmarked\n            )\n        ) FILTER (WHERE cp.created_at > (SELECT created_at FROM posts WHERE id = in_post_id)), '[]'::jsonb),\n        'conversation_id', conversation_root_id\n    ) INTO result\n    FROM conversation_posts cp;\n    \n    RETURN COALESCE(result, jsonb_build_object(\n        'ancestors', '[]'::jsonb,\n        'descendants', '[]'::jsonb,\n        'conversation_id', conversation_root_id\n    ));\nEND;\n$function$\n"
    }
  },
  {
    "function_json": {
      "function_name": "get_conversation_participants",
      "return_type": "record",
      "arguments": "conversation_uuid uuid",
      "definition": "CREATE OR REPLACE FUNCTION public.get_conversation_participants(conversation_uuid uuid)\n RETURNS TABLE(user_id uuid, role text, joined_at timestamp with time zone, is_muted boolean, last_read_at timestamp with time zone)\n LANGUAGE sql\n STABLE\nAS $function$\n  SELECT \n    cp.user_id,\n    cp.role,\n    cp.joined_at,\n    cp.is_muted,\n    cp.last_read_at\n  FROM conversation_participants cp\n  WHERE cp.conversation_id = conversation_uuid \n    AND cp.left_at IS NULL\n  ORDER BY cp.joined_at;\n$function$\n"
    }
  },
  {
    "function_json": {
      "function_name": "get_conversation_thread",
      "return_type": "jsonb",
      "arguments": "p_conversation_id text, p_user_id uuid",
      "definition": "CREATE OR REPLACE FUNCTION public.get_conversation_thread(p_conversation_id text, p_user_id uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\nAS $function$\nDECLARE\n  root_post jsonb;\n  thread_posts jsonb;\n  reply_count integer;\n  participant_count integer;\n  last_updated timestamptz;\nBEGIN\n  -- Get the root post (the one that started the conversation)\n  SELECT to_jsonb(tp.*) INTO root_post\n  FROM timeline_posts tp\n  WHERE tp.conversation_id = p_conversation_id\n    AND tp.reply_context IS NULL\n  ORDER BY tp.created_at ASC\n  LIMIT 1;\n  \n  -- Get all posts in the conversation with user interaction state\n  SELECT jsonb_agg(\n    jsonb_build_object(\n      'id', tp.id,\n      'content', tp.content,\n      'author', tp.author,\n      'created_at', tp.created_at,\n      'reply_context', tp.reply_context,\n      'replies_count', tp.replies_count,\n      'reblogs_count', tp.reblogs_count,\n      'favorites_count', tp.favorites_count,\n      'is_favorited', COALESCE(fav.user_id IS NOT NULL, false),\n      'is_reblogged', COALESCE(reb.user_id IS NOT NULL, false),\n      'is_bookmarked', COALESCE(book.user_id IS NOT NULL, false)\n    ) ORDER BY tp.created_at ASC\n  ) INTO thread_posts\n  FROM timeline_posts tp\n  LEFT JOIN post_interactions fav ON tp.id = fav.post_id \n    AND fav.user_id = p_user_id AND fav.interaction_type = 'favorite'\n  LEFT JOIN post_interactions reb ON tp.id = reb.post_id \n    AND reb.user_id = p_user_id AND reb.interaction_type = 'reblog'\n  LEFT JOIN post_interactions book ON tp.id = book.post_id \n    AND book.user_id = p_user_id AND book.interaction_type = 'bookmark'\n  WHERE tp.conversation_id = p_conversation_id;\n  \n  -- Get conversation stats\n  SELECT \n    COUNT(*) - 1, -- Subtract 1 for root post\n    COUNT(DISTINCT tp.author_id),\n    MAX(tp.created_at)\n  INTO reply_count, participant_count, last_updated\n  FROM timeline_posts tp\n  WHERE tp.conversation_id = p_conversation_id;\n  \n  RETURN jsonb_build_object(\n    'root_post', root_post,\n    'posts', COALESCE(thread_posts, '[]'::jsonb),\n    'reply_count', COALESCE(reply_count, 0),\n    'participant_count', COALESCE(participant_count, 0),\n    'last_updated', last_updated\n  );\nEND;\n$function$\n"
    }
  },
  {
    "function_json": {
      "function_name": "get_default_channel",
      "return_type": "uuid",
      "arguments": "p_server_id uuid",
      "definition": "CREATE OR REPLACE FUNCTION public.get_default_channel(p_server_id uuid)\n RETURNS uuid\n LANGUAGE plpgsql\n SECURITY DEFINER\nAS $function$\nDECLARE\n    channel_id UUID;\nBEGIN\n    -- Get the first text channel (type 0) named 'general' or the first text channel\n    SELECT id INTO channel_id\n    FROM channels \n    WHERE server_id = p_server_id \n      AND type = 0 \n    ORDER BY \n        CASE WHEN name = 'general' THEN 0 ELSE 1 END,\n        \"order\" ASC,\n        created_at ASC\n    LIMIT 1;\n    \n    RETURN channel_id;\nEND;\n$function$\n"
    }
  },
  {
    "function_json": {
      "function_name": "get_emoji_metadata_bulk",
      "return_type": "record",
      "arguments": "server_ids uuid[]",
      "definition": "CREATE OR REPLACE FUNCTION public.get_emoji_metadata_bulk(server_ids uuid[])\n RETURNS TABLE(server_id uuid, last_modified timestamp with time zone, emoji_count integer)\n LANGUAGE plpgsql\nAS $function$\nBEGIN\n    RETURN QUERY\n    SELECT \n        e.server_id,\n        COALESCE(MAX(e.updated_at), MAX(e.created_at)) as last_modified,\n        COUNT(e.id)::integer as emoji_count\n    FROM emojis e\n    WHERE e.server_id = ANY(server_ids)\n    GROUP BY e.server_id;\nEND;\n$function$\n"
    }
  },
  {
    "function_json": {
      "function_name": "get_emoji_usage_analytics",
      "return_type": "record",
      "arguments": "p_server_id uuid, p_user_id uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 10",
      "definition": "CREATE OR REPLACE FUNCTION public.get_emoji_usage_analytics(p_server_id uuid, p_user_id uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 10)\n RETURNS TABLE(emoji_id uuid, emoji_name text, emoji_url text, total_uses bigint, unique_users bigint, user_uses bigint, last_used timestamp with time zone, message_uses bigint, reaction_uses bigint)\n LANGUAGE plpgsql\nAS $function$\nBEGIN\n    RETURN QUERY\n    SELECT \n        e.id as emoji_id,\n        e.name as emoji_name,\n        e.url as emoji_url,\n        COUNT(eu.*) as total_uses,\n        COUNT(DISTINCT eu.user_id) as unique_users,\n        CASE \n            WHEN p_user_id IS NOT NULL THEN \n                COUNT(CASE WHEN eu.user_id = p_user_id THEN 1 END)\n            ELSE 0 \n        END as user_uses,\n        MAX(eu.used_at) as last_used,\n        COUNT(CASE WHEN eu.context_type = 'message' THEN 1 END) as message_uses,\n        COUNT(CASE WHEN eu.context_type = 'reaction' THEN 1 END) as reaction_uses\n    FROM emojis e\n    LEFT JOIN emoji_usage eu ON e.id = eu.emoji_id\n    WHERE e.server_id = p_server_id\n    GROUP BY e.id, e.name, e.url\n    ORDER BY total_uses DESC, unique_users DESC\n    LIMIT p_limit;\nEND;\n$function$\n"
    }
  },
  {
    "function_json": {
      "function_name": "get_enhanced_timeline_posts",
      "return_type": "record",
      "arguments": "p_user_id uuid, p_timeline_type text DEFAULT 'home'::text, p_limit integer DEFAULT 20, p_max_id text DEFAULT NULL::text",
      "definition": "CREATE OR REPLACE FUNCTION public.get_enhanced_timeline_posts(p_user_id uuid, p_timeline_type text DEFAULT 'home'::text, p_limit integer DEFAULT 20, p_max_id text DEFAULT NULL::text)\n RETURNS TABLE(id text, created_at timestamp with time zone, updated_at timestamp with time zone, content jsonb, content_warning text, language text, author_id text, ap_id text, ap_type text, url text, reply_context jsonb, conversation_id text, visibility text, is_local boolean, is_federated boolean, replies_count integer, reblogs_count integer, favorites_count integer, media_attachments jsonb, metadata jsonb, is_sensitive boolean, is_deleted boolean, deleted_at timestamp with time zone, author jsonb, is_favorited boolean, is_reblogged boolean, is_bookmarked boolean, reblog jsonb, reblog_author jsonb)\n LANGUAGE plpgsql\nAS $function$\nBEGIN\n    RETURN QUERY\n    SELECT \n        tp.id::TEXT,\n        tp.created_at,\n        tp.updated_at,\n        tp.content,\n        tp.content_warning,\n        'en'::TEXT as language,\n        (tp.author->>'id')::TEXT as author_id,\n        p.ap_id::TEXT,\n        COALESCE(p.ap_type, 'Note')::TEXT as ap_type,\n        tp.url,\n        tp.reply_context,\n        tp.conversation_id::TEXT,\n        tp.visibility,\n        (tp.author->>'is_local')::BOOLEAN as is_local,\n        NOT (tp.author->>'is_local')::BOOLEAN as is_federated,\n        tp.replies_count,\n        tp.reblogs_count,\n        tp.favorites_count,\n        tp.media_attachments,\n        COALESCE(p.metadata, '{}'::JSONB) as metadata,\n        tp.is_sensitive,\n        COALESCE(p.is_deleted, false) as is_deleted,\n        p.deleted_at,\n        tp.author,\n        \n        -- User interaction states\n        COALESCE(fav.user_id IS NOT NULL, false) as is_favorited,\n        COALESCE(reb.user_id IS NOT NULL, false) as is_reblogged,\n        COALESCE(book.user_id IS NOT NULL, false) as is_bookmarked,\n        \n        -- Reblog fields\n        tp.reblog,\n        tp.reblog_author\n        \n    FROM timeline_posts tp\n    JOIN posts p ON tp.id = p.id\n    LEFT JOIN post_interactions fav ON tp.id = fav.post_id \n        AND fav.user_id = p_user_id \n        AND fav.interaction_type = 'favorite'\n    LEFT JOIN post_interactions reb ON tp.id = reb.post_id \n        AND reb.user_id = p_user_id \n        AND reb.interaction_type = 'reblog'\n    LEFT JOIN post_interactions book ON tp.id = book.post_id \n        AND book.user_id = p_user_id \n        AND book.interaction_type = 'bookmark'\n    \n    WHERE \n        CASE \n            -- HOME: Use timeline_entries for proper following logic\n            WHEN p_timeline_type = 'home' THEN \n                EXISTS (\n                    SELECT 1 FROM timeline_entries te \n                    WHERE te.user_id = p_user_id \n                      AND te.post_id = tp.id \n                      AND te.timeline_type = 'home'\n                )\n            \n            -- LOCAL: Only public posts from local users\n            WHEN p_timeline_type = 'local' THEN \n                tp.visibility = 'public' \n                AND (tp.author->>'is_local')::BOOLEAN = true\n            \n            -- PUBLIC/FEDERATED: All public posts (local + remote) - standard ActivityPub timeline\n            WHEN p_timeline_type IN ('public', 'federated') THEN \n                tp.visibility = 'public'\n                \n            ELSE tp.visibility = 'public'\n        END\n        \n        -- Pagination\n        AND (p_max_id IS NULL OR tp.created_at < (\n            SELECT tp2.created_at FROM timeline_posts tp2 WHERE tp2.id = p_max_id::UUID\n        ))\n    \n    ORDER BY tp.created_at DESC\n    LIMIT p_limit;\nEND;\n$function$\n"
    }
  },
  {
    "function_json": {
      "function_name": "get_featured_posts_hybrid",
      "return_type": "record",
      "arguments": "p_author_id uuid, p_limit integer DEFAULT 10",
      "definition": "CREATE OR REPLACE FUNCTION public.get_featured_posts_hybrid(p_author_id uuid, p_limit integer DEFAULT 10)\n RETURNS TABLE(id uuid, content jsonb, created_at timestamp with time zone, updated_at timestamp with time zone, author_id uuid, engagement_count integer, replies_count integer, is_pinned boolean, ap_id text, ap_type text, visibility text, media_attachments jsonb, content_warning text, in_reply_to uuid, favorites_count integer, reblogs_count integer)\n LANGUAGE plpgsql\nAS $function$\nDECLARE\n    pinned_count INT;\n    remaining_limit INT;\nBEGIN\n    -- First, get pinned posts\n    RETURN QUERY\n    SELECT \n        p.id, p.content, p.created_at, p.updated_at, p.author_id,\n        (p.favorites_count + p.reblogs_count + p.replies_count) as engagement_count,\n        p.replies_count, p.is_pinned,\n        p.ap_id, p.ap_type, p.visibility, p.media_attachments,\n        p.content_warning, p.in_reply_to, p.favorites_count, p.reblogs_count\n    FROM posts p\n    WHERE p.author_id = p_author_id \n        AND p.is_pinned = true\n        AND p.is_deleted = false\n        AND p.visibility IN ('public', 'unlisted')\n    ORDER BY p.created_at DESC\n    LIMIT p_limit;\n\n    -- Count how many pinned posts we got\n    GET DIAGNOSTICS pinned_count = ROW_COUNT;\n    remaining_limit := p_limit - pinned_count;\n\n    -- If we have room for more, add popular posts\n    IF remaining_limit > 0 THEN\n        RETURN QUERY\n        SELECT \n            p.id, p.content, p.created_at, p.updated_at, p.author_id,\n            (p.favorites_count + p.reblogs_count + p.replies_count) as engagement_count,\n            p.replies_count, p.is_pinned,\n            p.ap_id, p.ap_type, p.visibility, p.media_attachments,\n            p.content_warning, p.in_reply_to, p.favorites_count, p.reblogs_count\n        FROM posts p\n        WHERE p.author_id = p_author_id \n            AND p.is_pinned = false\n            AND p.is_deleted = false\n            AND p.visibility IN ('public', 'unlisted')\n            AND (p.favorites_count + p.reblogs_count + p.replies_count) > 0\n        ORDER BY (p.favorites_count + p.reblogs_count + p.replies_count) DESC, p.created_at DESC\n        LIMIT remaining_limit;\n    END IF;\nEND;\n$function$\n"
    }
  },
  {
    "function_json": {
      "function_name": "get_federation_config",
      "return_type": "jsonb",
      "arguments": "",
      "definition": "CREATE OR REPLACE FUNCTION public.get_federation_config()\n RETURNS jsonb\n LANGUAGE plpgsql\n STABLE\nAS $function$\nDECLARE\n    config jsonb;\nBEGIN\n    SELECT config_value INTO config\n    FROM instance_config \n    WHERE config_key = 'federation_settings';\n    \n    -- Return defaults if no config exists\n    IF config IS NULL THEN\n        config := jsonb_build_object(\n            'federation_enabled', true,\n            'federation_auto_accept_follows', true,\n            'federation_require_approval', false,\n            'federation_max_delivery_attempts', 5,\n            'federation_delivery_timeout_ms', 10000\n        );\n    END IF;\n    \n    RETURN config;\nEND;\n$function$\n"
    }
  },
  {
    "function_json": {
      "function_name": "get_federation_stats",
      "return_type": "json",
      "arguments": "",
      "definition": "CREATE OR REPLACE FUNCTION public.get_federation_stats()\n RETURNS json\n LANGUAGE plpgsql\n SECURITY DEFINER\nAS $function$\nDECLARE\n    result JSON;\n    pending_deliveries INTEGER;\n    failed_deliveries INTEGER;\n    successful_deliveries_today INTEGER;\nBEGIN\n    -- Get pending deliveries (if federation_delivery_queue exists)\n    SELECT COUNT(*) INTO pending_deliveries \n    FROM federation_delivery_queue \n    WHERE status = 'pending' OR status = 'retrying';\n    \n    -- Get failed deliveries\n    SELECT COUNT(*) INTO failed_deliveries \n    FROM federation_delivery_queue \n    WHERE status = 'failed';\n    \n    -- Get successful deliveries today\n    SELECT COUNT(*) INTO successful_deliveries_today \n    FROM federation_delivery_queue \n    WHERE status = 'delivered' \n    AND delivered_at >= CURRENT_DATE;\n    \n    result := json_build_object(\n        'pending', COALESCE(pending_deliveries, 0),\n        'failed', COALESCE(failed_deliveries, 0),\n        'successfulToday', COALESCE(successful_deliveries_today, 0)\n    );\n    \n    RETURN result;\nEXCEPTION WHEN undefined_table THEN\n    -- If federation_delivery_queue doesn't exist, return default values\n    result := json_build_object(\n        'pending', 0,\n        'failed', 0,\n        'successfulToday', 0\n    );\n    RETURN result;\nEND;\n$function$\n"
    }
  },
  {
    "function_json": {
      "function_name": "get_follow_status",
      "return_type": "record",
      "arguments": "current_user_id uuid, target_user_id uuid",
      "definition": "CREATE OR REPLACE FUNCTION public.get_follow_status(current_user_id uuid, target_user_id uuid)\n RETURNS TABLE(is_following boolean, is_followed_by boolean, follow_status text, followed_by_status text)\n LANGUAGE plpgsql\n SECURITY DEFINER\nAS $function$\nBEGIN\n    RETURN QUERY\n    SELECT \n        -- Is current user following target user?\n        EXISTS(\n            SELECT 1 FROM follows \n            WHERE follower_id = current_user_id \n            AND following_id = target_user_id \n            AND status = 'accepted'\n        ) as is_following,\n        \n        -- Is current user followed by target user?\n        EXISTS(\n            SELECT 1 FROM follows \n            WHERE follower_id = target_user_id \n            AND following_id = current_user_id \n            AND status = 'accepted'\n        ) as is_followed_by,\n        \n        -- Follow request status (outgoing)\n        COALESCE(\n            (SELECT status FROM follows \n             WHERE follower_id = current_user_id \n             AND following_id = target_user_id \n             LIMIT 1), \n            'none'\n        ) as follow_status,\n        \n        -- Follow request status (incoming)\n        COALESCE(\n            (SELECT status FROM follows \n             WHERE follower_id = target_user_id \n             AND following_id = current_user_id \n             LIMIT 1), \n            'none'\n        ) as followed_by_status;\nEND;\n$function$\n"
    }
  },
  {
    "function_json": {
      "function_name": "get_instance_config",
      "return_type": "record",
      "arguments": "p_key text DEFAULT NULL::text",
      "definition": "CREATE OR REPLACE FUNCTION public.get_instance_config(p_key text DEFAULT NULL::text)\n RETURNS TABLE(config_key text, config_value jsonb, description text)\n LANGUAGE plpgsql\n SECURITY DEFINER\nAS $function$\nBEGIN\n    IF p_key IS NOT NULL THEN\n        RETURN QUERY\n        SELECT ic.config_key, ic.config_value, ic.description\n        FROM instance_config ic\n        WHERE ic.config_key = p_key;\n    ELSE\n        RETURN QUERY\n        SELECT ic.config_key, ic.config_value, ic.description\n        FROM instance_config ic\n        ORDER BY ic.config_key;\n    END IF;\nEND;\n$function$\n"
    }
  },
  {
    "function_json": {
      "function_name": "get_instance_domain",
      "return_type": "text",
      "arguments": "",
      "definition": "CREATE OR REPLACE FUNCTION public.get_instance_domain()\n RETURNS text\n LANGUAGE plpgsql\n SECURITY DEFINER\nAS $function$\nDECLARE\n    domain_value text;\nBEGIN\n    -- Get domain from instance_config\n    SELECT trim(both '\"' from config_value::text) INTO domain_value\n    FROM instance_config \n    WHERE config_key = 'domain';\n    \n    -- Return domain or fallback\n    RETURN COALESCE(domain_value, 'localhost');\nEND;\n$function$\n"
    }
  },
  {
    "function_json": {
      "function_name": "get_message_reactions",
      "return_type": "record",
      "arguments": "message_id uuid",
      "definition": "CREATE OR REPLACE FUNCTION public.get_message_reactions(message_id uuid)\n RETURNS TABLE(count bigint, emoji jsonb, reactions jsonb, message_id_of_reactions uuid)\n LANGUAGE plpgsql\nAS $function$\nBEGIN\n    RETURN QUERY\n    SELECT \n        COUNT(r.*) as count,\n        to_jsonb(e.*) as emoji,\n        COALESCE(\n            jsonb_agg(\n                jsonb_build_object(\n                    'reaction_id', r.id::text,\n                    'user_id', r.user_id::text\n                ) ORDER BY r.created_at\n            ) FILTER (WHERE r.user_id IS NOT NULL),\n            '[]'::jsonb\n        ) as reactions,\n        get_message_reactions.message_id as message_id_of_reactions\n    FROM reactions r\n    LEFT JOIN emojis e ON r.emoji_id = e.id\n    WHERE r.message_id = get_message_reactions.message_id\n    GROUP BY r.emoji_id, e.id, r.message_id\n    ORDER BY MIN(r.created_at);\nEND;\n$function$\n"
    }
  },
  {
    "function_json": {
      "function_name": "get_most_used_emojis",
      "return_type": "record",
      "arguments": "server_ids uuid[] DEFAULT NULL::uuid[], limit_count integer DEFAULT 100",
      "definition": "CREATE OR REPLACE FUNCTION public.get_most_used_emojis(server_ids uuid[] DEFAULT NULL::uuid[], limit_count integer DEFAULT 100)\n RETURNS TABLE(emoji_id uuid, server_id uuid, name text, url text, usage_count integer, last_used timestamp with time zone)\n LANGUAGE plpgsql\nAS $function$\nBEGIN\n    RETURN QUERY\n    SELECT \n        e.id as emoji_id,\n        e.server_id,\n        e.name,\n        e.url,\n        e.usage_count,\n        e.last_used\n    FROM emojis e\n    WHERE \n        CASE \n            WHEN server_ids IS NOT NULL THEN e.server_id = ANY(server_ids)\n            ELSE TRUE\n        END\n    ORDER BY e.usage_count DESC, e.last_used DESC NULLS LAST\n    LIMIT limit_count;\nEND;\n$function$\n"
    }
  },
  {
    "function_json": {
      "function_name": "get_or_create_conversation",
      "return_type": "uuid",
      "arguments": "participant1_id uuid, participant2_id uuid",
      "definition": "CREATE OR REPLACE FUNCTION public.get_or_create_conversation(participant1_id uuid, participant2_id uuid)\n RETURNS uuid\n LANGUAGE plpgsql\n SECURITY DEFINER\nAS $function$\nDECLARE\n    conversation_id uuid;\n    authenticated_user_id uuid;\nBEGIN\n    -- Get the authenticated user ID\n    authenticated_user_id := auth.uid();\n    \n    -- Ensure the authenticated user is one of the participants\n    IF authenticated_user_id IS NULL OR \n       (authenticated_user_id != participant1_id AND authenticated_user_id != participant2_id) THEN\n        RAISE EXCEPTION 'Access denied: user must be a participant in the conversation';\n    END IF;\n    \n    -- Ensure both participants exist in profiles\n    IF NOT EXISTS (SELECT 1 FROM public.profiles WHERE id = participant1_id) THEN\n        RAISE EXCEPTION 'Participant 1 does not exist in profiles';\n    END IF;\n    \n    IF NOT EXISTS (SELECT 1 FROM public.profiles WHERE id = participant2_id) THEN\n        RAISE EXCEPTION 'Participant 2 does not exist in profiles';\n    END IF;\n    \n    -- UPDATED: Try to find existing conversation using participant system\n    SELECT c.id INTO conversation_id\n    FROM conversations c\n    WHERE c.type = 'direct'\n      AND EXISTS (\n        SELECT 1 FROM conversation_participants cp1\n        WHERE cp1.conversation_id = c.id \n          AND cp1.user_id = participant1_id \n          AND cp1.left_at IS NULL\n      )\n      AND EXISTS (\n        SELECT 1 FROM conversation_participants cp2\n        WHERE cp2.conversation_id = c.id \n          AND cp2.user_id = participant2_id \n          AND cp2.left_at IS NULL\n      )\n      -- Ensure it's exactly 2 participants (direct conversation)\n      AND (\n        SELECT COUNT(*) FROM conversation_participants cp3\n        WHERE cp3.conversation_id = c.id \n          AND cp3.left_at IS NULL\n      ) = 2;\n    \n    -- If no conversation exists, create one using new structure\n    IF conversation_id IS NULL THEN\n        INSERT INTO public.conversations (type, created_by, is_active)\n        VALUES ('direct', participant1_id, TRUE)\n        RETURNING id INTO conversation_id;\n        \n        -- Add both participants\n        INSERT INTO conversation_participants (conversation_id, user_id, role, joined_at)\n        VALUES \n          (conversation_id, participant1_id, 'member', NOW()),\n          (conversation_id, participant2_id, 'member', NOW());\n    END IF;\n    \n    RETURN conversation_id;\nEND;\n$function$\n"
    }
  },
  {
    "function_json": {
      "function_name": "get_or_create_dm_conversation",
      "return_type": "uuid",
      "arguments": "p_user1_id uuid, p_user2_id uuid",
      "definition": "CREATE OR REPLACE FUNCTION public.get_or_create_dm_conversation(p_user1_id uuid, p_user2_id uuid)\n RETURNS uuid\n LANGUAGE plpgsql\n SECURITY DEFINER\nAS $function$\nDECLARE\n  v_conversation_id UUID;\nBEGIN\n  -- Try to find existing conversation between these users\n  SELECT c.id INTO v_conversation_id\n  FROM conversations c\n  WHERE c.type = 'direct'\n    AND EXISTS (\n      SELECT 1 FROM conversation_participants cp1\n      WHERE cp1.conversation_id = c.id \n        AND cp1.user_id = p_user1_id \n        AND cp1.left_at IS NULL\n    )\n    AND EXISTS (\n      SELECT 1 FROM conversation_participants cp2\n      WHERE cp2.conversation_id = c.id \n        AND cp2.user_id = p_user2_id \n        AND cp2.left_at IS NULL\n    )\n    -- Ensure it's exactly 2 participants (direct conversation)\n    AND (\n      SELECT COUNT(*) FROM conversation_participants cp3\n      WHERE cp3.conversation_id = c.id \n        AND cp3.left_at IS NULL\n    ) = 2;\n  \n  -- If not found, create new conversation\n  IF v_conversation_id IS NULL THEN\n    INSERT INTO conversations (type, created_by, is_active)\n    VALUES ('direct', p_user1_id, TRUE)\n    RETURNING id INTO v_conversation_id;\n    \n    -- Add both participants\n    INSERT INTO conversation_participants (conversation_id, user_id, role, joined_at)\n    VALUES \n      (v_conversation_id, p_user1_id, 'member', NOW()),\n      (v_conversation_id, p_user2_id, 'member', NOW());\n      \n    RAISE NOTICE 'Created new DM conversation % between users % and %', \n      v_conversation_id, p_user1_id, p_user2_id;\n  END IF;\n  \n  RETURN v_conversation_id;\nEND;\n$function$\n"
    }
  },
  {
    "function_json": {
      "function_name": "get_post_emoji_reactions",
      "return_type": "record",
      "arguments": "p_post_id uuid",
      "definition": "CREATE OR REPLACE FUNCTION public.get_post_emoji_reactions(p_post_id uuid)\n RETURNS TABLE(emoji_id uuid, emoji_name text, emoji_url text, custom_emoji_content text, reaction_count bigint, user_reactions jsonb)\n LANGUAGE plpgsql\n STABLE\nAS $function$\nBEGIN\n    RETURN QUERY\n    SELECT \n        pi.emoji_id,\n        e.name as emoji_name,\n        e.url as emoji_url,\n        pi.custom_emoji_content,\n        COUNT(*)::bigint as reaction_count,\n        jsonb_agg(\n            jsonb_build_object(\n                'user_id', pi.user_id,\n                'created_at', pi.created_at\n            )\n        ) as user_reactions\n    FROM post_interactions pi\n    LEFT JOIN emojis e ON pi.emoji_id = e.id\n    WHERE pi.post_id = p_post_id \n      AND pi.interaction_type = 'emoji_reaction'\n    GROUP BY pi.emoji_id, e.name, e.url, pi.custom_emoji_content\n    ORDER BY reaction_count DESC;\nEND;\n$function$\n"
    }
  },
  {
    "function_json": {
      "function_name": "get_post_replies",
      "return_type": "jsonb",
      "arguments": "p_post_id uuid, p_user_id uuid, p_limit integer DEFAULT 20, p_max_id text DEFAULT NULL::text",
      "definition": "CREATE OR REPLACE FUNCTION public.get_post_replies(p_post_id uuid, p_user_id uuid, p_limit integer DEFAULT 20, p_max_id text DEFAULT NULL::text)\n RETURNS jsonb\n LANGUAGE plpgsql\nAS $function$\nDECLARE\n  result jsonb;\nBEGIN\n  SELECT jsonb_agg(\n    jsonb_build_object(\n      'id', tp.id,\n      'created_at', tp.created_at,\n      'content', tp.content,\n      'author', tp.author,\n      'reply_context', tp.reply_context,\n      'conversation_id', tp.conversation_id,\n      'visibility', tp.visibility,\n      'replies_count', tp.replies_count,\n      'reblogs_count', tp.reblogs_count,\n      'favorites_count', tp.favorites_count,\n      'media_attachments', tp.media_attachments,\n      'is_sensitive', tp.is_sensitive,\n      'content_warning', tp.content_warning,\n      'is_favorited', COALESCE(fav.user_id IS NOT NULL, false),\n      'is_reblogged', COALESCE(reb.user_id IS NOT NULL, false),\n      'is_bookmarked', COALESCE(book.user_id IS NOT NULL, false)\n    ) ORDER BY tp.created_at ASC\n  ) INTO result\n  FROM timeline_posts tp\n  LEFT JOIN post_interactions fav ON tp.id = fav.post_id \n    AND fav.user_id = p_user_id AND fav.interaction_type = 'favorite'\n  LEFT JOIN post_interactions reb ON tp.id = reb.post_id \n    AND reb.user_id = p_user_id AND reb.interaction_type = 'reblog'\n  LEFT JOIN post_interactions book ON tp.id = book.post_id \n    AND book.user_id = p_user_id AND book.interaction_type = 'bookmark'\n  WHERE tp.reply_context->>'id' = p_post_id::text\n    AND (p_max_id IS NULL OR tp.created_at > p_max_id::timestamptz)\n  ORDER BY tp.created_at ASC\n  LIMIT p_limit;\n  \n  RETURN COALESCE(result, '[]'::jsonb);\nEND;\n$function$\n"
    }
  },
  {
    "function_json": {
      "function_name": "get_public_federation_settings",
      "return_type": "jsonb",
      "arguments": "",
      "definition": "CREATE OR REPLACE FUNCTION public.get_public_federation_settings()\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\nAS $function$\nDECLARE\n    federation_settings jsonb;\nBEGIN\n    -- Get federation settings from instance_config\n    SELECT config_value INTO federation_settings\n    FROM instance_config \n    WHERE config_key = 'federation_settings';\n    \n    -- Return safe subset of federation settings (no sensitive data)\n    IF federation_settings IS NULL THEN\n        RETURN jsonb_build_object(\n            'federation_enabled', true,\n            'federation_auto_accept_follows', true\n        );\n    END IF;\n    \n    -- Return only public federation settings\n    RETURN jsonb_build_object(\n        'federation_enabled', COALESCE((federation_settings->>'federation_enabled')::boolean, true),\n        'federation_auto_accept_follows', COALESCE((federation_settings->>'federation_auto_accept_follows')::boolean, true)\n    );\nEND;\n$function$\n"
    }
  },
  {
    "function_json": {
      "function_name": "get_public_instance_info",
      "return_type": "jsonb",
      "arguments": "",
      "definition": "CREATE OR REPLACE FUNCTION public.get_public_instance_info()\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\nAS $function$\nDECLARE\n    instance_name text;\n    instance_description text;\n    domain_value text;\n    open_registration boolean;\n    approval_required boolean;\nBEGIN\n    -- Get various config values\n    SELECT trim(both '\"' from config_value::text) INTO instance_name\n    FROM instance_config WHERE config_key = 'instance_name';\n    \n    SELECT trim(both '\"' from config_value::text) INTO instance_description\n    FROM instance_config WHERE config_key = 'instance_description';\n    \n    SELECT trim(both '\"' from config_value::text) INTO domain_value\n    FROM instance_config WHERE config_key = 'domain';\n    \n    SELECT (config_value)::boolean INTO open_registration\n    FROM instance_config WHERE config_key = 'open_registration';\n    \n    SELECT (config_value)::boolean INTO approval_required\n    FROM instance_config WHERE config_key = 'approval_required';\n    \n    -- Return public instance information\n    RETURN jsonb_build_object(\n        'name', COALESCE(instance_name, 'Harmony Instance'),\n        'description', COALESCE(instance_description, 'A federated social platform'),\n        'domain', COALESCE(domain_value, 'localhost'),\n        'open_registration', COALESCE(open_registration, true),\n        'approval_required', COALESCE(approval_required, false)\n    );\nEND;\n$function$\n"
    }
  },
  {
    "function_json": {
      "function_name": "get_recent_admin_activity",
      "return_type": "record",
      "arguments": "p_limit integer DEFAULT 20",
      "definition": "CREATE OR REPLACE FUNCTION public.get_recent_admin_activity(p_limit integer DEFAULT 20)\n RETURNS TABLE(id uuid, admin_username text, action_type text, target_type text, target_id text, action_details jsonb, created_at timestamp with time zone)\n LANGUAGE plpgsql\n SECURITY DEFINER\nAS $function$\nBEGIN\n    RETURN QUERY\n    SELECT \n        aal.id,\n        p.username as admin_username,\n        aal.action_type,\n        aal.target_type,\n        aal.target_id,\n        aal.action_details,\n        aal.created_at\n    FROM admin_audit_log aal\n    JOIN profiles p ON aal.admin_id = p.id\n    ORDER BY aal.created_at DESC\n    LIMIT p_limit;\nEND;\n$function$\n"
    }
  },
  {
    "function_json": {
      "function_name": "get_server_emoji_analytics",
      "return_type": "record",
      "arguments": "target_server_id uuid",
      "definition": "CREATE OR REPLACE FUNCTION public.get_server_emoji_analytics(target_server_id uuid)\n RETURNS TABLE(total_emojis integer, total_usage integer, most_used_emoji_name text, most_used_emoji_count integer, least_used_emoji_name text, least_used_emoji_count integer, average_usage numeric)\n LANGUAGE plpgsql\nAS $function$\nBEGIN\n    RETURN QUERY\n    WITH emoji_stats AS (\n        SELECT \n            COUNT(*) as total_emojis,\n            SUM(usage_count) as total_usage,\n            AVG(usage_count) as avg_usage\n        FROM emojis \n        WHERE server_id = target_server_id\n    ),\n    most_used AS (\n        SELECT name, usage_count\n        FROM emojis \n        WHERE server_id = target_server_id \n        ORDER BY usage_count DESC \n        LIMIT 1\n    ),\n    least_used AS (\n        SELECT name, usage_count\n        FROM emojis \n        WHERE server_id = target_server_id \n        ORDER BY usage_count ASC \n        LIMIT 1\n    )\n    SELECT \n        es.total_emojis::integer,\n        es.total_usage::integer,\n        mu.name as most_used_emoji_name,\n        mu.usage_count::integer as most_used_emoji_count,\n        lu.name as least_used_emoji_name,\n        lu.usage_count::integer as least_used_emoji_count,\n        es.avg_usage::numeric as average_usage\n    FROM emoji_stats es\n    LEFT JOIN most_used mu ON true\n    LEFT JOIN least_used lu ON true;\nEND;\n$function$\n"
    }
  },
  {
    "function_json": {
      "function_name": "get_system_stats",
      "return_type": "json",
      "arguments": "",
      "definition": "CREATE OR REPLACE FUNCTION public.get_system_stats()\n RETURNS json\n LANGUAGE plpgsql\n SECURITY DEFINER\nAS $function$\nDECLARE\n    result JSON;\n    total_users INTEGER;\n    new_users_today INTEGER;\n    total_servers INTEGER;\n    active_servers INTEGER;\n    federated_instances INTEGER;\n    total_posts INTEGER;\n    posts_today INTEGER;\nBEGIN\n    -- Get total users\n    SELECT COUNT(*) INTO total_users FROM profiles WHERE created_at IS NOT NULL;\n    \n    -- Get new users today\n    SELECT COUNT(*) INTO new_users_today \n    FROM profiles \n    WHERE created_at >= CURRENT_DATE;\n    \n    -- Get total servers\n    SELECT COUNT(*) INTO total_servers FROM servers;\n    \n    -- Get active servers (servers with recent activity)\n    SELECT COUNT(*) INTO active_servers \n    FROM servers s \n    WHERE EXISTS (\n        SELECT 1 FROM messages m \n        JOIN channels c ON m.channel_id = c.id \n        WHERE c.server_id = s.id \n        AND m.created_at >= NOW() - INTERVAL '7 days'\n    );\n    \n    -- Get federated instances count\n    SELECT COUNT(DISTINCT domain) INTO federated_instances \n    FROM profiles \n    WHERE domain IS NOT NULL;\n    \n    -- Get total posts\n    SELECT COUNT(*) INTO total_posts FROM posts;\n    \n    -- Get posts today\n    SELECT COUNT(*) INTO posts_today \n    FROM posts \n    WHERE created_at >= CURRENT_DATE;\n    \n    result := json_build_object(\n        'totalUsers', total_users,\n        'newUsersToday', new_users_today,\n        'totalServers', total_servers,\n        'activeServers', active_servers,\n        'federatedInstances', federated_instances,\n        'totalPosts', total_posts,\n        'postsToday', posts_today\n    );\n    \n    RETURN result;\nEND;\n$function$\n"
    }
  },
  {
    "function_json": {
      "function_name": "get_timeline_posts_with_interactions",
      "return_type": "record",
      "arguments": "p_user_id uuid, p_timeline_type text DEFAULT 'public'::text, p_limit integer DEFAULT 20, p_max_id text DEFAULT NULL::text",
      "definition": "CREATE OR REPLACE FUNCTION public.get_timeline_posts_with_interactions(p_user_id uuid, p_timeline_type text DEFAULT 'public'::text, p_limit integer DEFAULT 20, p_max_id text DEFAULT NULL::text)\n RETURNS TABLE(id text, created_at timestamp with time zone, updated_at timestamp with time zone, content jsonb, content_warning text, language text, author_id text, ap_id text, ap_type text, url text, reply_context jsonb, conversation_id text, visibility text, is_local boolean, is_federated boolean, replies_count integer, reblogs_count integer, favorites_count integer, media_attachments jsonb, metadata jsonb, is_sensitive boolean, is_deleted boolean, deleted_at timestamp with time zone, author jsonb, is_favorited boolean, is_reblogged boolean, is_bookmarked boolean, reblog jsonb, reblog_author jsonb)\n LANGUAGE plpgsql\nAS $function$\nBEGIN\n  RETURN QUERY\n  SELECT \n    tp.id::text,\n    tp.created_at,\n    tp.updated_at,\n    tp.content,\n    tp.content_warning,\n    'en'::text as language, -- Default language\n    (tp.author->>'id')::text as author_id,\n    p.ap_id::text,\n    COALESCE(p.ap_type, 'Note')::text as ap_type,\n    tp.url,\n    tp.reply_context,\n    tp.conversation_id::text,\n    tp.visibility,\n    (tp.author->>'is_local')::boolean as is_local,\n    NOT (tp.author->>'is_local')::boolean as is_federated,\n    tp.replies_count,\n    tp.reblogs_count,\n    tp.favorites_count,\n    tp.media_attachments,\n    COALESCE(p.metadata, '{}'::jsonb) as metadata,\n    tp.is_sensitive,\n    COALESCE(p.is_deleted, false) as is_deleted,\n    p.deleted_at,\n    tp.author,\n    \n    -- User interaction states (calculated properly from post_interactions)\n    COALESCE(fav.user_id IS NOT NULL, false) as is_favorited,\n    COALESCE(reb.user_id IS NOT NULL, false) as is_reblogged,\n    COALESCE(book.user_id IS NOT NULL, false) as is_bookmarked,\n    \n    -- Add reblog fields from timeline_posts view\n    tp.reblog,\n    tp.reblog_author\n    \n  FROM timeline_posts tp\n  JOIN posts p ON tp.id = p.id  -- Join to get additional post data\n  LEFT JOIN post_interactions fav ON tp.id = fav.post_id \n    AND fav.user_id = p_user_id \n    AND fav.interaction_type = 'favorite'\n  LEFT JOIN post_interactions reb ON tp.id = reb.post_id \n    AND reb.user_id = p_user_id \n    AND reb.interaction_type = 'reblog'\n  LEFT JOIN post_interactions book ON tp.id = book.post_id \n    AND book.user_id = p_user_id \n    AND book.interaction_type = 'bookmark'\n  \n  WHERE \n    -- Timeline filtering\n    CASE \n      WHEN p_timeline_type = 'public' THEN tp.visibility = 'public'\n      WHEN p_timeline_type = 'local' THEN tp.visibility = 'public' AND (tp.author->>'is_local')::boolean = true\n      WHEN p_timeline_type = 'home' THEN (\n        tp.visibility = 'public' AND (\n          (tp.author->>'id')::text = p_user_id::text OR\n          EXISTS (\n            SELECT 1 FROM follows f \n            WHERE f.follower_id = p_user_id \n            AND f.following_id = (tp.author->>'id')::uuid\n            AND f.status = 'accepted'\n          )\n        )\n      )\n      ELSE tp.visibility = 'public'\n    END\n    -- FIX: Use timeline_posts for pagination\n    AND (p_max_id IS NULL OR tp.created_at < (\n      SELECT tp2.created_at FROM timeline_posts tp2 WHERE tp2.id = p_max_id::uuid\n    ))\n  \n  ORDER BY tp.created_at DESC\n  LIMIT p_limit;\nEND;\n$function$\n"
    }
  },
  {
    "function_json": {
      "function_name": "get_trending_hashtags",
      "return_type": "record",
      "arguments": "p_limit_count integer DEFAULT 20",
      "definition": "CREATE OR REPLACE FUNCTION public.get_trending_hashtags(p_limit_count integer DEFAULT 20)\n RETURNS TABLE(tag text, daily_uses integer, trending_score numeric, trending_rank integer, change_percent numeric)\n LANGUAGE plpgsql\nAS $function$\nBEGIN\n    RETURN QUERY\n    SELECT \n        h.tag,\n        h.daily_uses,\n        h.trending_score,\n        h.trending_rank,\n        CASE \n            WHEN h.weekly_uses > 0 THEN \n                ROUND(((h.daily_uses::DECIMAL - (h.weekly_uses::DECIMAL / 7)) / (h.weekly_uses::DECIMAL / 7)) * 100, 1)\n            ELSE 0.0\n        END as change_percent\n    FROM hashtags h\n    WHERE h.trending_rank IS NOT NULL \n    ORDER BY h.trending_rank ASC\n    LIMIT p_limit_count;\nEND;\n$function$\n"
    }
  },
  {
    "function_json": {
      "function_name": "get_trending_maintenance_stats",
      "return_type": "json",
      "arguments": "",
      "definition": "CREATE OR REPLACE FUNCTION public.get_trending_maintenance_stats()\n RETURNS json\n LANGUAGE plpgsql\nAS $function$\nDECLARE\n    result JSON;\n    total_hashtags INTEGER;\n    active_hashtags INTEGER;\n    trending_hashtags INTEGER;\n    old_hashtags INTEGER;\n    trending_posts_count INTEGER;\n    trending_users_count INTEGER;\n    archived_hashtags INTEGER;\nBEGIN\n    -- Get current statistics\n    SELECT COUNT(*) INTO total_hashtags FROM hashtags;\n    SELECT COUNT(*) INTO active_hashtags FROM hashtags WHERE last_used_at >= NOW() - INTERVAL '30 days';\n    SELECT COUNT(*) INTO trending_hashtags FROM hashtags WHERE trending_rank IS NOT NULL;\n    SELECT COUNT(*) INTO old_hashtags FROM hashtags WHERE last_used_at < NOW() - INTERVAL '90 days';\n    SELECT COUNT(*) INTO trending_posts_count FROM trending_posts;\n    SELECT COUNT(*) INTO trending_users_count FROM trending_users;\n    \n    -- Get archived count if table exists\n    SELECT COUNT(*) INTO archived_hashtags \n    FROM hashtag_archive \n    WHERE EXISTS (SELECT 1 FROM information_schema.tables WHERE table_name = 'hashtag_archive');\n    \n    result := json_build_object(\n        'generated_at', NOW(),\n        'hashtags', json_build_object(\n            'total', total_hashtags,\n            'active_last_30_days', active_hashtags,\n            'currently_trending', trending_hashtags,\n            'older_than_90_days', old_hashtags,\n            'archived', COALESCE(archived_hashtags, 0)\n        ),\n        'trending_data', json_build_object(\n            'trending_posts', trending_posts_count,\n            'trending_users', trending_users_count\n        ),\n        'recommendations', json_build_object(\n            'should_run_cleanup', old_hashtags > 100,\n            'cleanup_benefit_estimate', old_hashtags || ' hashtags could be cleaned',\n            'next_recommended_cleanup', CASE \n                WHEN old_hashtags > 500 THEN 'immediately'\n                WHEN old_hashtags > 100 THEN 'within a week'\n                ELSE 'not needed'\n            END\n        )\n    );\n    \n    RETURN result;\nEND;\n$function$\n"
    }
  },
