    "function_json": {
      "function_name": "get_unread_notification_count",
      "return_type": "integer",
      "arguments": "p_user_id uuid",
      "definition": "CREATE OR REPLACE FUNCTION public.get_unread_notification_count(p_user_id uuid)\n RETURNS integer\n LANGUAGE sql\n STABLE\nAS $function$\n    SELECT COUNT(*)::integer\n    FROM notifications n\n    WHERE n.user_id = p_user_id\n    AND n.read_at IS NULL;\n$function$\n"
