  {
    "function_json": {
      "function_name": "get_user_conversations_with_participants",
      "return_type": "record",
      "arguments": "user_uuid uuid",
      "definition": "CREATE OR REPLACE FUNCTION public.get_user_conversations_with_participants(user_uuid uuid)\n RETURNS TABLE(conversation_id uuid, conversation_name text, conversation_type text, is_active boolean, created_at timestamp with time zone, updated_at timestamp with time zone, participant_count bigint, other_participants jsonb, user_role text, user_joined_at timestamp with time zone, user_last_read_at timestamp with time zone)\n LANGUAGE sql\n STABLE\nAS $function$\n  SELECT \n    c.id as conversation_id,\n    c.name as conversation_name,\n    c.type as conversation_type,\n    c.is_active,\n    c.created_at,\n    c.updated_at,\n    (\n      SELECT COUNT(*) FROM conversation_participants cp_count\n      WHERE cp_count.conversation_id = c.id AND cp_count.left_at IS NULL\n    ) as participant_count,\n    (\n      SELECT COALESCE(\n        jsonb_agg(\n          jsonb_build_object(\n            'user_id', cp_others.user_id,\n            'role', cp_others.role,\n            'joined_at', cp_others.joined_at\n          )\n        ),\n        '[]'::jsonb\n      )\n      FROM conversation_participants cp_others\n      WHERE cp_others.conversation_id = c.id \n        AND cp_others.user_id != user_uuid\n        AND cp_others.left_at IS NULL\n    ) as other_participants,\n    cp_user.role as user_role,\n    cp_user.joined_at as user_joined_at,\n    cp_user.last_read_at as user_last_read_at\n  FROM conversations c\n  INNER JOIN conversation_participants cp_user ON c.id = cp_user.conversation_id\n  WHERE cp_user.user_id = user_uuid \n    AND cp_user.left_at IS NULL\n    AND c.is_active = TRUE\n  ORDER BY c.updated_at DESC;\n$function$\n"
    }
  },
  {
    "function_json": {
      "function_name": "get_user_emoji_stats",
      "return_type": "record",
      "arguments": "p_user_id uuid, p_server_id uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 20",
      "definition": "CREATE OR REPLACE FUNCTION public.get_user_emoji_stats(p_user_id uuid, p_server_id uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 20)\n RETURNS TABLE(emoji_id uuid, emoji_name text, emoji_url text, usage_count bigint, last_used timestamp with time zone, message_uses bigint, reaction_uses bigint)\n LANGUAGE plpgsql\nAS $function$\nBEGIN\n    RETURN QUERY\n    SELECT \n        e.id as emoji_id,\n        e.name as emoji_name,\n        e.url as emoji_url,\n        COUNT(eu.*) as usage_count,\n        MAX(eu.used_at) as last_used,\n        COUNT(CASE WHEN eu.context_type = 'message' THEN 1 END) as message_uses,\n        COUNT(CASE WHEN eu.context_type = 'reaction' THEN 1 END) as reaction_uses\n    FROM emoji_usage eu\n    JOIN emojis e ON eu.emoji_id = e.id\n    WHERE eu.user_id = p_user_id\n    AND (p_server_id IS NULL OR eu.server_id = p_server_id)\n    GROUP BY e.id, e.name, e.url\n    ORDER BY usage_count DESC, last_used DESC\n    LIMIT p_limit;\nEND;\n$function$\n"
    }
  },
  {
    "function_json": {
      "function_name": "get_user_featured_posts",
      "return_type": "record",
      "arguments": "p_author_id uuid, p_limit integer DEFAULT 10",
      "definition": "CREATE OR REPLACE FUNCTION public.get_user_featured_posts(p_author_id uuid, p_limit integer DEFAULT 10)\n RETURNS TABLE(id uuid, content jsonb, created_at timestamp with time zone, updated_at timestamp with time zone, author_id uuid, engagement_count integer, replies_count integer, is_pinned boolean, ap_id text, ap_type text, visibility text, media_attachments jsonb, content_warning text, in_reply_to uuid, favorites_count integer, reblogs_count integer)\n LANGUAGE plpgsql\nAS $function$\nBEGIN\n    RETURN QUERY\n    SELECT \n        p.id, p.content, p.created_at, p.updated_at, p.author_id,\n        (p.favorites_count + p.reblogs_count + p.replies_count) as engagement_count,\n        p.replies_count, p.is_pinned,\n        p.ap_id, p.ap_type, p.visibility, p.media_attachments,\n        p.content_warning, p.in_reply_to, p.favorites_count, p.reblogs_count\n    FROM posts p\n    WHERE p.author_id = p_author_id \n        AND p.is_deleted = false\n        AND p.visibility IN ('public', 'unlisted')\n    ORDER BY \n        CASE WHEN p.is_pinned THEN 1 ELSE 2 END,\n        (p.favorites_count + p.reblogs_count + p.replies_count) DESC,\n        p.created_at DESC\n    LIMIT p_limit;\nEND;\n$function$\n"
    }
  },
  {
    "function_json": {
      "function_name": "get_user_handle",
      "return_type": "text",
      "arguments": "p_user_id uuid",
      "definition": "CREATE OR REPLACE FUNCTION public.get_user_handle(p_user_id uuid)\n RETURNS text\n LANGUAGE plpgsql\nAS $function$\nDECLARE\n    user_record profiles%ROWTYPE;\nBEGIN\n    SELECT * INTO user_record FROM profiles WHERE id = p_user_id;\n    IF user_record.domain = 'har.mony.lol' THEN\n        RETURN '@' || user_record.username;\n    ELSE\n        RETURN '@' || user_record.username || '@' || user_record.domain;\n    END IF;\nEND;\n$function$\n"
    }
  },
  {
    "function_json": {
      "function_name": "get_user_id_from_username",
      "return_type": "uuid",
      "arguments": "username_param text",
      "definition": "CREATE OR REPLACE FUNCTION public.get_user_id_from_username(username_param text)\n RETURNS uuid\n LANGUAGE plpgsql\nAS $function$\nDECLARE\n    user_id UUID;\nBEGIN\n    SELECT id INTO user_id\n    FROM profiles\n    WHERE username = username_param\n    LIMIT 1;\n    \n    RETURN user_id;\nEND;\n$function$\n"
