    "function_json": {
      "function_name": "handle_outgoing_messages",
      "return_type": "trigger",
      "arguments": "",
      "definition": "CREATE OR REPLACE FUNCTION public.handle_outgoing_messages()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'extensions', 'public', 'pg_temp'\nAS $function$\nDECLARE\n    -- Variables for notifications\n    mentioned_usernames TEXT[];\n    mentioned_user_id UUID;\n    username_item TEXT;\n    sender_profile profiles%ROWTYPE;\n    channel_info channels%ROWTYPE;\n    server_info servers%ROWTYPE;\n    conversation_type TEXT;\n    \n    -- Variables for federation\n    v_federation_type TEXT;\n    v_instance_domain TEXT;\n    v_sender_url TEXT;\n    v_recipient_url TEXT;\n    v_message_url TEXT;\n    v_activity_id TEXT;\n    v_html_content TEXT;\n    v_attachments JSONB;\n    v_tags JSONB;\n    v_note_object JSONB;\n    v_activity JSONB;\n    v_activity_uuid UUID;\n    v_recipient_profile RECORD;\n    target_domains TEXT[];\nBEGIN\n    -- Get sender profile\n    SELECT * INTO sender_profile FROM profiles WHERE id = NEW.user_id;\n    \n    -- Determine federation type\n    v_federation_type := determine_message_federation_type(NEW.id);\n    \n    -- Send notifications for federated messages ONLY to LOCAL users\n    IF v_federation_type = 'dm_federated' THEN\n        -- Notify only LOCAL conversation participants\n        PERFORM send_notification(\n            'dm',\n            ARRAY(\n                SELECT DISTINCT cp.user_id \n                FROM conversation_participants cp\n                JOIN profiles p ON p.id = cp.user_id\n                WHERE cp.conversation_id = NEW.conversation_id \n                  AND cp.user_id != NEW.user_id\n                  AND cp.left_at IS NULL\n                  AND p.is_local = true  -- ✅ ONLY LOCAL USERS\n            ),\n            jsonb_build_object(\n                'message_id', NEW.id,\n                'conversation_id', NEW.conversation_id,\n                'sender_id', NEW.user_id,\n                'content_preview', CASE \n                    WHEN jsonb_array_length(NEW.content) > 0 \n                    THEN NEW.content->0->>'text'\n                    ELSE 'New message'\n                END,\n                'federated', true\n            ),\n            NULL, NULL, NEW.conversation_id, NEW.user_id, 'normal'\n        );\n    END IF;\n    \n    -- Handle federation for outgoing messages\n    IF NEW.conversation_id IS NOT NULL AND sender_profile.is_local THEN\n        -- Get instance domain from config\n        SELECT trim(both '\"' from config_value::text) INTO v_instance_domain \n        FROM instance_config \n        WHERE config_key = 'domain' \n        LIMIT 1;\n        \n        IF v_instance_domain IS NOT NULL THEN\n            -- Find remote recipients using conversation_participants table\n            FOR v_recipient_profile IN \n                SELECT p.id, p.username, p.domain, p.federated_id, p.is_local, p.inbox_url\n                FROM conversation_participants cp\n                JOIN profiles p ON p.id = cp.user_id\n                WHERE cp.conversation_id = NEW.conversation_id \n                  AND cp.user_id != NEW.user_id\n                  AND cp.left_at IS NULL\n                  AND NOT p.is_local\n                  AND p.domain IS NOT NULL\n            LOOP\n                -- Build URLs using federated_id when available, fallback to constructed URL\n                v_sender_url := 'https://' || v_instance_domain || '/users/' || sender_profile.username;\n                v_recipient_url := COALESCE(v_recipient_profile.federated_id, 'https://' || v_recipient_profile.domain || '/users/' || v_recipient_profile.username);\n                v_message_url := 'https://' || v_instance_domain || '/messages/' || NEW.id::TEXT;\n                v_activity_id := v_sender_url || '#dm-' || NEW.id::TEXT;\n                \n                -- Use modern content processing functions\n                v_html_content := convert_jsonb_to_ap(NEW.content);\n                v_attachments := extract_activitypub_attachments(NEW.content);\n                v_tags := extract_all_activitypub_tags(NEW.content);\n                \n                -- ✅ CRITICAL FIX 1: Add recipient as mention tag (from working 073-074)\n                v_tags := v_tags || jsonb_build_array(\n                    jsonb_build_object(\n                        'type', 'Mention',\n                        'href', v_recipient_url,\n                        'name', '@' || v_recipient_profile.username || '@' || v_recipient_profile.domain\n                    )\n                );\n                \n                -- Create Note object (DM format)\n                v_note_object := jsonb_build_object(\n                    'id', v_message_url,\n                    'type', 'Note',\n                    'attributedTo', v_sender_url,\n                    'published', to_char(NEW.created_at AT TIME ZONE 'UTC', 'YYYY-MM-DD\"T\"HH24:MI:SS\"Z\"'),\n                    'content', v_html_content,\n                    'contentMap', jsonb_build_object('en', v_html_content),\n                    'attachment', COALESCE(v_attachments, '[]'::jsonb),\n                    'tag', v_tags,\n                    'to', jsonb_build_array(v_recipient_url),  -- Direct addressing\n                    'cc', '[]'::jsonb,                         -- Empty CC for DMs\n                    'directMessage', true                      -- ✅ CRITICAL FIX 2: Explicit DM flag\n                );\n                \n                -- Create ActivityPub Create activity\n                v_activity := jsonb_build_object(\n                    '@context', 'https://www.w3.org/ns/activitystreams',\n                    'id', v_activity_id,\n                    'type', 'Create',\n                    'actor', v_sender_url,\n                    'published', to_char(NEW.created_at AT TIME ZONE 'UTC', 'YYYY-MM-DD\"T\"HH24:MI:SS\"Z\"'),\n                    'object', v_note_object,\n                    'to', jsonb_build_array(v_recipient_url),  -- Direct addressing\n                    'cc', '[]'::jsonb                          -- Empty CC for DMs\n                );\n                \n                -- Store the ActivityPub activity record\n                INSERT INTO ap_activities (\n                    ap_id, ap_type, actor_id, actor_ap_id, object_id, object_type,\n                    activity_data, status, to_addresses, is_local, origin_domain\n                ) VALUES (\n                    v_activity_id, 'Create', sender_profile.id, v_sender_url, v_message_url, 'Note',\n                    v_activity, 'pending', ARRAY[v_recipient_url], true, v_instance_domain\n                ) RETURNING id INTO v_activity_uuid;\n                \n                -- Build array of target domains for queue_activity_for_federation\n                target_domains := ARRAY[v_recipient_profile.domain];\n                \n                -- Queue for federation delivery\n                PERFORM queue_activity_for_federation(\n                    v_activity_uuid,  -- The UUID from ap_activities \n                    target_domains,   -- Array of domains to deliver to\n                    8,                -- High priority for DMs (1-10 scale, 8 is high)\n                    true              -- Immediate delivery\n                );\n                \n                RAISE NOTICE '📮 Queued DM for federation to: %@% (activity: %)', \n                    v_recipient_profile.username, v_recipient_profile.domain, v_activity_uuid;\n                    \n            END LOOP;\n        END IF;\n    END IF;\n    \n    RETURN NEW;\nEXCEPTION\n    WHEN OTHERS THEN\n        RAISE WARNING 'Error in handle_outgoing_messages for message %: % %', NEW.id, SQLSTATE, SQLERRM;\n        RETURN NEW;\nEND;\n$function$\n"
    }
  },
  {
    "function_json": {
      "function_name": "handle_post_federation",
      "return_type": "trigger",
      "arguments": "",
      "definition": "CREATE OR REPLACE FUNCTION public.handle_post_federation()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\nAS $function$\nDECLARE\n    v_sender_profile RECORD;\n    v_instance_domain TEXT;\n    v_activity_id TEXT;\n    v_activity_uuid UUID;\n    v_sender_url TEXT;\n    v_post_url TEXT;\n    v_activity JSONB;\n    v_note_object JSONB;\n    v_mentioned_actor_urls TEXT[];\n    v_mention_domains TEXT[];\n    v_domain TEXT;\n    v_followers_url TEXT;\nBEGIN\n    -- Only process local posts that should be federated\n    IF NEW.is_local IS NOT TRUE OR NEW.visibility = 'private' THEN\n        RETURN NEW;\n    END IF;\n\n    -- Get sender profile and instance domain\n    SELECT * INTO v_sender_profile FROM profiles WHERE id = NEW.author_id;\n    SELECT trim(both '\"' from config_value::text) INTO v_instance_domain \n    FROM instance_config WHERE config_key = 'domain' LIMIT 1;\n    \n    IF v_instance_domain IS NULL THEN\n        RAISE WARNING 'No instance domain configured, skipping post federation';\n        RETURN NEW;\n    END IF;\n\n    -- Build URLs and activity\n    v_sender_url := 'https://' || v_instance_domain || '/users/' || v_sender_profile.username;\n    v_post_url := 'https://' || v_instance_domain || '/posts/' || NEW.id::TEXT;\n    v_activity_id := v_sender_url || '#create-' || NEW.id::TEXT;\n    v_followers_url := v_sender_url || '/followers';\n\n    -- Extract mentions using actual federated_id lookup\n    WITH mention_extraction AS (\n        SELECT \n            content_item->>'username' as username,\n            content_item->>'domain' as domain\n        FROM jsonb_array_elements(NEW.content) AS content_item\n        WHERE content_item->>'type' = 'mention'\n        AND content_item->>'username' IS NOT NULL\n        AND content_item->>'username' != ''\n    ),\n    resolved_mentions AS (\n        SELECT DISTINCT\n            CASE \n                WHEN me.domain IS NOT NULL AND me.domain != v_instance_domain THEN\n                    -- Use actual federated_id from profiles table\n                    COALESCE(p.federated_id, 'https://' || me.domain || '/users/' || me.username)\n                WHEN me.domain IS NULL OR me.domain = v_instance_domain THEN\n                    'https://' || v_instance_domain || '/users/' || me.username\n                ELSE \n                    COALESCE(p.federated_id, 'https://' || me.domain || '/users/' || me.username)\n            END as actor_url,\n            COALESCE(me.domain, v_instance_domain) as domain\n        FROM mention_extraction me\n        LEFT JOIN profiles p ON (\n            p.username = me.username \n            AND p.domain = me.domain \n            AND NOT p.is_local\n        )\n        WHERE me.username IS NOT NULL\n    ),\n    remote_mentions AS (\n        -- Filter to get only remote mention domains (excluding local)\n        SELECT DISTINCT rm.domain\n        FROM resolved_mentions rm\n        WHERE rm.domain IS NOT NULL \n          AND rm.domain != v_instance_domain\n          AND rm.domain != ''\n    )\n    SELECT \n        CASE WHEN count(rm.actor_url) > 0 \n             THEN array_agg(DISTINCT rm.actor_url) \n             ELSE NULL \n        END,\n        CASE WHEN count(rmt.domain) > 0 \n             THEN array_agg(DISTINCT rmt.domain) \n             ELSE NULL \n        END\n    INTO v_mentioned_actor_urls, v_mention_domains\n    FROM resolved_mentions rm\n    FULL OUTER JOIN remote_mentions rmt ON true;\n\n    -- Debug logging\n    RAISE NOTICE 'Post %: Extracted % mention domains: %', \n        NEW.id, \n        COALESCE(array_length(v_mention_domains, 1), 0), \n        v_mention_domains;\n    RAISE NOTICE 'Post %: Extracted % actor URLs: %', \n        NEW.id, \n        COALESCE(array_length(v_mentioned_actor_urls, 1), 0), \n        v_mentioned_actor_urls;\n\n    -- Build ActivityPub Note object\n    v_note_object := jsonb_build_object(\n        'id', v_post_url,\n        'type', 'Note',\n        'attributedTo', v_sender_url,\n        'published', to_char(NEW.created_at AT TIME ZONE 'UTC', 'YYYY-MM-DD\"T\"HH24:MI:SS\"Z\"'),\n        'content', public.convert_jsonb_to_ap(NEW.content),  -- ✅ FIXED: Use modern function\n        'contentMap', jsonb_build_object('en', public.convert_jsonb_to_ap(NEW.content)),  -- ✅ FIXED: Use modern function\n        'attachment', public.extract_activitypub_attachments(NEW.content),\n        'tag', public.extract_all_activitypub_tags(NEW.content),\n        'to', CASE NEW.visibility\n            WHEN 'public' THEN jsonb_build_array('https://www.w3.org/ns/activitystreams#Public', v_followers_url)\n            WHEN 'unlisted' THEN jsonb_build_array(v_followers_url)\n            WHEN 'followers' THEN jsonb_build_array(v_followers_url)\n            WHEN 'mentioned' THEN CASE \n                WHEN v_mentioned_actor_urls IS NOT NULL \n                THEN to_jsonb(v_mentioned_actor_urls)\n                ELSE '[]'::jsonb\n            END\n            ELSE '[]'::jsonb\n        END,\n        'cc', CASE NEW.visibility\n            WHEN 'public' THEN CASE \n                WHEN v_mentioned_actor_urls IS NOT NULL \n                THEN to_jsonb(v_mentioned_actor_urls)\n                ELSE '[]'::jsonb\n            END\n            WHEN 'unlisted' THEN jsonb_build_array('https://www.w3.org/ns/activitystreams#Public') || \n                CASE \n                    WHEN v_mentioned_actor_urls IS NOT NULL \n                    THEN to_jsonb(v_mentioned_actor_urls)\n                    ELSE '[]'::jsonb\n                END\n            ELSE '[]'::jsonb\n        END\n    );\n\n    -- Create ActivityPub Create activity\n    v_activity := jsonb_build_object(\n        '@context', 'https://www.w3.org/ns/activitystreams',\n        'id', v_activity_id,\n        'type', 'Create',\n        'actor', v_sender_url,\n        'object', v_note_object,\n        'published', to_char(NEW.created_at AT TIME ZONE 'UTC', 'YYYY-MM-DD\"T\"HH24:MI:SS\"Z\"'),\n        'to', v_note_object->'to',\n        'cc', v_note_object->'cc'\n    );\n\n    -- Store the ActivityPub activity record (use service role to bypass RLS)\n    INSERT INTO ap_activities (\n        ap_id, ap_type, actor_id, actor_ap_id, object_id, object_type,\n        activity_data, status, to_addresses, is_local, origin_domain\n    ) VALUES (\n        v_activity_id, 'Create', NEW.author_id, v_sender_url, v_post_url, 'Note',\n        v_activity, 'pending', ARRAY[]::TEXT[], true, v_instance_domain\n    ) RETURNING id INTO v_activity_uuid;\n\n    -- Queue for edge function delivery based on visibility\n    CASE NEW.visibility\n        WHEN 'public', 'unlisted' THEN\n            -- For public/unlisted posts, federate to all domains that follow this user\n            WITH follower_domains AS (\n                SELECT DISTINCT p.domain\n                FROM follows f\n                JOIN profiles p ON f.follower_id = p.id\n                WHERE f.following_id = NEW.author_id\n                  AND f.status = 'accepted'\n                  AND NOT p.is_local\n                  AND p.domain IS NOT NULL\n                  AND p.domain != ''\n            ),\n            all_target_domains AS (\n                -- Combine follower domains with mention domains\n                SELECT domain FROM follower_domains\n                UNION\n                SELECT unnest(v_mention_domains) as domain \n                WHERE v_mention_domains IS NOT NULL\n            ),\n            final_domains AS (\n                SELECT DISTINCT domain\n                FROM all_target_domains\n                WHERE domain IS NOT NULL \n                  AND domain != ''\n                  AND domain != v_instance_domain\n            )\n            SELECT array_agg(domain) INTO v_mention_domains\n            FROM final_domains;\n            \n            IF v_mention_domains IS NOT NULL AND array_length(v_mention_domains, 1) > 0 THEN\n                PERFORM queue_activity_for_federation(v_activity_uuid, v_mention_domains, 5, true);\n                RAISE NOTICE '📮 Queued public/unlisted post % for delivery to % domains (followers + mentions)', \n                    NEW.id, array_length(v_mention_domains, 1);\n            ELSE\n                UPDATE ap_activities SET status = 'completed' WHERE id = v_activity_uuid;\n                RAISE NOTICE '🏠 Public/unlisted post % has no remote followers or mentions, marked as completed', NEW.id;\n            END IF;\n            \n        WHEN 'followers' THEN\n            -- For followers-only posts, federate to follower domains only\n            WITH follower_domains AS (\n                SELECT DISTINCT p.domain\n                FROM follows f\n                JOIN profiles p ON f.follower_id = p.id\n                WHERE f.following_id = NEW.author_id\n                  AND f.status = 'accepted'\n                  AND NOT p.is_local\n                  AND p.domain IS NOT NULL\n                  AND p.domain != ''\n                  AND p.domain != v_instance_domain\n            )\n            SELECT array_agg(domain) INTO v_mention_domains\n            FROM follower_domains;\n            \n            IF v_mention_domains IS NOT NULL AND array_length(v_mention_domains, 1) > 0 THEN\n                PERFORM queue_activity_for_federation(v_activity_uuid, v_mention_domains, 6, true);\n                RAISE NOTICE '📮 Queued followers post % for delivery to % follower domains', \n                    NEW.id, array_length(v_mention_domains, 1);\n            ELSE\n                UPDATE ap_activities SET status = 'completed' WHERE id = v_activity_uuid;\n                RAISE NOTICE '🏠 Followers post % has no remote followers, marked as completed', NEW.id;\n            END IF;\n            \n        WHEN 'mentioned' THEN\n            -- For mentioned posts, only federate to domains with mentions\n            IF v_mention_domains IS NOT NULL AND array_length(v_mention_domains, 1) > 0 THEN\n                PERFORM queue_activity_for_federation(v_activity_uuid, v_mention_domains, 7, true);\n                RAISE NOTICE '📮 Queued mentioned post % for delivery to % domains', \n                    NEW.id, array_length(v_mention_domains, 1);\n            ELSE\n                UPDATE ap_activities SET status = 'completed' WHERE id = v_activity_uuid;\n                RAISE NOTICE '🏠 Mentioned post % has no remote mentions, marked as completed', NEW.id;\n            END IF;\n            \n        ELSE\n            UPDATE ap_activities SET status = 'completed' WHERE id = v_activity_uuid;\n            RAISE NOTICE 'Unknown visibility % for post %, marked as completed', NEW.visibility, NEW.id;\n    END CASE;\n\n    RETURN NEW;\nEXCEPTION\n    WHEN OTHERS THEN\n        RAISE WARNING 'Error in handle_post_federation for post %: % %', NEW.id, SQLSTATE, SQLERRM;\n        RETURN NEW;\nEND;\n$function$\n"
    }
  },
  {
    "function_json": {
      "function_name": "handle_post_reactions_federation",
      "return_type": "trigger",
      "arguments": "",
      "definition": "CREATE OR REPLACE FUNCTION public.handle_post_reactions_federation()\n RETURNS trigger\n LANGUAGE plpgsql\nAS $function$\nDECLARE\n    user_federation_enabled boolean;\n    current_instance_domain text;\n    full_instance_url text;  -- NEW: Full URL with protocol\n    activity_type text;\n    target_object_id text;\n    target_actor_id uuid;\n    emoji_data record;\n    reaction_content text;\n    activity_content jsonb;\nBEGIN\n    -- Get instance domain and build full URL with protocol\n    SELECT trim(both '\"' from config_value::text) INTO current_instance_domain \n    FROM instance_config WHERE config_key = 'domain' LIMIT 1;\n    \n    full_instance_url := 'https://' || current_instance_domain;  -- NEW: Add protocol\n\n    -- Check federation for user\n    SELECT is_federation_enabled_for_user(COALESCE(NEW.user_id, OLD.user_id)) INTO user_federation_enabled;\n    \n    IF NOT user_federation_enabled THEN\n        RETURN COALESCE(NEW, OLD);\n    END IF;\n\n    -- Only federate reactions on post_interactions (not regular reactions table)\n    IF TG_OP = 'INSERT' THEN\n        activity_type := 'Like';\n        target_object_id := (SELECT ap_id FROM posts WHERE id = NEW.post_id);\n        target_actor_id := (SELECT author_id FROM posts WHERE id = NEW.post_id);\n        \n        -- Get emoji data for custom emoji federation\n        SELECT name, url INTO emoji_data \n        FROM emojis WHERE id = NEW.emoji_id;\n        \n        -- Build reaction content\n        reaction_content := CASE \n            WHEN emoji_data.name IS NOT NULL THEN ':' || emoji_data.name || ':'\n            ELSE '❤️'  -- Default heart emoji\n        END;\n        \n    ELSIF TG_OP = 'DELETE' THEN\n        activity_type := 'Undo';\n        target_object_id := (SELECT ap_id FROM posts WHERE id = OLD.post_id);\n        target_actor_id := (SELECT author_id FROM posts WHERE id = OLD.post_id);\n        \n        -- For undo, we don't need emoji data\n        reaction_content := NULL;\n    END IF;\n\n    -- Build activity content\n    activity_content := jsonb_build_object(\n        'type', activity_type,\n        'actor', (SELECT federated_id FROM profiles WHERE id = COALESCE(NEW.user_id, OLD.user_id)),\n        'object', target_object_id,\n        'content', reaction_content,\n        'tag', CASE \n            WHEN emoji_data.name IS NOT NULL AND emoji_data.url IS NOT NULL THEN\n                jsonb_build_array(\n                    jsonb_build_object(\n                        'type', 'Emoji',\n                        'name', reaction_content,\n                        'icon', jsonb_build_object(\n                            'type', 'Image',\n                            'url', emoji_data.url\n                        ),\n                        'id', full_instance_url || '/emojis/' || COALESCE(NEW.emoji_id, OLD.emoji_id)  -- FIXED: Use full URL\n                    )\n                )\n            ELSE '[]'::jsonb\n        END\n    );\n\n    -- Create ActivityPub activity for federation\n    INSERT INTO ap_activities (\n        ap_id, ap_type, actor_id, actor_ap_id, object_id, object_type,\n        target_id, target_type, activity_data, status, is_local\n    ) VALUES (\n        full_instance_url || '/activities/' || gen_random_uuid(),  -- FIXED: Use full URL\n        activity_type,\n        COALESCE(NEW.user_id, OLD.user_id),\n        (SELECT federated_id FROM profiles WHERE id = COALESCE(NEW.user_id, OLD.user_id)),\n        target_object_id, 'Note', target_actor_id, 'Person',\n        activity_content,\n        'pending', true\n    );\n\n    RETURN COALESCE(NEW, OLD);\nEND;\n$function$\n"
    }
