  {
    "function_json": {
      "function_name": "handle_unified_interaction_federation",
      "return_type": "trigger",
      "arguments": "",
      "definition": "CREATE OR REPLACE FUNCTION public.handle_unified_interaction_federation()\n RETURNS trigger\n LANGUAGE plpgsql\nAS $function$\nDECLARE\n    user_federation_enabled boolean;\n    target_federation_enabled boolean;\n    current_instance_domain text;\n    full_instance_url text;  -- NEW: Full URL with protocol\n    activity_type text;\n    target_object_id text;\n    target_actor_id uuid;\n    actor_user_id uuid;\nBEGIN\n    -- Get instance domain and build full URL with protocol\n    SELECT trim(both '\"' from config_value::text) INTO current_instance_domain \n    FROM instance_config WHERE config_key = 'domain' LIMIT 1;\n    \n    full_instance_url := 'https://' || current_instance_domain;  -- NEW: Add protocol\n\n    -- Determine the actor user ID based on table type\n    IF TG_TABLE_NAME = 'follows' THEN\n        actor_user_id := COALESCE(NEW.follower_id, OLD.follower_id);\n    ELSE\n        actor_user_id := COALESCE(NEW.user_id, OLD.user_id);\n    END IF;\n\n    -- Check federation for actor user\n    SELECT is_federation_enabled_for_user(actor_user_id) INTO user_federation_enabled;\n    \n    IF NOT user_federation_enabled THEN\n        RETURN COALESCE(NEW, OLD);\n    END IF;\n\n    -- Determine activity details based on table and operation\n    IF TG_TABLE_NAME = 'follows' THEN\n        IF TG_OP = 'INSERT' THEN\n            activity_type := 'Follow';\n            target_object_id := (SELECT federated_id FROM profiles WHERE id = NEW.following_id);\n            target_actor_id := NEW.following_id;\n        ELSIF TG_OP = 'DELETE' THEN\n            activity_type := 'Undo';\n            target_object_id := (SELECT federated_id FROM profiles WHERE id = OLD.following_id);\n            target_actor_id := OLD.following_id;\n        END IF;\n\n    ELSIF TG_TABLE_NAME = 'post_interactions' THEN\n        -- Check federation for interaction user\n        SELECT is_federation_enabled_for_user(COALESCE(NEW.user_id, OLD.user_id)) INTO user_federation_enabled;\n        \n        IF NOT user_federation_enabled THEN\n            RETURN COALESCE(NEW, OLD);\n        END IF;\n\n        IF TG_OP = 'INSERT' THEN\n            activity_type := CASE \n                WHEN NEW.interaction_type = 'favorite' THEN 'Like'\n                WHEN NEW.interaction_type = 'reblog' THEN 'Announce' \n                ELSE 'Like'\n            END;\n            target_object_id := (SELECT ap_id FROM posts WHERE id = NEW.post_id);\n            target_actor_id := (SELECT author_id FROM posts WHERE id = NEW.post_id);\n        ELSIF TG_OP = 'DELETE' THEN\n            activity_type := 'Undo';\n            target_object_id := (SELECT ap_id FROM posts WHERE id = OLD.post_id);\n            target_actor_id := (SELECT author_id FROM posts WHERE id = OLD.post_id);\n        END IF;\n\n    ELSIF TG_TABLE_NAME = 'reactions' THEN\n        -- Check federation for reaction user\n        SELECT is_federation_enabled_for_user(COALESCE(NEW.user_id, OLD.user_id)) INTO user_federation_enabled;\n        \n        IF NOT user_federation_enabled THEN\n            RETURN COALESCE(NEW, OLD);\n        END IF;\n\n        IF TG_OP = 'INSERT' THEN\n            activity_type := 'Like';  -- FIXED: Use 'Like' instead of 'EmojiReact'\n            target_object_id := (SELECT 'message-' || NEW.message_id);\n            -- Get message author\n            SELECT user_id INTO target_actor_id FROM messages WHERE id = NEW.message_id;\n        ELSIF TG_OP = 'DELETE' THEN\n            activity_type := 'Undo';\n            target_object_id := (SELECT 'message-' || OLD.message_id);\n            SELECT user_id INTO target_actor_id FROM messages WHERE id = OLD.message_id;\n        END IF;\n    END IF;\n\n    -- Create federation activity if we have the required data\n    IF activity_type IS NOT NULL AND target_object_id IS NOT NULL AND actor_user_id IS NOT NULL THEN\n        INSERT INTO ap_activities (\n            ap_id,\n            ap_type,\n            actor_id,\n            actor_ap_id, \n            object_id,\n            object_type,\n            target_id,\n            target_type,\n            activity_data,\n            status,\n            is_local\n        ) VALUES (\n            full_instance_url || '/activities/' || gen_random_uuid(),  -- FIXED: Use full URL\n            activity_type,\n            actor_user_id,\n            (SELECT federated_id FROM profiles WHERE id = actor_user_id),\n            target_object_id,\n            CASE \n                WHEN TG_TABLE_NAME = 'follows' THEN 'Person'\n                WHEN TG_TABLE_NAME = 'post_interactions' THEN 'Note'\n                WHEN TG_TABLE_NAME = 'reactions' THEN 'Note'\n                ELSE 'Object'\n            END,\n            target_actor_id,\n            'Person',\n            jsonb_build_object(\n                'type', activity_type,\n                'actor', (SELECT federated_id FROM profiles WHERE id = actor_user_id),\n                'object', target_object_id\n            ),\n            'pending',\n            true\n        );\n    END IF;\n\n    RETURN COALESCE(NEW, OLD);\nEND;\n$function$\n"
    }
  },
  {
    "function_json": {
      "function_name": "handle_unified_interaction_processing",
      "return_type": "trigger",
      "arguments": "",
      "definition": "CREATE OR REPLACE FUNCTION public.handle_unified_interaction_processing()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\nAS $function$\nDECLARE\n    post_record RECORD;\n    user_profile RECORD;\n    target_user_profile RECORD;\n    is_target_local BOOLEAN;\n    activity_id UUID;\n    user_actor_url TEXT;\n    target_actor_url TEXT;\n    v_activity_data JSONB;\n    instance_domain TEXT;\nBEGIN\n    -- Only handle new interactions\n    IF TG_OP != 'INSERT' THEN\n        RETURN COALESCE(NEW, OLD);\n    END IF;\n\n    -- Get post and user info\n    SELECT * INTO post_record FROM posts WHERE id = NEW.post_id;\n    SELECT * INTO user_profile FROM profiles WHERE id = NEW.user_id;\n    SELECT * INTO target_user_profile FROM profiles WHERE id = post_record.author_id;\n    \n    -- Check if target user is local\n    is_target_local := target_user_profile.is_local;\n    \n    -- Get instance domain for federation\n    SELECT trim(both '\"' from config_value::text) INTO instance_domain \n    FROM instance_config WHERE config_key = 'domain' LIMIT 1;\n\n    IF NEW.interaction_type = 'favorite' THEN\n        IF is_target_local THEN\n            -- LOCAL USER: Create notification only\n            PERFORM create_simple_activitypub_notification(\n                post_record.author_id,\n                'activitypub_favorite',\n                jsonb_build_object(\n                    'user', jsonb_build_object(\n                        'id', user_profile.id,\n                        'username', user_profile.username,\n                        'display_name', user_profile.display_name,\n                        'avatar_url', user_profile.avatar_url,\n                        'domain', user_profile.domain\n                    ),\n                    'post_id', post_record.id,\n                    'interaction_id', NEW.id\n                )\n            );\n        ELSE\n            -- REMOTE USER: Only queue for federation (no immediate HTTP delivery)\n            activity_id := gen_random_uuid();\n            user_actor_url := format('https://%s/users/%s', instance_domain, user_profile.username);\n            target_actor_url := COALESCE(target_user_profile.federated_id, format('https://%s/users/%s', target_user_profile.domain, target_user_profile.username));\n            \n            v_activity_data := jsonb_build_object(\n                '@context', 'https://www.w3.org/ns/activitystreams',\n                'id', format('%s#like-%s', user_actor_url, NEW.id),\n                'type', 'Like',\n                'actor', user_actor_url,\n                'object', COALESCE(post_record.ap_id, format('https://%s/posts/%s', target_user_profile.domain, post_record.id)),\n                'published', to_char(NEW.created_at AT TIME ZONE 'UTC', 'YYYY-MM-DD\"T\"HH24:MI:SS\"Z\"')\n            );\n\n            -- Store activity\n            INSERT INTO ap_activities (\n                id, ap_id, ap_type, actor_id, actor_ap_id, object_id, object_type,\n                activity_data, status, to_addresses, is_local, origin_domain\n            ) VALUES (\n                activity_id, v_activity_data->>'id', 'Like', user_profile.id, user_actor_url,\n                post_record.ap_id, 'Note', v_activity_data, 'pending',\n                ARRAY[target_actor_url], true, instance_domain\n            );\n\n            -- Queue for federation delivery\n            PERFORM queue_activity_for_federation(activity_id, ARRAY[target_user_profile.domain]);\n        END IF;\n\n    ELSIF NEW.interaction_type = 'reblog' THEN\n        IF is_target_local THEN\n            -- LOCAL USER: Create notification only\n            PERFORM create_simple_activitypub_notification(\n                post_record.author_id,\n                'activitypub_reblog',\n                jsonb_build_object(\n                    'user', jsonb_build_object(\n                        'id', user_profile.id,\n                        'username', user_profile.username,\n                        'display_name', user_profile.display_name,\n                        'avatar_url', user_profile.avatar_url,\n                        'domain', user_profile.domain\n                    ),\n                    'post_id', post_record.id,\n                    'interaction_id', NEW.id\n                )\n            );\n        ELSE\n            -- REMOTE USER: Only queue for federation (no immediate HTTP delivery)\n            activity_id := gen_random_uuid();\n            user_actor_url := format('https://%s/users/%s', instance_domain, user_profile.username);\n            \n            v_activity_data := jsonb_build_object(\n                '@context', 'https://www.w3.org/ns/activitystreams',\n                'id', format('%s#announce-%s', user_actor_url, NEW.id),\n                'type', 'Announce',\n                'actor', user_actor_url,\n                'object', COALESCE(post_record.ap_id, format('https://%s/posts/%s', target_user_profile.domain, post_record.id)),\n                'published', to_char(NEW.created_at AT TIME ZONE 'UTC', 'YYYY-MM-DD\"T\"HH24:MI:SS\"Z\"'),\n                'to', jsonb_build_array('https://www.w3.org/ns/activitystreams#Public'),\n                'cc', jsonb_build_array(format('%s/followers', user_actor_url))\n            );\n\n            -- Store activity\n            INSERT INTO ap_activities (\n                id, ap_id, ap_type, actor_id, actor_ap_id, object_id, object_type,\n                activity_data, status, to_addresses, is_local, origin_domain\n            ) VALUES (\n                activity_id, v_activity_data->>'id', 'Announce', user_profile.id, user_actor_url,\n                post_record.ap_id, 'Note', v_activity_data, 'pending',\n                ARRAY['https://www.w3.org/ns/activitystreams#Public'], true, instance_domain\n            );\n\n            -- Queue for federation delivery  \n            PERFORM queue_activity_for_federation(activity_id, ARRAY[target_user_profile.domain]);\n        END IF;\n    END IF;\n\n    RETURN NEW;\nEND;\n$function$\n"
    }
  },
  {
    "function_json": {
      "function_name": "handle_unified_notification_processing",
      "return_type": "trigger",
      "arguments": "",
      "definition": "CREATE OR REPLACE FUNCTION public.handle_unified_notification_processing()\n RETURNS trigger\n LANGUAGE plpgsql\nAS $function$\nDECLARE\n    notification_data jsonb;\n    target_user_id uuid;\n    mentioned_users uuid[];\n    server_members uuid[];\n    followers uuid[];\n    single_target_id uuid;\n    target_user_ids uuid[];\n    -- CRITICAL: Use explicit variable names to avoid ANY ambiguity\n    msg_channel_id uuid;\n    msg_server_id uuid;\nBEGIN\n    -- Early exit for non-notification operations\n    IF TG_OP = 'UPDATE' THEN\n        RETURN NEW;\n    END IF;\n\n    -- Handle different table operations\n    IF TG_TABLE_NAME = 'mentions' AND TG_OP = 'INSERT' THEN\n        -- Handle mention notifications\n        notification_data := jsonb_build_object(\n            'type', 'mention',\n            'message_id', NEW.message_id,\n            'mentioned_by', NEW.mentioned_by\n        );\n        \n        PERFORM send_notification_to_user(\n            'mention',\n            NEW.mentioned_user,\n            notification_data,\n            (SELECT s.id FROM messages m JOIN channels c ON m.channel_id = c.id JOIN servers s ON c.server_id = s.id WHERE m.id = NEW.message_id),\n            (SELECT m.channel_id FROM messages m WHERE m.id = NEW.message_id),\n            NULL,\n            NEW.mentioned_by,\n            'normal'\n        );\n\n    ELSIF TG_TABLE_NAME = 'follows' AND TG_OP = 'INSERT' THEN\n        -- Handle follow notifications\n        notification_data := jsonb_build_object(\n            'type', 'follow',\n            'follower_id', NEW.follower_id\n        );\n        \n        PERFORM send_notification_to_user(\n            'follow',\n            NEW.following_id,\n            notification_data,\n            NULL,\n            NULL,\n            NULL,\n            NEW.follower_id,\n            'normal'\n        );\n\n    ELSIF TG_TABLE_NAME = 'reactions' AND TG_OP = 'INSERT' THEN\n        -- Handle reaction notifications\n        SELECT user_id INTO single_target_id FROM messages WHERE id = NEW.message_id;\n        \n        IF single_target_id IS NOT NULL AND single_target_id != NEW.user_id THEN\n            -- CRITICAL FIX: Use explicit variables to eliminate ANY channel_id ambiguity\n            SELECT m.channel_id, c.server_id \n            INTO msg_channel_id, msg_server_id\n            FROM messages m \n            LEFT JOIN channels c ON m.channel_id = c.id \n            WHERE m.id = NEW.message_id;\n            \n            notification_data := jsonb_build_object(\n                'type', 'reaction',\n                'message_id', NEW.message_id,\n                'emoji_id', NEW.emoji_id,\n                'user_id', NEW.user_id\n            );\n            \n            -- CRITICAL FIX: Use explicit variable names instead of ambiguous references\n            PERFORM send_notification_to_user(\n                'reaction',\n                single_target_id,\n                notification_data,\n                msg_server_id,  -- EXPLICIT: No ambiguity\n                msg_channel_id, -- EXPLICIT: No ambiguity\n                NULL,\n                NEW.user_id,\n                'normal'\n            );\n        END IF;\n    END IF;\n\n    RETURN COALESCE(NEW, OLD);\nEND;\n$function$\n"
    }
  },
  {
    "function_json": {
      "function_name": "handle_unified_profile_federation",
      "return_type": "trigger",
      "arguments": "",
      "definition": "CREATE OR REPLACE FUNCTION public.handle_unified_profile_federation()\n RETURNS trigger\n LANGUAGE plpgsql\nAS $function$\nDECLARE\n    user_federation_enabled boolean;\n    current_instance_domain text;\n    should_federate boolean := false;\nBEGIN\n    -- Only process UPDATE operations\n    IF TG_OP != 'UPDATE' THEN\n        RETURN COALESCE(NEW, OLD);\n    END IF;\n\n    -- Check if federation is enabled for this user\n    SELECT is_federation_enabled_for_user(NEW.id) INTO user_federation_enabled;\n    \n    IF NOT user_federation_enabled THEN\n        RETURN NEW;\n    END IF;\n\n    -- Check if any federable fields changed\n    should_federate := (\n        OLD.display_name IS DISTINCT FROM NEW.display_name OR\n        OLD.bio IS DISTINCT FROM NEW.bio OR\n        OLD.avatar_url IS DISTINCT FROM NEW.avatar_url OR\n        OLD.banner_url IS DISTINCT FROM NEW.banner_url\n    );\n\n    IF should_federate THEN\n        -- Get instance domain\n        SELECT trim(both '\"' from config_value::text) INTO current_instance_domain \n        FROM instance_config WHERE config_key = 'domain' LIMIT 1;\n\n        -- Create Update activity for profile changes\n        INSERT INTO ap_activities (\n            ap_id,\n            ap_type,\n            actor_id,\n            actor_ap_id,\n            object_id,\n            object_type,\n            activity_data,\n            status,\n            is_local\n        ) VALUES (\n            current_instance_domain || '/activities/' || gen_random_uuid(),\n            'Update',\n            NEW.id,\n            NEW.federated_id,\n            NEW.federated_id,\n            'Person',\n            jsonb_build_object(\n                'type', 'Update',\n                'actor', NEW.federated_id,\n                'object', jsonb_build_object(\n                    'type', 'Person',\n                    'id', NEW.federated_id,\n                    'name', NEW.display_name,\n                    'summary', NEW.bio,\n                    'icon', CASE WHEN NEW.avatar_url IS NOT NULL THEN \n                        jsonb_build_object('type', 'Image', 'url', NEW.avatar_url)\n                        ELSE NULL END,\n                    'image', CASE WHEN NEW.banner_url IS NOT NULL THEN\n                        jsonb_build_object('type', 'Image', 'url', NEW.banner_url) \n                        ELSE NULL END\n                )\n            ),\n            'pending',\n            true\n        );\n    END IF;\n\n    RETURN NEW;\nEND;\n$function$\n"
    }
  },
  {
    "function_json": {
      "function_name": "handle_unified_reply_processing",
      "return_type": "trigger",
      "arguments": "",
      "definition": "CREATE OR REPLACE FUNCTION public.handle_unified_reply_processing()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'extensions', 'public', 'pg_temp'\nAS $function$\nDECLARE\n    parent_post RECORD;\n    author_profile RECORD;\n    target_user_profile RECORD;\n    is_target_local BOOLEAN;\nBEGIN\n    -- Only handle new posts that are replies\n    -- Post creation federation is already handled by handle_post_federation()\n    IF TG_OP != 'INSERT' OR NEW.in_reply_to IS NULL THEN\n        RETURN NEW;\n    END IF;\n\n    -- Get parent post\n    SELECT id, author_id, ap_id\n    INTO parent_post\n    FROM posts\n    WHERE id = NEW.in_reply_to;\n\n    -- Get reply author profile\n    SELECT id, username, display_name, avatar_url, domain\n    INTO author_profile\n    FROM profiles \n    WHERE id = NEW.author_id;\n\n    -- Get target user (parent post author) profile\n    SELECT id, username, display_name, avatar_url, domain, is_local\n    INTO target_user_profile\n    FROM profiles \n    WHERE id = parent_post.author_id;\n\n    -- Skip if parent doesn't exist, profiles don't exist, or replying to self\n    IF NOT FOUND OR parent_post.author_id = NEW.author_id THEN\n        RETURN NEW;\n    END IF;\n\n    -- Use the is_local column from profiles table\n    is_target_local := target_user_profile.is_local;\n\n    IF is_target_local THEN\n        -- LOCAL USER: Create notification\n        -- (Federation of the reply itself is handled by handle_post_federation())\n        PERFORM create_simple_activitypub_notification(\n            parent_post.author_id,\n            'activitypub_reply',\n            jsonb_build_object(\n                'author', jsonb_build_object(\n                    'id', author_profile.id,\n                    'username', author_profile.username,\n                    'display_name', author_profile.display_name,\n                    'avatar_url', author_profile.avatar_url,\n                    'domain', author_profile.domain\n                ),\n                'post_id', NEW.id,\n                'parent_post_id', parent_post.id\n            )\n        );\n    END IF;\n    \n    -- Note: Federation is handled by handle_post_federation() trigger\n    -- which already handles replies with inReplyTo properly\n\n    RETURN NEW;\nEND;\n$function$\n"
    }
  },
  {
    "function_json": {
      "function_name": "handle_user_join",
      "return_type": "trigger",
      "arguments": "",
      "definition": "CREATE OR REPLACE FUNCTION public.handle_user_join()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\nAS $function$\nDECLARE\n    default_channel_id UUID;\n    event_id UUID;\n    user_profile RECORD;\n    invite_info RECORD;\n    via_invite BOOLEAN := false;\n    invite_temporary BOOLEAN := false;\nBEGIN\n    -- Get user profile for system message\n    SELECT username, display_name, avatar_url \n    INTO user_profile \n    FROM profiles \n    WHERE id = NEW.user_id;\n\n    -- Check if user joined via invite (look for recent invite usage)\n    -- We check for invites used within the last 5 minutes for this server\n    SELECT i.temporary, i.code, i.created_by\n    INTO invite_info\n    FROM invites i\n    WHERE i.server_id = NEW.server_id \n      AND i.used = true\n      AND i.created_at >= (NEW.created_at - INTERVAL '5 minutes')\n    ORDER BY i.created_at DESC\n    LIMIT 1;\n    \n    IF FOUND THEN\n        via_invite := true;\n        invite_temporary := COALESCE(invite_info.temporary, false);\n    END IF;\n\n    -- Log the membership event\n    INSERT INTO server_membership_events (server_id, user_id, event_type, metadata)\n    VALUES (NEW.server_id, NEW.user_id, 'join', jsonb_build_object(\n        'joined_at', NEW.created_at,\n        'via_invite', via_invite,\n        'invite_temporary', invite_temporary,\n        'username', user_profile.username,\n        'display_name', user_profile.display_name\n    ))\n    RETURNING id INTO event_id;\n    \n    -- Get default channel for system message\n    SELECT get_default_channel(NEW.server_id) INTO default_channel_id;\n    \n    -- Create system message if default channel exists\n    IF default_channel_id IS NOT NULL THEN\n        PERFORM create_system_message(default_channel_id, NEW.user_id, 'join');\n    END IF;\n    \n    RETURN NEW;\nEND;\n$function$\n"
    }
  },
  {
    "function_json": {
      "function_name": "handle_user_leave",
      "return_type": "trigger",
      "arguments": "",
      "definition": "CREATE OR REPLACE FUNCTION public.handle_user_leave()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\nAS $function$DECLARE\n    default_channel_id UUID;\n    event_id UUID;\n    user_profile RECORD;\n    server_exists BOOLEAN;\nBEGIN\n    -- Check if the server still exists (might have been deleted)\n    SELECT EXISTS(SELECT 1 FROM servers WHERE id = OLD.server_id) INTO server_exists;\n    \n    -- If server doesn't exist, this is part of server deletion cascade\n    -- Don't create membership events or system messages\n    IF NOT server_exists THEN\n        RETURN OLD;\n    END IF;\n\n    -- Get user profile for system message\n    SELECT username, display_name, avatar_url \n    INTO user_profile \n    FROM profiles \n    WHERE id = OLD.user_id;\n\n    -- Log the membership event (only if server still exists)\n    INSERT INTO server_membership_events (server_id, user_id, event_type, metadata)\n    VALUES (OLD.server_id, OLD.user_id, 'leave', jsonb_build_object(\n        'left_at', NOW(),\n        'username', user_profile.username,\n        'display_name', user_profile.display_name\n    ))\n    RETURNING id INTO event_id;\n    \n    -- Get default channel for system message\n    SELECT get_default_channel(OLD.server_id) INTO default_channel_id;\n    \n    -- Create system message if default channel exists\n    IF default_channel_id IS NOT NULL THEN\n        PERFORM create_system_message(default_channel_id, OLD.user_id, 'leave');\n    END IF;\n    \n    RETURN OLD;\nEND;$function$\n"
    }
  },
  {
    "function_json": {
      "function_name": "increment_emoji_usage",
      "return_type": "void",
      "arguments": "emoji_id uuid",
      "definition": "CREATE OR REPLACE FUNCTION public.increment_emoji_usage(emoji_id uuid)\n RETURNS void\n LANGUAGE plpgsql\nAS $function$\nBEGIN\n    UPDATE emojis \n    SET \n        usage_count = usage_count + 1,\n        last_used = now(),\n        updated_at = now()\n    WHERE id = emoji_id;\nEND;\n$function$\n"
    }
