    "function_json": {
      "function_name": "insert_ap_activity_safe",
      "return_type": "uuid",
      "arguments": "p_ap_id text, p_ap_type text, p_actor_ap_id text, p_activity_data jsonb, p_origin_domain text DEFAULT NULL::text, p_to_addresses text[] DEFAULT '{}'::text[], p_cc_addresses text[] DEFAULT '{}'::text[], p_is_local boolean DEFAULT false",
      "definition": "CREATE OR REPLACE FUNCTION public.insert_ap_activity_safe(p_ap_id text, p_ap_type text, p_actor_ap_id text, p_activity_data jsonb, p_origin_domain text DEFAULT NULL::text, p_to_addresses text[] DEFAULT '{}'::text[], p_cc_addresses text[] DEFAULT '{}'::text[], p_is_local boolean DEFAULT false)\n RETURNS uuid\n LANGUAGE plpgsql\n SECURITY DEFINER\nAS $function$\nDECLARE\n    result_record RECORD;\nBEGIN\n    SELECT * INTO result_record \n    FROM upsert_ap_activity(\n        p_ap_id,\n        p_ap_type,\n        p_actor_ap_id,\n        p_activity_data,\n        p_origin_domain,\n        p_to_addresses,\n        p_cc_addresses,\n        '{}', -- bto_addresses\n        '{}', -- bcc_addresses\n        p_is_local\n    );\n    \n    RETURN result_record.activity_id;\nEND;\n$function$\n"
