      "definition": "CREATE OR REPLACE FUNCTION public.is_user_in_conversation(user_uuid uuid, conversation_uuid uuid)\n RETURNS boolean\n LANGUAGE sql\n STABLE\nAS $function$\n  SELECT EXISTS(\n    SELECT 1 FROM conversation_participants \n    WHERE user_id = user_uuid \n      AND conversation_id = conversation_uuid \n      AND left_at IS NULL\n  );\n$function$\n"
    }
