      "definition": "CREATE OR REPLACE FUNCTION public.jsonb_agg_text_array(text_array text[])\n RETURNS jsonb\n LANGUAGE plpgsql\n IMMUTABLE\nAS $function$\nBEGIN\n    IF text_array IS NULL OR array_length(text_array, 1) IS NULL THEN\n        RETURN '[]'::jsonb;\n    END IF;\n    \n    RETURN (SELECT jsonb_agg(item) FROM unnest(text_array) AS item);\nEND;\n$function$\n"
    }
