      "function_name": "log_activity_processing_event",
      "return_type": "void",
      "arguments": "p_activity_id uuid, p_ap_id text, p_ap_type text, p_status text, p_error_message text DEFAULT NULL::text",
      "definition": "CREATE OR REPLACE FUNCTION public.log_activity_processing_event(p_activity_id uuid, p_ap_id text, p_ap_type text, p_status text, p_error_message text DEFAULT NULL::text)\n RETURNS void\n LANGUAGE plpgsql\nAS $function$\nBEGIN\n    INSERT INTO activity_processing_logs (activity_id, ap_id, ap_type, status, error_message, created_at, updated_at)\n    VALUES (p_activity_id, p_ap_id, p_ap_type, p_status, p_error_message, NOW(), NOW())\n    ON CONFLICT (activity_id) DO UPDATE \n    SET status = EXCLUDED.status,\n        attempts = activity_processing_logs.attempts + 1,\n        error_message = EXCLUDED.error_message,\n        updated_at = NOW(),\n        processed_at = CASE WHEN EXCLUDED.status = 'processed' THEN NOW() ELSE activity_processing_logs.processed_at END;\nEND;\n$function$\n"
    }
