      "arguments": "p_admin_id uuid, p_action_type text, p_target_type text DEFAULT NULL::text, p_target_id text DEFAULT NULL::text, p_action_details jsonb DEFAULT NULL::jsonb, p_ip_address inet DEFAULT NULL::inet, p_user_agent text DEFAULT NULL::text",
      "definition": "CREATE OR REPLACE FUNCTION public.log_admin_action(p_admin_id uuid, p_action_type text, p_target_type text DEFAULT NULL::text, p_target_id text DEFAULT NULL::text, p_action_details jsonb DEFAULT NULL::jsonb, p_ip_address inet DEFAULT NULL::inet, p_user_agent text DEFAULT NULL::text)\n RETURNS uuid\n LANGUAGE plpgsql\n SECURITY DEFINER\nAS $function$\nDECLARE\n    log_id UUID;\nBEGIN\n    INSERT INTO admin_audit_log (\n        admin_id,\n        action_type,\n        target_type,\n        target_id,\n        action_details,\n        ip_address,\n        user_agent\n    ) VALUES (\n        p_admin_id,\n        p_action_type,\n        p_target_type,\n        p_target_id,\n        p_action_details,\n        p_ip_address,\n        p_user_agent\n    ) RETURNING id INTO log_id;\n    \n    RETURN log_id;\nEND;\n$function$\n"
    }
