  {
    "function_json": {
      "function_name": "mark_notifications_read",
      "return_type": "integer",
      "arguments": "p_user_id uuid, p_notification_ids uuid[] DEFAULT NULL::uuid[]",
      "definition": "CREATE OR REPLACE FUNCTION public.mark_notifications_read(p_user_id uuid, p_notification_ids uuid[] DEFAULT NULL::uuid[])\n RETURNS integer\n LANGUAGE plpgsql\nAS $function$\nDECLARE\n    updated_count integer;\nBEGIN\n    IF p_notification_ids IS NULL THEN\n        -- Mark all unread notifications as read\n        UPDATE notifications \n        SET read_at = now(), is_read = true, updated_at = now()\n        WHERE user_id = p_user_id \n        AND read_at IS NULL;\n    ELSE\n        -- Mark specific notifications as read\n        UPDATE notifications \n        SET read_at = now(), is_read = true, updated_at = now()\n        WHERE user_id = p_user_id \n        AND id = ANY(p_notification_ids)\n        AND read_at IS NULL;\n    END IF;\n    \n    GET DIAGNOSTICS updated_count = ROW_COUNT;\n    RETURN updated_count;\nEND;\n$function$\n"
    }
  },
  {
    "function_json": {
      "function_name": "moderate_instance",
      "return_type": "boolean",
      "arguments": "p_admin_id uuid, p_domain text, p_action text, p_reason text DEFAULT NULL::text",
      "definition": "CREATE OR REPLACE FUNCTION public.moderate_instance(p_admin_id uuid, p_domain text, p_action text, p_reason text DEFAULT NULL::text)\n RETURNS boolean\n LANGUAGE plpgsql\n SECURITY DEFINER\nAS $function$\nBEGIN\n    -- Check if admin has permission\n    IF NOT EXISTS (SELECT 1 FROM profiles WHERE id = p_admin_id AND is_admin = TRUE) THEN\n        RAISE EXCEPTION 'Insufficient permissions';\n    END IF;\n    \n    IF p_action = 'block' THEN\n        INSERT INTO blocked_instances (domain, reason, blocked_by)\n        VALUES (p_domain, p_reason, p_admin_id)\n        ON CONFLICT (domain) DO UPDATE SET\n            reason = p_reason,\n            blocked_by = p_admin_id,\n            created_at = NOW();\n        \n        -- Log the action\n        PERFORM log_admin_action(\n            p_admin_id,\n            'instance_block',\n            'instance',\n            p_domain,\n            json_build_object('reason', p_reason)\n        );\n        \n    ELSIF p_action = 'unblock' THEN\n        DELETE FROM blocked_instances WHERE domain = p_domain;\n        \n        -- Log the action\n        PERFORM log_admin_action(\n            p_admin_id,\n            'instance_unblock',\n            'instance',\n            p_domain,\n            json_build_object()\n        );\n    ELSE\n        RAISE EXCEPTION 'Invalid action: %', p_action;\n    END IF;\n    \n    RETURN TRUE;\nEND;\n$function$\n"
    }
  },
  {
    "function_json": {
      "function_name": "moderate_user",
      "return_type": "boolean",
      "arguments": "p_admin_id uuid, p_target_user_id uuid, p_action text, p_reason text DEFAULT NULL::text",
      "definition": "CREATE OR REPLACE FUNCTION public.moderate_user(p_admin_id uuid, p_target_user_id uuid, p_action text, p_reason text DEFAULT NULL::text)\n RETURNS boolean\n LANGUAGE plpgsql\n SECURITY DEFINER\nAS $function$\nDECLARE\n    target_username TEXT;\nBEGIN\n    -- Check if admin has permission\n    IF NOT EXISTS (SELECT 1 FROM profiles WHERE id = p_admin_id AND is_admin = TRUE) THEN\n        RAISE EXCEPTION 'Insufficient permissions';\n    END IF;\n    \n    -- Get target username for logging\n    SELECT username INTO target_username FROM profiles WHERE id = p_target_user_id;\n    \n    IF p_action = 'suspend' THEN\n        UPDATE profiles \n        SET \n            is_suspended = TRUE,\n            suspended_at = NOW(),\n            suspension_reason = p_reason\n        WHERE id = p_target_user_id;\n        \n        -- Log the action\n        PERFORM log_admin_action(\n            p_admin_id,\n            'user_suspend',\n            'user',\n            p_target_user_id::TEXT,\n            json_build_object('reason', p_reason, 'username', target_username)\n        );\n        \n    ELSIF p_action = 'unsuspend' THEN\n        UPDATE profiles \n        SET \n            is_suspended = FALSE,\n            suspended_at = NULL,\n            suspension_reason = NULL\n        WHERE id = p_target_user_id;\n        \n        -- Log the action\n        PERFORM log_admin_action(\n            p_admin_id,\n            'user_unsuspend',\n            'user',\n            p_target_user_id::TEXT,\n            json_build_object('username', target_username)\n        );\n    ELSE\n        RAISE EXCEPTION 'Invalid action: %', p_action;\n    END IF;\n    \n    RETURN TRUE;\nEND;\n$function$\n"
    }
  },
  {
    "function_json": {
      "function_name": "normalize_hashtag",
      "return_type": "text",
      "arguments": "tag text",
      "definition": "CREATE OR REPLACE FUNCTION public.normalize_hashtag(tag text)\n RETURNS text\n LANGUAGE plpgsql\n IMMUTABLE\nAS $function$\nBEGIN\n    -- Remove # if present, convert to lowercase, keep only alphanumeric and underscore\n    RETURN regexp_replace(lower(ltrim(tag, '#')), '[^a-z0-9_]', '', 'g');\nEND;\n$function$\n"
    }
