    "function_json": {
      "function_name": "process_announce_activity",
      "return_type": "void",
      "arguments": "activity_id uuid, activity_data jsonb, actor_profile record",
      "definition": "CREATE OR REPLACE FUNCTION public.process_announce_activity(activity_id uuid, activity_data jsonb, actor_profile record)\n RETURNS void\n LANGUAGE plpgsql\nAS $function$\nDECLARE\n    v_object_id TEXT;\n    v_post_record RECORD;\n    v_ap_id TEXT;\nBEGIN\n    v_object_id := activity_data->>'object';\n    v_ap_id := activity_data->>'id';\n\n    -- Find the post being announced\n    SELECT * INTO v_post_record\n    FROM posts \n    WHERE ap_id = v_object_id;\n\n    IF FOUND THEN\n        -- Create the reblog interaction\n        INSERT INTO post_interactions (\n            user_id,\n            post_id,\n            interaction_type,\n            ap_id,\n            is_local,\n            created_at\n        ) VALUES (\n            actor_profile.id,\n            v_post_record.id,\n            'reblog',\n            v_ap_id,\n            false,\n            NOW()\n        ) ON CONFLICT (user_id, post_id, interaction_type) DO NOTHING;\n        \n        RAISE NOTICE '🔄 Post announced: % by %', v_object_id, actor_profile.username;\n    END IF;\nEND;\n$function$\n"
    }
  },
  {
    "function_json": {
      "function_name": "process_ap_activity_on_update",
      "return_type": "trigger",
      "arguments": "",
      "definition": "CREATE OR REPLACE FUNCTION public.process_ap_activity_on_update()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\nAS $function$\nDECLARE\n    v_instance_domain TEXT;\n    v_classification TEXT;\n    v_actor_profile_id UUID;\nBEGIN\n    -- Only process when status changes to 'processing'\n    IF NEW.status != 'processing' OR OLD.status = 'processing' THEN\n        RETURN NEW;\n    END IF;\n    \n    -- Get instance domain\n    SELECT trim(both '\"' from config_value::text) INTO v_instance_domain \n    FROM instance_config WHERE config_key = 'domain' LIMIT 1;\n    \n    IF v_instance_domain IS NULL THEN\n        RAISE WARNING 'No instance domain configured, skipping activity processing';\n        RETURN NEW;\n    END IF;\n    \n    -- Try to find actor profile (optional)\n    SELECT actor_id INTO v_actor_profile_id FROM ap_activities WHERE id = NEW.id;\n    \n    -- Classify the activity\n    v_classification := classify_activitypub_activity(NEW.activity_data, v_instance_domain);\n    \n    -- Route based on classification\n    CASE v_classification\n        WHEN 'private_mention' THEN\n            -- Process as incoming private message/DM\n            IF v_actor_profile_id IS NOT NULL THEN\n                PERFORM process_incoming_private_message(\n                    NEW.id,\n                    NEW.activity_data,\n                    v_actor_profile_id,\n                    v_instance_domain\n                );\n            ELSE\n                RAISE WARNING 'Actor profile not found for private mention activity %', NEW.id;\n            END IF;\n            \n        WHEN 'public_post' THEN\n            -- Process as public post (existing function)\n            IF v_actor_profile_id IS NOT NULL THEN\n                PERFORM process_activitypub_public_post(\n                    NEW.id,\n                    NEW.activity_data,\n                    (SELECT ROW(id, username, display_name, domain, federated_id, is_local, avatar_url, bio, created_at, updated_at) \n                     FROM profiles WHERE id = v_actor_profile_id),\n                    v_instance_domain\n                );\n            ELSE\n                RAISE WARNING 'Actor profile not found for public post activity %', NEW.id;\n            END IF;\n            \n        ELSE\n            RAISE WARNING 'Unknown activity classification: % for activity %', v_classification, NEW.id;\n    END CASE;\n    \n    -- Mark as completed\n    UPDATE ap_activities SET status = 'completed', processed_at = NOW() WHERE id = NEW.id;\n    \n    RETURN NEW;\n    \nEXCEPTION\n    WHEN OTHERS THEN\n        -- Mark as failed and log error\n        UPDATE ap_activities SET \n            status = 'failed', \n            error_message = SQLERRM,\n            processed_at = NOW()\n        WHERE id = NEW.id;\n        \n        RAISE WARNING 'Failed to process ActivityPub activity %: %', NEW.id, SQLERRM;\n        RETURN NEW;\nEND;\n$function$\n"
    }
  },
  {
    "function_json": {
      "function_name": "process_create_activity",
      "return_type": "void",
      "arguments": "activity_id uuid, activity_data jsonb, actor_profile record, instance_domain text",
      "definition": "CREATE OR REPLACE FUNCTION public.process_create_activity(activity_id uuid, activity_data jsonb, actor_profile record, instance_domain text)\n RETURNS void\n LANGUAGE plpgsql\nAS $function$\nDECLARE\n    v_object JSONB;\n    v_object_type TEXT;\n    v_is_dm BOOLEAN;\nBEGIN\n    v_object := activity_data->'object';\n    v_object_type := v_object->>'type';\n\n    IF v_object_type != 'Note' THEN\n        RAISE WARNING 'Create activity object is not a Note: %', v_object_type;\n        RETURN;\n    END IF;\n\n    -- Check if this is a direct message\n    v_is_dm := is_activitypub_direct_message(v_object, instance_domain);\n\n    IF v_is_dm THEN\n        RAISE NOTICE '📩 Processing as direct message';\n        PERFORM handle_incoming_messages(activity_id, activity_data, actor_profile, instance_domain);\n    ELSE\n        RAISE NOTICE '📢 Processing as public post';\n        PERFORM process_activitypub_public_post(activity_id, activity_data, actor_profile, instance_domain);\n    END IF;\nEND;\n$function$\n"
    }
  },
  {
    "function_json": {
      "function_name": "process_delete_activity",
      "return_type": "void",
      "arguments": "activity_id uuid, activity_data jsonb, actor_profile record",
      "definition": "CREATE OR REPLACE FUNCTION public.process_delete_activity(activity_id uuid, activity_data jsonb, actor_profile record)\n RETURNS void\n LANGUAGE plpgsql\nAS $function$\nDECLARE\n    v_object_id TEXT;\n    v_post_record RECORD;\nBEGIN\n    -- Object can be string ID or object with ID\n    v_object_id := CASE \n        WHEN jsonb_typeof(activity_data->'object') = 'string' \n        THEN activity_data->>'object'\n        ELSE activity_data->'object'->>'id'\n    END;\n    \n    -- Find and soft-delete the post\n    SELECT * INTO v_post_record\n    FROM posts \n    WHERE ap_id = v_object_id \n      AND author_id = actor_profile.id; -- Security: only author can delete\n    \n    IF FOUND THEN\n        UPDATE posts \n        SET is_deleted = true,\n            deleted_at = NOW(),\n            content = '[{\"type\": \"text\", \"text\": \"[deleted]\"}]'::jsonb\n        WHERE id = v_post_record.id;\n        \n        RAISE NOTICE '🗑️ Deleted post: %', v_object_id;\n    END IF;\nEND;\n$function$\n"
    }
  },
  {
    "function_json": {
      "function_name": "process_follow_activity",
      "return_type": "void",
      "arguments": "activity_id uuid, activity_data jsonb, actor_profile record, instance_domain text",
      "definition": "CREATE OR REPLACE FUNCTION public.process_follow_activity(activity_id uuid, activity_data jsonb, actor_profile record, instance_domain text)\n RETURNS void\n LANGUAGE plpgsql\nAS $function$\nDECLARE\n    v_following_url TEXT;\n    v_following_profile RECORD;\n    v_username TEXT;\n    v_follow_id UUID;\nBEGIN\n    -- Extract the user being followed\n    v_following_url := CASE \n        WHEN jsonb_typeof(activity_data->'object') = 'string' \n        THEN activity_data->>'object'\n        ELSE activity_data->'object'->>'id'\n    END;\n\n    -- Extract username from URL\n    v_username := substring(v_following_url from 'https://[^/]+/users/([^/]+)');\n    \n    IF v_username IS NULL THEN\n        RAISE WARNING 'Could not extract username from follow object: %', v_following_url;\n        RETURN;\n    END IF;\n\n    -- Get the local user being followed\n    SELECT * INTO v_following_profile\n    FROM profiles \n    WHERE username = v_username \n      AND domain = instance_domain \n      AND is_local = true;\n\n    IF NOT FOUND THEN\n        RAISE WARNING 'Local user not found: %', v_username;\n        RETURN;\n    END IF;\n\n    -- Create or update follow relationship\n    INSERT INTO follows (\n        follower_id,\n        following_id,\n        ap_id,\n        status,\n        accepted_at,\n        is_local,\n        created_at\n    ) VALUES (\n        actor_profile.id,\n        v_following_profile.id,\n        activity_data->>'id',\n        'accepted', -- Auto-accept for now\n        NOW(),\n        false,\n        NOW()\n    )\n    ON CONFLICT (follower_id, following_id) \n    DO UPDATE SET\n        ap_id = EXCLUDED.ap_id,\n        status = 'accepted',\n        accepted_at = NOW(),\n        updated_at = NOW()\n    RETURNING id INTO v_follow_id;\n\n    RAISE NOTICE '✅ Follow relationship created: % now follows %', \n        actor_profile.username, v_following_profile.username;\n\n    -- Note: Follow notifications are handled by the existing follow notification trigger\n    -- TODO: Send Accept activity back to follower (queue for federation)\nEND;\n$function$\n"
    }
  },
  {
    "function_json": {
      "function_name": "process_incoming_emoji_reaction",
      "return_type": "boolean",
      "arguments": "activity_data jsonb, actor_id uuid, target_object_id text",
      "definition": "CREATE OR REPLACE FUNCTION public.process_incoming_emoji_reaction(activity_data jsonb, actor_id uuid, target_object_id text)\n RETURNS boolean\n LANGUAGE plpgsql\nAS $function$\nDECLARE\n    emoji_content text;\n    emoji_name text;\n    emoji_url text;\n    emoji_id uuid;\n    target_message_id uuid;\n    target_post_id uuid;\n    reaction_exists boolean;\nBEGIN\n    -- Extract emoji information from activity\n    emoji_content := activity_data->>'content';\n    \n    -- Try to extract emoji from tags\n    IF activity_data ? 'tag' AND jsonb_array_length(activity_data->'tag') > 0 THEN\n        SELECT \n            (tag_item->>'name'),\n            (tag_item->'icon'->>'url')\n        INTO emoji_name, emoji_url\n        FROM jsonb_array_elements(activity_data->'tag') AS tag_item\n        WHERE tag_item->>'type' = 'Emoji'\n        LIMIT 1;\n        \n        -- Try to find matching local emoji\n        SELECT id INTO emoji_id\n        FROM emojis \n        WHERE name = trim(both ':' from emoji_name)\n        LIMIT 1;\n    END IF;\n\n    -- Determine target type and ID\n    IF target_object_id LIKE 'message-%' THEN\n        target_message_id := (regexp_match(target_object_id, 'message-(.+)'))[1]::uuid;\n        \n        -- Check if reaction already exists\n        SELECT EXISTS(\n            SELECT 1 FROM reactions \n            WHERE message_id = target_message_id \n              AND user_id = actor_id \n              AND emoji_id = COALESCE(emoji_id, (SELECT id FROM emojis WHERE name = 'thumbsup'))\n        ) INTO reaction_exists;\n        \n        -- Add reaction if it doesn't exist\n        IF NOT reaction_exists THEN\n            INSERT INTO reactions (message_id, user_id, emoji_id, is_local)\n            VALUES (target_message_id, actor_id, COALESCE(emoji_id, (SELECT id FROM emojis WHERE name = 'thumbsup')), false);\n        END IF;\n        \n    ELSIF target_object_id LIKE 'post-%' THEN\n        target_post_id := (regexp_match(target_object_id, 'post-(.+)'))[1]::uuid;\n        \n        -- Check if reaction already exists\n        SELECT EXISTS(\n            SELECT 1 FROM post_interactions \n            WHERE post_id = target_post_id \n              AND user_id = actor_id \n              AND interaction_type = 'emoji_reaction'\n              AND emoji_id = COALESCE(emoji_id, (SELECT id FROM emojis WHERE name = 'thumbsup'))\n        ) INTO reaction_exists;\n        \n        -- Add reaction if it doesn't exist\n        IF NOT reaction_exists THEN\n            INSERT INTO post_interactions (post_id, user_id, interaction_type, emoji_id, custom_emoji_content, is_local)\n            VALUES (target_post_id, actor_id, 'emoji_reaction', emoji_id, emoji_content, false);\n        END IF;\n    END IF;\n    \n    RETURN true;\nEND;\n$function$\n"
    }
  },
  {
    "function_json": {
      "function_name": "process_incoming_private_message",
      "return_type": "void",
      "arguments": "p_activity_id uuid, p_activity_data jsonb, p_actor_profile_id uuid, p_instance_domain text",
      "definition": "CREATE OR REPLACE FUNCTION public.process_incoming_private_message(p_activity_id uuid, p_activity_data jsonb, p_actor_profile_id uuid, p_instance_domain text)\n RETURNS void\n LANGUAGE plpgsql\n SECURITY DEFINER\nAS $function$\nDECLARE\n  v_object JSONB;\n  v_content JSONB;\n  v_local_recipients TEXT[];\n  v_recipient_username TEXT;\n  v_local_user profiles%ROWTYPE;\n  v_actor_profile profiles%ROWTYPE;\n  v_conversation_id UUID;\n  v_message_id UUID;\n  v_recipient_count INTEGER := 0;\n  v_is_dm BOOLEAN := false;\nBEGIN\n  -- Get actor profile\n  SELECT * INTO v_actor_profile FROM profiles WHERE id = p_actor_profile_id;\n  \n  IF NOT FOUND THEN\n    RAISE EXCEPTION 'Actor profile not found: %', p_actor_profile_id;\n  END IF;\n  \n  RAISE NOTICE '📨 Processing ActivityPub private message from %@%', \n    v_actor_profile.username, v_actor_profile.domain;\n  \n  -- Extract message object\n  v_object := p_activity_data->'object';\n  \n  -- Extract local recipients from addressing (compatible with all ActivityPub platforms)\n  WITH recipient_extraction AS (\n    SELECT jsonb_array_elements_text(\n      COALESCE(v_object->'to', '[]'::jsonb) || \n      COALESCE(v_object->'cc', '[]'::jsonb)\n    ) AS recipient_url\n  ),\n  -- Also extract from mention tags (Mastodon/Pleroma compatibility)\n  mention_extraction AS (\n    SELECT jsonb_array_elements(COALESCE(v_object->'tag', '[]'::jsonb)) AS tag\n  ),\n  mention_recipients AS (\n    SELECT tag->>'href' AS recipient_url\n    FROM mention_extraction\n    WHERE tag->>'type' = 'Mention'\n      AND tag->>'href' IS NOT NULL\n  ),\n  all_recipients AS (\n    SELECT recipient_url FROM recipient_extraction\n    UNION\n    SELECT recipient_url FROM mention_recipients\n  ),\n  local_recipients AS (\n    SELECT DISTINCT\n      CASE \n        WHEN recipient_url LIKE 'https://' || p_instance_domain || '/users/%' THEN\n          substring(recipient_url from 'https://' || p_instance_domain || '/users/([^/]+)')\n        WHEN recipient_url LIKE 'https://' || p_instance_domain || '/social/profile/%' THEN  \n          substring(recipient_url from 'https://' || p_instance_domain || '/social/profile/([^/]+)')\n        WHEN recipient_url LIKE 'https://' || p_instance_domain || '/@%' THEN\n          substring(recipient_url from 'https://' || p_instance_domain || '/@([^/]+)')\n        ELSE NULL\n      END AS username\n    FROM all_recipients\n  )\n  SELECT array_agg(username)\n  INTO v_local_recipients\n  FROM local_recipients \n  WHERE username IS NOT NULL;\n  \n  -- Validate recipients exist\n  IF v_local_recipients IS NULL OR array_length(v_local_recipients, 1) = 0 THEN\n    RAISE WARNING 'Private message from %@% has no valid local recipients - skipping',\n      v_actor_profile.username, v_actor_profile.domain;\n    RETURN;\n  END IF;\n  \n  RAISE NOTICE '📧 Private message mentions % local users: %', \n    array_length(v_local_recipients, 1), v_local_recipients;\n  \n  -- Check if this is actually a DM using the existing detection function\n  v_is_dm := is_activitypub_direct_message(v_object, p_instance_domain);\n  \n  -- Convert ActivityPub content to unified format\n  v_content := convert_ap_to_jsonb(\n    v_object->>'content',\n    v_object->'tag'\n  );\n  \n  -- 🔧 FIX: Strip redundant @user@domain mentions ONLY from DM content\n  IF v_is_dm THEN\n    v_content := strip_mentions_from_dm_content(v_content);\n    RAISE NOTICE '🧹 Stripped mentions from DM content';\n  ELSE\n    RAISE NOTICE '📢 Keeping mentions in non-DM message';\n  END IF;\n  \n  -- Process each local recipient\n  FOREACH v_recipient_username IN ARRAY v_local_recipients LOOP\n    -- Get local user profile\n    SELECT * INTO v_local_user\n    FROM profiles \n    WHERE username = v_recipient_username \n      AND domain = p_instance_domain \n      AND is_local = true;\n      \n    IF NOT FOUND THEN\n      RAISE WARNING 'Local recipient not found: %@%', v_recipient_username, p_instance_domain;\n      CONTINUE;\n    END IF;\n    \n    -- Get or create conversation between remote sender and local recipient\n    v_conversation_id := get_or_create_dm_conversation(\n      v_actor_profile.id,\n      v_local_user.id\n    );\n    \n    -- Insert the federated private message (with mentions stripped only if DM)\n    INSERT INTO messages (\n      conversation_id,\n      user_id,\n      content,\n      created_at,\n      metadata\n    ) VALUES (\n      v_conversation_id,\n      v_actor_profile.id,\n      v_content,\n      COALESCE((v_object->>'published')::timestamptz, NOW()),\n      jsonb_build_object(\n        'federated', true,\n        'ap_id', v_object->>'id',\n        'ap_type', 'Note',\n        'from_domain', v_actor_profile.domain,\n        'activity_id', p_activity_id,\n        'original_url', COALESCE(v_object->>'url', v_object->>'id'),\n        'private_mention', true,\n        'activitypub_compatible', true,\n        'is_dm', v_is_dm\n      )\n    ) RETURNING id INTO v_message_id;\n    \n    v_recipient_count := v_recipient_count + 1;\n    \n    RAISE NOTICE '✅ Saved federated private message %: %@% → %',\n      v_message_id, v_actor_profile.username, v_actor_profile.domain, v_recipient_username;\n  END LOOP;\n  \n  RAISE NOTICE '🎯 Completed private message processing for activity % (% recipients)',\n    p_activity_id, v_recipient_count;\nEND;\n$function$\n"
    }
  },
  {
    "function_json": {
      "function_name": "process_like_activity",
      "return_type": "void",
      "arguments": "activity_id uuid, activity_data jsonb, actor_profile record",
      "definition": "CREATE OR REPLACE FUNCTION public.process_like_activity(activity_id uuid, activity_data jsonb, actor_profile record)\n RETURNS void\n LANGUAGE plpgsql\nAS $function$\nDECLARE\n    v_object_id TEXT;\n    v_post_record RECORD;\n    v_ap_id TEXT;\nBEGIN\n    v_object_id := activity_data->>'object';\n    v_ap_id := activity_data->>'id';\n\n    -- Find the post being liked\n    SELECT * INTO v_post_record\n    FROM posts \n    WHERE ap_id = v_object_id;\n\n    IF FOUND THEN\n        -- Create the like interaction\n        INSERT INTO post_interactions (\n            user_id,\n            post_id,\n            interaction_type,\n            ap_id,\n            is_local,\n            created_at\n        ) VALUES (\n            actor_profile.id,\n            v_post_record.id,\n            'favorite',\n            v_ap_id,\n            false,\n            NOW()\n        ) ON CONFLICT (user_id, post_id, interaction_type) DO NOTHING;\n        \n        RAISE NOTICE '❤️ Post liked: % by %', v_object_id, actor_profile.username;\n    END IF;\nEND;\n$function$\n"
    }
  },
  {
    "function_json": {
      "function_name": "process_post_hashtags",
      "return_type": "integer",
      "arguments": "p_post_id uuid, p_content jsonb",
      "definition": "CREATE OR REPLACE FUNCTION public.process_post_hashtags(p_post_id uuid, p_content jsonb)\n RETURNS integer\n LANGUAGE plpgsql\nAS $function$\nDECLARE\n    v_hashtag_array TEXT[];\n    v_hashtag_text TEXT;\n    v_hashtag_id UUID;\n    v_position_counter INTEGER := 0;\n    v_processed_count INTEGER := 0;\nBEGIN\n    -- Extract hashtags from content\n    v_hashtag_array := extract_hashtags_from_content(p_content);\n    \n    -- Process each hashtag\n    FOREACH v_hashtag_text IN ARRAY v_hashtag_array LOOP\n        v_position_counter := v_position_counter + 1;\n        \n        -- Upsert hashtag and get ID\n        v_hashtag_id := upsert_hashtag(v_hashtag_text);\n        \n        -- Link post to hashtag\n        INSERT INTO post_hashtags (post_id, hashtag_id, position_in_content)\n        VALUES (p_post_id, v_hashtag_id, v_position_counter)\n        ON CONFLICT (post_id, hashtag_id) DO NOTHING;\n        \n        v_processed_count := v_processed_count + 1;\n    END LOOP;\n    \n    RETURN v_processed_count;\nEND;\n$function$\n"
    }
  },
  {
    "function_json": {
      "function_name": "process_reject_activity",
      "return_type": "void",
      "arguments": "activity_id uuid, activity_data jsonb, actor_profile record",
      "definition": "CREATE OR REPLACE FUNCTION public.process_reject_activity(activity_id uuid, activity_data jsonb, actor_profile record)\n RETURNS void\n LANGUAGE plpgsql\nAS $function$\nDECLARE\n    v_object JSONB;\n    v_original_follow_id TEXT;\n    v_follow_record RECORD;\nBEGIN\n    v_object := activity_data->'object';\n    \n    -- Handle Reject of Follow activities\n    IF v_object->>'type' = 'Follow' THEN\n        v_original_follow_id := v_object->>'id';\n        \n        -- Find the follow request in our database\n        SELECT * INTO v_follow_record\n        FROM follows \n        WHERE ap_id = v_original_follow_id \n          AND status = 'pending';\n        \n        IF FOUND THEN\n            -- Update follow status to rejected (or delete)\n            UPDATE follows \n            SET status = 'rejected',\n                updated_at = NOW()\n            WHERE id = v_follow_record.id;\n            \n            RAISE NOTICE '❌ Follow request rejected: % -> %', \n                v_follow_record.follower_id, v_follow_record.following_id;\n        END IF;\n    END IF;\nEND;\n$function$\n"
    }
  },
  {
    "function_json": {
      "function_name": "process_trending_queue",
      "return_type": "integer",
      "arguments": "",
      "definition": "CREATE OR REPLACE FUNCTION public.process_trending_queue()\n RETURNS integer\n LANGUAGE plpgsql\nAS $function$\nDECLARE\n    queue_item RECORD;\n    processed_count INTEGER := 0;\nBEGIN\n    -- Process high priority items first\n    FOR queue_item IN \n        SELECT * FROM trending_refresh_queue \n        WHERE NOT is_processing \n        AND (processing_started_at IS NULL OR processing_started_at < NOW() - INTERVAL '10 minutes')\n        ORDER BY \n            CASE priority \n                WHEN 'high' THEN 1 \n                WHEN 'normal' THEN 2 \n                ELSE 3 \n            END,\n            updated_at ASC\n        LIMIT 3 -- Process max 3 items per run\n    LOOP\n        CASE queue_item.refresh_type\n            WHEN 'hashtags' THEN\n                PERFORM update_hashtag_trending_scores_efficient();\n            WHEN 'posts' THEN\n                PERFORM update_trending_posts();\n            WHEN 'users' THEN\n                PERFORM update_trending_users();\n        END CASE;\n        \n        processed_count := processed_count + 1;\n    END LOOP;\n    \n    RETURN processed_count;\nEND;\n$function$\n"
    }
  },
  {
    "function_json": {
      "function_name": "process_undo_activity",
      "return_type": "void",
      "arguments": "activity_id uuid, activity_data jsonb, actor_profile record",
      "definition": "CREATE OR REPLACE FUNCTION public.process_undo_activity(activity_id uuid, activity_data jsonb, actor_profile record)\n RETURNS void\n LANGUAGE plpgsql\nAS $function$\nDECLARE\n    v_object JSONB;\n    v_original_activity_id TEXT;\n    v_object_type TEXT;\nBEGIN\n    v_object := activity_data->'object';\n    v_original_activity_id := v_object->>'id';\n    v_object_type := v_object->>'type';\n    \n    CASE v_object_type\n        WHEN 'Follow' THEN\n            -- Undo follow = unfollow\n            DELETE FROM follows \n            WHERE ap_id = v_original_activity_id \n              AND follower_id = actor_profile.id;\n        \n            RAISE NOTICE '🔄 Undone follow activity: %', v_original_activity_id;\n        \n        WHEN 'Like' THEN\n            -- Undo like = unfavorite\n            DELETE FROM post_interactions \n            WHERE ap_id = v_original_activity_id \n              AND user_id = actor_profile.id \n              AND interaction_type = 'favorite';\n          \n            RAISE NOTICE '🔄 Undone like activity: %', v_original_activity_id;\n        \n        WHEN 'Announce' THEN\n            -- Undo announce = unreblog\n            DELETE FROM post_interactions \n            WHERE ap_id = v_original_activity_id \n              AND user_id = actor_profile.id \n              AND interaction_type = 'reblog';\n          \n            RAISE NOTICE '🔄 Undone announce activity: %', v_original_activity_id;\n        \n        ELSE\n            RAISE NOTICE '⚠️ Unhandled undo object type: %', v_object_type;\n    END CASE;\nEND;\n$function$\n"
    }
  },
  {
    "function_json": {
      "function_name": "process_update_activity",
      "return_type": "void",
      "arguments": "activity_id uuid, activity_data jsonb, actor_profile record",
      "definition": "CREATE OR REPLACE FUNCTION public.process_update_activity(activity_id uuid, activity_data jsonb, actor_profile record)\n RETURNS void\n LANGUAGE plpgsql\nAS $function$\nDECLARE\n    v_object JSONB;\n    v_object_id TEXT;\n    v_object_type TEXT;\n    v_post_record RECORD;\n    v_content JSONB;\nBEGIN\n    v_object := activity_data->'object';\n    v_object_id := v_object->>'id';\n    v_object_type := v_object->>'type';\n    \n    CASE v_object_type\n        WHEN 'Note' THEN\n            -- Handle Note updates (post edits)\n            -- Find the existing post\n            SELECT * INTO v_post_record\n            FROM posts \n            WHERE ap_id = v_object_id;\n            \n            IF FOUND THEN\n                -- Convert ActivityPub content to our format\n                v_content := parse_activitypub_content_to_jsonb(\n                    v_object->>'content', \n                    v_object->'tag'\n                );\n                \n                -- Update the post\n                UPDATE posts \n                SET content = v_content,\n                    content_warning = v_object->>'summary',\n                    is_sensitive = COALESCE((v_object->>'sensitive')::boolean, false),\n                    updated_at = NOW(),\n                    edited_at = NOW()\n                WHERE id = v_post_record.id;\n                \n                RAISE NOTICE '📝 Updated post: %', v_object_id;\n            END IF;\n            \n        WHEN 'Person' THEN\n            -- Handle Person updates (profile updates)\n            RAISE NOTICE '👤 Processing profile update for: %', v_object_id;\n            \n            -- Verify this update is from the profile owner\n            IF actor_profile.federated_id != v_object_id THEN\n                RAISE WARNING 'Profile update rejected: actor % cannot update profile %', \n                    actor_profile.federated_id, v_object_id;\n                RETURN;\n            END IF;\n            \n            -- Update the profile with new information\n            -- Handle both direct fields and nested objects (like icon/image)\n            UPDATE profiles \n            SET \n                display_name = COALESCE(v_object->>'name', display_name),\n                bio = COALESCE(v_object->>'summary', bio),\n                avatar_url = CASE \n                    WHEN v_object->'icon'->>'type' = 'Image' THEN v_object->'icon'->>'url'\n                    WHEN v_object->>'icon' IS NOT NULL THEN v_object->>'icon'\n                    ELSE avatar_url\n                END,\n                banner_url = CASE \n                    WHEN v_object->'image'->>'type' = 'Image' THEN v_object->'image'->>'url'\n                    WHEN v_object->>'image' IS NOT NULL THEN v_object->>'image'\n                    ELSE banner_url\n                END,\n                public_key = COALESCE(v_object->'publicKey'->>'publicKeyPem', public_key),\n                inbox_url = COALESCE(v_object->>'inbox', inbox_url),\n                outbox_url = COALESCE(v_object->>'outbox', outbox_url),\n                followers_url = COALESCE(v_object->>'followers', followers_url),\n                following_url = COALESCE(v_object->>'following', following_url),\n                updated_at = NOW(),\n                last_synced_at = NOW()\n            WHERE federated_id = v_object_id \n              AND NOT is_local; -- Only update federated profiles\n            \n            IF FOUND THEN\n                RAISE NOTICE '✅ Updated profile: %', v_object_id;\n                \n                -- Log the updated fields for debugging\n                RAISE NOTICE 'Profile update details - name: %, summary: %, icon: %, image: %',\n                    v_object->>'name',\n                    v_object->>'summary',\n                    COALESCE(v_object->'icon'->>'url', v_object->>'icon'),\n                    COALESCE(v_object->'image'->>'url', v_object->>'image');\n            ELSE\n                RAISE WARNING 'Profile not found for update: %', v_object_id;\n            END IF;\n            \n        ELSE\n            RAISE NOTICE 'Unhandled Update object type: %', v_object_type;\n    END CASE;\nEND;\n$function$\n"
    }
  },
  {
    "function_json": {
      "function_name": "queue_activity_for_federation",
      "return_type": "void",
      "arguments": "p_activity_id uuid, p_target_domains text[], p_priority integer DEFAULT 5, p_immediate boolean DEFAULT true",
      "definition": "CREATE OR REPLACE FUNCTION public.queue_activity_for_federation(p_activity_id uuid, p_target_domains text[], p_priority integer DEFAULT 5, p_immediate boolean DEFAULT true)\n RETURNS void\n LANGUAGE plpgsql\nAS $function$\nDECLARE\n    domain text;\n    inbox_url text;\n    next_attempt timestamptz;\n    activity_record RECORD;\n    actor_username TEXT;\n    actor_domain TEXT;\nBEGIN\n    -- Get activity metadata including the activity data\n    SELECT \n        aa.actor_ap_id,\n        aa.origin_domain,\n        aa.activity_data\n    INTO activity_record\n    FROM ap_activities aa\n    WHERE aa.id = p_activity_id;\n\n    IF NOT FOUND THEN\n        RAISE WARNING 'Activity % not found, cannot queue for federation', p_activity_id;\n        RETURN;\n    END IF;\n\n    -- Extract username from actor AP ID\n    actor_username := regexp_replace(activity_record.actor_ap_id, '^https?://[^/]+/users/([^/#]+).*$', '\\1');\n    actor_domain := activity_record.origin_domain;\n    \n    -- Set timing for delivery attempt\n    next_attempt := CASE \n        WHEN p_immediate THEN now()\n        ELSE now() + interval '1 minute'\n    END;\n    \n    FOREACH domain IN ARRAY p_target_domains LOOP\n        inbox_url := 'https://' || domain || '/inbox';\n        \n        INSERT INTO federation_delivery_queue (\n            activity_id,\n            activity_data,  -- Include the activity data\n            target_domain,\n            target_inbox_url,\n            actor_username,\n            actor_domain,\n            status,\n            priority,\n            attempts,\n            next_attempt_at\n        ) VALUES (\n            p_activity_id,\n            activity_record.activity_data,  -- Store the activity data\n            domain,\n            inbox_url,\n            actor_username,\n            actor_domain,\n            'pending',\n            p_priority,\n            0,\n            next_attempt\n        );\n    END LOOP;\n\n    RAISE NOTICE '📦 Queued activity % for federation to % domains', p_activity_id, array_length(p_target_domains, 1);\nEND;\n$function$\n"
    }
  },
  {
    "function_json": {
      "function_name": "reconcile_social_counters",
      "return_type": "record",
      "arguments": "p_profile_id uuid DEFAULT NULL::uuid",
      "definition": "CREATE OR REPLACE FUNCTION public.reconcile_social_counters(p_profile_id uuid DEFAULT NULL::uuid)\n RETURNS TABLE(profile_id uuid, old_followers_count integer, new_followers_count integer, old_following_count integer, new_following_count integer, old_posts_count integer, new_posts_count integer, was_corrected boolean)\n LANGUAGE plpgsql\nAS $function$\nDECLARE\n    profile_record RECORD;\n    actual_followers INTEGER;\n    actual_following INTEGER;\n    actual_posts INTEGER;\n    correction_made BOOLEAN := FALSE;\nBEGIN\n    -- If specific profile provided, only check that one\n    FOR profile_record IN \n        SELECT p.id, p.followers_count, p.following_count, p.posts_count\n        FROM profiles p\n        WHERE (p_profile_id IS NULL OR p.id = p_profile_id)\n    LOOP\n        -- Calculate actual counts\n        SELECT COUNT(*) INTO actual_followers\n        FROM follows \n        WHERE following_id = profile_record.id \n        AND status = 'accepted';\n        \n        SELECT COUNT(*) INTO actual_following\n        FROM follows \n        WHERE follower_id = profile_record.id \n        AND status = 'accepted';\n        \n        SELECT COUNT(*) INTO actual_posts\n        FROM posts \n        WHERE author_id = profile_record.id \n        AND deleted_at IS NULL;\n        \n        -- Check if correction needed\n        correction_made := (\n            profile_record.followers_count != actual_followers OR\n            profile_record.following_count != actual_following OR\n            profile_record.posts_count != actual_posts\n        );\n        \n        -- Update if needed\n        IF correction_made THEN\n            UPDATE profiles SET\n                followers_count = actual_followers,\n                following_count = actual_following,\n                posts_count = actual_posts\n            WHERE id = profile_record.id;\n        END IF;\n        \n        -- Return the results\n        RETURN QUERY SELECT\n            profile_record.id as profile_id,\n            profile_record.followers_count as old_followers_count,\n            actual_followers as new_followers_count,\n            profile_record.following_count as old_following_count,\n            actual_following as new_following_count,\n            profile_record.posts_count as old_posts_count,\n            actual_posts as new_posts_count,\n            correction_made as was_corrected;\n    END LOOP;\nEND;\n$function$\n"
    }
  },
  {
    "function_json": {
      "function_name": "record_emoji_usage",
      "return_type": "void",
      "arguments": "p_emoji_id uuid, p_user_id uuid, p_server_id uuid, p_context_type text, p_context_id uuid DEFAULT NULL::uuid",
      "definition": "CREATE OR REPLACE FUNCTION public.record_emoji_usage(p_emoji_id uuid, p_user_id uuid, p_server_id uuid, p_context_type text, p_context_id uuid DEFAULT NULL::uuid)\n RETURNS void\n LANGUAGE plpgsql\nAS $function$\nBEGIN\n    -- Insert usage record (ignore if duplicate due to unique constraint)\n    INSERT INTO emoji_usage (emoji_id, user_id, server_id, context_type, context_id)\n    VALUES (p_emoji_id, p_user_id, p_server_id, p_context_type, p_context_id)\n    ON CONFLICT (emoji_id, user_id, context_type, context_id) DO NOTHING;\n    \n    -- Update emoji global usage count and last_used\n    UPDATE emojis \n    SET \n        usage_count = (\n            SELECT COUNT(DISTINCT (user_id, context_type, context_id))\n            FROM emoji_usage \n            WHERE emoji_id = p_emoji_id\n        ),\n        last_used = now(),\n        updated_at = now()\n    WHERE id = p_emoji_id;\nEND;\n$function$\n"
    }
  },
  {
    "function_json": {
      "function_name": "regenerate_all_activitypub_keys",
      "return_type": "text",
      "arguments": "",
      "definition": "CREATE OR REPLACE FUNCTION public.regenerate_all_activitypub_keys()\n RETURNS text\n LANGUAGE plpgsql\n SECURITY DEFINER\nAS $function$\nDECLARE\n    user_record RECORD;\n    updated_count INTEGER := 0;\n    error_count INTEGER := 0;\n    result_message TEXT;\nBEGIN\n    -- Loop through all local users\n    FOR user_record IN \n        SELECT id, username, domain\n        FROM profiles \n        WHERE is_local = true\n    LOOP\n        BEGIN\n            PERFORM add_activitypub_keys_to_user(user_record.id);\n            updated_count := updated_count + 1;\n        EXCEPTION \n            WHEN OTHERS THEN\n                error_count := error_count + 1;\n                RAISE WARNING 'Failed to generate keys for user %: %', user_record.username, SQLERRM;\n        END;\n    END LOOP;\n    \n    result_message := format('ActivityPub key regeneration complete. Updated: %s users, Errors: %s users', \n                            updated_count, error_count);\n    \n    RAISE NOTICE '%', result_message;\n    RETURN result_message;\nEND;\n$function$\n"
    }
  },
  {
    "function_json": {
      "function_name": "remove_group_icon",
      "return_type": "jsonb",
      "arguments": "conversation_uuid uuid, user_profile_id uuid",
      "definition": "CREATE OR REPLACE FUNCTION public.remove_group_icon(conversation_uuid uuid, user_profile_id uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\nAS $function$\nDECLARE\n  is_participant BOOLEAN := false;\n  conversation_exists BOOLEAN := false;\nBEGIN\n  -- Check if user is a participant in the conversation\n  SELECT can_manage_group_icon(conversation_uuid, user_profile_id) INTO is_participant;\n  \n  IF NOT is_participant THEN\n    RETURN jsonb_build_object(\n      'success', false,\n      'error', 'User is not a participant in this conversation'\n    );\n  END IF;\n  \n  -- Check if conversation exists and is a group\n  SELECT EXISTS(\n    SELECT 1 FROM conversations \n    WHERE id = conversation_uuid AND type = 'group'\n  ) INTO conversation_exists;\n  \n  IF NOT conversation_exists THEN\n    RETURN jsonb_build_object(\n      'success', false,\n      'error', 'Group conversation not found'\n    );\n  END IF;\n  \n  -- Remove icon from conversation metadata\n  UPDATE conversations \n  SET \n    metadata = COALESCE(metadata, '{}'::jsonb) - 'icon_url',\n    updated_at = CURRENT_TIMESTAMP\n  WHERE id = conversation_uuid\n    AND type = 'group';\n  \n  RETURN jsonb_build_object(\n    'success', true,\n    'message', 'Group icon removed successfully'\n  );\nEND;\n$function$\n"
    }
  },
  {
    "function_json": {
      "function_name": "remove_post_emoji_reaction",
      "return_type": "boolean",
      "arguments": "p_user_id uuid, p_post_id uuid, p_emoji_id uuid DEFAULT NULL::uuid, p_custom_emoji_content text DEFAULT NULL::text",
      "definition": "CREATE OR REPLACE FUNCTION public.remove_post_emoji_reaction(p_user_id uuid, p_post_id uuid, p_emoji_id uuid DEFAULT NULL::uuid, p_custom_emoji_content text DEFAULT NULL::text)\n RETURNS boolean\n LANGUAGE plpgsql\n SECURITY DEFINER\nAS $function$\nDECLARE\n    v_deleted_count integer;\nBEGIN\n    DELETE FROM post_interactions \n    WHERE user_id = p_user_id\n      AND post_id = p_post_id \n      AND interaction_type = 'emoji_reaction'\n      AND (\n          (p_emoji_id IS NOT NULL AND emoji_id = p_emoji_id) OR\n          (p_custom_emoji_content IS NOT NULL AND custom_emoji_content = p_custom_emoji_content)\n      );\n    \n    GET DIAGNOSTICS v_deleted_count = ROW_COUNT;\n    RETURN v_deleted_count > 0;\nEND;\n$function$\n"
    }
  },
  {
    "function_json": {
      "function_name": "reset_daily_hashtag_counters",
      "return_type": "integer",
      "arguments": "",
      "definition": "CREATE OR REPLACE FUNCTION public.reset_daily_hashtag_counters()\n RETURNS integer\n LANGUAGE plpgsql\nAS $function$\nDECLARE\n    reset_count INTEGER;\nBEGIN\n    UPDATE hashtags \n    SET daily_uses = 0\n    WHERE daily_uses > 0;\n    \n    GET DIAGNOSTICS reset_count = ROW_COUNT;\n    RETURN reset_count;\nEND;\n$function$\n"
    }
  },
  {
    "function_json": {
      "function_name": "reset_weekly_hashtag_counters",
      "return_type": "integer",
      "arguments": "",
      "definition": "CREATE OR REPLACE FUNCTION public.reset_weekly_hashtag_counters()\n RETURNS integer\n LANGUAGE plpgsql\nAS $function$\nDECLARE\n    reset_count INTEGER;\nBEGIN\n    UPDATE hashtags \n    SET weekly_uses = 0\n    WHERE weekly_uses > 0;\n    \n    GET DIAGNOSTICS reset_count = ROW_COUNT;\n    RETURN reset_count;\nEND;\n$function$\n"
    }
  },
  {
    "function_json": {
      "function_name": "resume_activitypub_cron_jobs",
      "return_type": "text",
      "arguments": "",
      "definition": "CREATE OR REPLACE FUNCTION public.resume_activitypub_cron_jobs()\n RETURNS text\n LANGUAGE plpgsql\n SECURITY DEFINER\nAS $function$\nDECLARE\n    result TEXT := '';\n    schedule_result TEXT;\nBEGIN\n    SELECT cron.schedule(\n        'activitypub-retry-processor', \n        '*/5 * * * *', \n        'SELECT process_failed_activities_retry();'\n    ) INTO schedule_result;\n    SELECT cron.schedule(\n        'activitypub-cleanup-old-activities',\n        '0 3 * * *',\n        'DELETE FROM ap_activities WHERE status = ''processed'' AND created_at < NOW() - INTERVAL ''30 days'' AND attempts < 3;'\n    ) INTO schedule_result;\n    SELECT cron.schedule(\n        'activitypub-daily-stats',\n        '0 1 * * *',\n        'INSERT INTO activitypub_processing_stats (date, total_activities, processed_activities, failed_activities, permanently_failed_activities, avg_processing_time_ms) SELECT CURRENT_DATE - INTERVAL ''1 day'', COUNT(*), COUNT(*) FILTER (WHERE status = ''processed''), COUNT(*) FILTER (WHERE status = ''failed''), COUNT(*) FILTER (WHERE status = ''permanently_failed''), AVG(EXTRACT(EPOCH FROM (updated_at - created_at)) * 1000) FROM ap_activities WHERE created_at >= CURRENT_DATE - INTERVAL ''1 day'' AND created_at < CURRENT_DATE;'\n    ) INTO schedule_result;\n    result := 'ActivityPub cron jobs have been resumed';\n    RETURN result;\nEND;\n$function$\n"
    }
  },
  {
    "function_json": {
      "function_name": "resume_trending_cron_jobs",
      "return_type": "text",
      "arguments": "",
      "definition": "CREATE OR REPLACE FUNCTION public.resume_trending_cron_jobs()\n RETURNS text\n LANGUAGE plpgsql\n SECURITY DEFINER\nAS $function$\nDECLARE\n    result TEXT := '';\n    schedule_result TEXT;\nBEGIN\n    -- Re-create all the cron jobs using SELECT instead of PERFORM\n    SELECT cron.schedule('process-trending-queue', '*/15 * * * *', 'SELECT process_trending_queue();') INTO schedule_result;\n    SELECT cron.schedule('reset-daily-hashtag-counts', '0 0 * * *', 'SELECT reset_daily_hashtag_counts();') INTO schedule_result;\n    SELECT cron.schedule('reset-weekly-hashtag-counts', '0 1 * * 0', 'SELECT reset_weekly_hashtag_counts();') INTO schedule_result;\n    SELECT cron.schedule('cleanup-trending-queue', '0 2 * * *', 'SELECT cleanup_trending_queue();') INTO schedule_result;\n    SELECT cron.schedule('cleanup-old-trending-data', '0 3 * * 0', 'SELECT cleanup_old_trending_data();') INTO schedule_result;\n    SELECT cron.schedule('cleanup-inactive-hashtags', '0 4 1 * *', 'SELECT cleanup_inactive_hashtags();') INTO schedule_result;\n    \n    result := 'All trending cron jobs have been resumed';\n    RETURN result;\nEND;\n$function$\n"
    }
  },
  {
    "function_json": {
      "function_name": "run_trending_maintenance",
      "return_type": "json",
      "arguments": "",
      "definition": "CREATE OR REPLACE FUNCTION public.run_trending_maintenance()\n RETURNS json\n LANGUAGE plpgsql\nAS $function$\nDECLARE\n    result JSON;\n    hashtags_cleaned INTEGER;\n    trending_cleaned INTEGER;\n    hashtags_archived INTEGER;\n    scores_updated INTEGER;\nBEGIN\n    -- Archive popular hashtags before cleanup\n    hashtags_archived := archive_popular_hashtags();\n    \n    -- Clean up inactive hashtags\n    hashtags_cleaned := cleanup_inactive_hashtags();\n    \n    -- Clean up old trending data\n    trending_cleaned := cleanup_old_trending_data();\n    \n    -- Update trending scores\n    scores_updated := update_hashtag_trending_scores();\n    \n    -- Update trending posts\n    PERFORM update_trending_posts();\n    \n    -- Build result\n    result := json_build_object(\n        'maintenance_completed_at', NOW(),\n        'hashtags_archived', hashtags_archived,\n        'hashtags_cleaned', hashtags_cleaned,\n        'trending_data_cleaned', trending_cleaned,\n        'trending_scores_updated', scores_updated,\n        'status', 'success'\n    );\n    \n    RAISE NOTICE 'Trending system maintenance completed: %', result;\n    RETURN result;\nEND;\n$function$\n"
    }
  },
  {
    "function_json": {
      "function_name": "search_federated_users",
      "return_type": "record",
      "arguments": "p_query text, p_limit integer DEFAULT 10",
      "definition": "CREATE OR REPLACE FUNCTION public.search_federated_users(p_query text, p_limit integer DEFAULT 10)\n RETURNS TABLE(user_id uuid, username text, display_name text, domain text, avatar_url text, handle text, is_local boolean)\n LANGUAGE plpgsql\nAS $function$\nBEGIN\n    RETURN QUERY\n    SELECT \n        p.id as user_id,\n        p.username,\n        p.display_name,\n        p.domain,\n        p.avatar_url,\n        get_user_handle(p.id) as handle,\n        p.is_local\n    FROM profiles p\n    WHERE (\n        p.username ILIKE '%' || p_query || '%'\n        OR p.display_name ILIKE '%' || p_query || '%'\n        OR (p.username || '@' || p.domain) ILIKE '%' || p_query || '%'\n    )\n    ORDER BY \n        CASE WHEN p.is_local THEN 0 ELSE 1 END,\n        p.username\n    LIMIT p_limit;\nEND;\n$function$\n"
    }
  },
  {
    "function_json": {
      "function_name": "send_accept_activity_for_follow",
      "return_type": "void",
      "arguments": "follow_activity_id uuid, local_user_id uuid",
      "definition": "CREATE OR REPLACE FUNCTION public.send_accept_activity_for_follow(follow_activity_id uuid, local_user_id uuid)\n RETURNS void\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'extensions', 'public', 'pg_temp'\nAS $function$\nDECLARE\n    v_follow_activity RECORD;\n    v_local_profile RECORD;\n    v_instance_domain TEXT;\n    v_accept_id TEXT;\n    v_accept_activity JSONB;\n    v_activity_uuid UUID;\n    v_inbox_url TEXT;\n    v_signature_header TEXT;\n    v_date_header TEXT;\n    v_digest_header TEXT;\n    v_http_status INTEGER;\n    v_http_response TEXT;\n    v_delivery_success BOOLEAN;\n    v_follower_domain TEXT;\nBEGIN\n    RAISE NOTICE '📤 Sending Accept activity for follow: %', follow_activity_id;\n    \n    -- Get the Follow activity we're accepting\n    SELECT * INTO v_follow_activity\n    FROM ap_activities \n    WHERE id = follow_activity_id\n    AND ap_type = 'Follow';\n    \n    IF NOT FOUND THEN\n        RAISE WARNING 'Follow activity not found: %', follow_activity_id;\n        RETURN;\n    END IF;\n    \n    -- Get the local user profile\n    SELECT * INTO v_local_profile\n    FROM profiles \n    WHERE id = local_user_id\n    AND is_local = true;\n    \n    IF NOT FOUND THEN\n        RAISE WARNING 'Local user not found: %', local_user_id;\n        RETURN;\n    END IF;\n    \n    -- Get instance domain\n    SELECT trim(both '\"' from config_value::text) INTO v_instance_domain \n    FROM instance_config \n    WHERE config_key = 'domain' \n    LIMIT 1;\n    \n    IF v_instance_domain IS NULL THEN\n        RAISE WARNING 'Instance domain not configured, cannot send Accept';\n        RETURN;\n    END IF;\n    \n    -- Create Accept activity\n    v_accept_id := 'https://' || v_instance_domain || '/users/' || v_local_profile.username || '#accepts/' || extract(epoch from now())::bigint;\n    \n    v_accept_activity := jsonb_build_object(\n        '@context', 'https://www.w3.org/ns/activitystreams',\n        'id', v_accept_id,\n        'type', 'Accept',\n        'actor', 'https://' || v_instance_domain || '/users/' || v_local_profile.username,\n        'object', v_follow_activity.activity_data\n    );\n    \n    RAISE NOTICE '📋 Created Accept activity: %', v_accept_id;\n    \n    -- Store the Accept activity in our database\n    INSERT INTO ap_activities (\n        ap_id,\n        ap_type,\n        actor_id,\n        actor_ap_id,\n        object_id,\n        object_type,\n        activity_data,\n        status,\n        to_addresses,\n        is_local,\n        origin_domain\n    ) VALUES (\n        v_accept_id,\n        'Accept',\n        local_user_id,\n        'https://' || v_instance_domain || '/users/' || v_local_profile.username,\n        v_follow_activity.ap_id,\n        'Follow',\n        v_accept_activity,\n        'pending',\n        ARRAY[v_follow_activity.actor_ap_id],\n        true,\n        v_instance_domain\n    ) RETURNING id INTO v_activity_uuid;\n    \n    -- Extract follower domain for inbox URL\n    v_follower_domain := (SELECT domain FROM profiles WHERE federated_id = v_follow_activity.actor_ap_id OR id = (\n        SELECT id FROM profiles WHERE federated_id = v_follow_activity.actor_ap_id LIMIT 1\n    ));\n    \n    IF v_follower_domain IS NULL THEN\n        -- Try to extract domain from actor URL\n        v_follower_domain := substring(v_follow_activity.actor_ap_id from 'https://([^/]+)/');\n    END IF;\n    \n    IF v_follower_domain IS NULL THEN\n        RAISE WARNING 'Could not determine follower domain from: %', v_follow_activity.actor_ap_id;\n        RETURN;\n    END IF;\n    \n    -- Construct inbox URL (user-specific for better delivery)\n    v_inbox_url := v_follow_activity.actor_ap_id || '/inbox';\n    \n    RAISE WARNING '📮 Sending Accept to inbox: %', v_inbox_url;\n    \n    -- Generate HTTP signature\n    BEGIN\n        SELECT \n            signature_header,\n            date_header,\n            digest_header\n        INTO \n            v_signature_header,\n            v_date_header,\n            v_digest_header\n        FROM create_http_signature(\n            v_inbox_url,\n            v_accept_activity::text,\n            v_local_profile.username,\n            v_instance_domain,\n            'POST'\n        );\n        \n        RAISE NOTICE 'Generated HTTP signature for Accept to %', v_follower_domain;\n        \n    EXCEPTION \n        WHEN OTHERS THEN\n            RAISE WARNING 'Failed to generate signature for Accept: %', SQLERRM;\n            -- Update activity as failed and return\n            UPDATE ap_activities \n            SET status = 'failed',\n                error_message = 'Signature generation failed: ' || SQLERRM\n            WHERE id = v_activity_uuid;\n            RETURN;\n    END;\n    \n    -- Attempt immediate delivery\n    BEGIN\n        RAISE WARNING '🚀 Attempting Accept delivery to: %', v_inbox_url;\n\n        -- Try to deliver immediately using Supabase HTTP extension\n        SELECT status, content INTO v_http_status, v_http_response\n        FROM http((\n            'POST',\n            v_inbox_url,\n            ARRAY[\n                ('Content-Type', 'application/activity+json'),\n                ('User-Agent', 'Harmony/1.0.0'),\n                ('Host', v_follower_domain),\n                ('Date', v_date_header),\n                ('Digest', v_digest_header),\n                ('Signature', v_signature_header)\n            ]::http_header[],\n            'application/activity+json',\n            v_accept_activity::text\n        )::http_request);\n        \n        -- Check delivery success\n        v_delivery_success := (v_http_status >= 200 AND v_http_status < 300);\n        \n        RAISE WARNING 'Accept HTTP Response: Status=%, Body=%', v_http_status, LEFT(v_http_response, 200);\n        \n        IF v_delivery_success THEN\n            -- Immediate delivery succeeded\n            UPDATE ap_activities \n            SET status = 'completed',\n                last_attempt_at = NOW()\n            WHERE id = v_activity_uuid;\n            \n            RAISE NOTICE '✅ Accept delivery succeeded to: % (HTTP %)', v_follower_domain, v_http_status;\n            \n            -- Also mark the original Follow as completed/accepted\n            UPDATE ap_activities\n            SET status = 'completed'\n            WHERE id = follow_activity_id;\n            \n        ELSE\n            -- Immediate delivery failed, queue for retry\n            UPDATE ap_activities \n            SET status = 'failed',\n                attempts = 1,\n                last_attempt_at = NOW(),\n                error_message = format('HTTP %s: %s', v_http_status, LEFT(v_http_response, 500))\n            WHERE id = v_activity_uuid;\n            \n            RAISE WARNING '❌ Accept delivery failed to % (HTTP %): %', \n                v_follower_domain, v_http_status, LEFT(v_http_response, 200);\n            \n            -- Queue for retry\n            PERFORM queue_activity_for_federation(v_activity_uuid, ARRAY[v_follower_domain], 8, true);\n        END IF;\n        \n    EXCEPTION \n        WHEN OTHERS THEN\n            -- HTTP extension not available or network error, queue for delivery\n            UPDATE ap_activities \n            SET status = 'failed',\n                error_message = 'HTTP delivery failed: ' || SQLERRM\n            WHERE id = v_activity_uuid;\n            \n            RAISE WARNING '💥 Accept HTTP delivery exception to % - Error: %', v_follower_domain, SQLERRM;\n            PERFORM queue_activity_for_federation(v_activity_uuid, ARRAY[v_follower_domain], 8, true);\n    END;\n    \nEND;\n$function$\n"
    }
  },
  {
    "function_json": {
      "function_name": "send_notification",
      "return_type": "uuid[]",
      "arguments": "notification_type character varying, to_user_ids uuid[], notification_data jsonb DEFAULT '{}'::jsonb, server_id uuid DEFAULT NULL::uuid, channel_id uuid DEFAULT NULL::uuid, conversation_id uuid DEFAULT NULL::uuid, from_user_id uuid DEFAULT NULL::uuid, priority character varying DEFAULT 'normal'::character varying",
      "definition": "CREATE OR REPLACE FUNCTION public.send_notification(notification_type character varying, to_user_ids uuid[], notification_data jsonb DEFAULT '{}'::jsonb, server_id uuid DEFAULT NULL::uuid, channel_id uuid DEFAULT NULL::uuid, conversation_id uuid DEFAULT NULL::uuid, from_user_id uuid DEFAULT NULL::uuid, priority character varying DEFAULT 'normal'::character varying)\n RETURNS uuid[]\n LANGUAGE plpgsql\n SECURITY DEFINER\nAS $function$\nDECLARE\n    created_notification_ids uuid[] := '{}';\n    recipient_id uuid;\n    user_prefs record;\n    should_send boolean;\n    notification_id uuid;\n    current_timestamp timestamp with time zone := now();\n    enhanced_data jsonb;\nBEGIN\n    -- Validate inputs\n    IF notification_type IS NULL OR array_length(to_user_ids, 1) IS NULL THEN\n        RETURN '{}';\n    END IF;\n\n    -- Process each recipient\n    FOREACH recipient_id IN ARRAY to_user_ids LOOP\n        -- Skip if sending to self (optional check)\n        IF from_user_id IS NOT NULL AND recipient_id = from_user_id THEN\n            CONTINUE;\n        END IF;\n\n        -- Get user notification preferences if table exists\n        user_prefs := NULL;\n        BEGIN\n            SELECT * INTO user_prefs FROM notification_preferences WHERE user_id = recipient_id;\n        EXCEPTION\n            WHEN undefined_table THEN\n                -- notification_preferences table doesn't exist, send all notifications\n                user_prefs := NULL;\n        END;\n\n        -- Default to sending notifications if no preferences found\n        should_send := true;\n\n        -- Apply preferences if they exist\n        IF user_prefs IS NOT NULL THEN\n            -- ✅ FIXED: Use ACTUAL column names from notification_preferences table\n            CASE notification_type\n                WHEN 'mention' THEN\n                    should_send := COALESCE(user_prefs.desktop_mentions, true);\n                WHEN 'reply' THEN\n                    should_send := COALESCE(user_prefs.desktop_replies, true);\n                WHEN 'dm' THEN\n                    should_send := COALESCE(user_prefs.desktop_dms, true);\n                WHEN 'reaction' THEN\n                    should_send := COALESCE(user_prefs.desktop_reactions, true);\n                WHEN 'activitypub_follow' THEN\n                    should_send := COALESCE(user_prefs.activitypub_desktop_follows, true);\n                WHEN 'activitypub_favorite' THEN\n                    should_send := COALESCE(user_prefs.activitypub_desktop_favorites, true);\n                WHEN 'activitypub_reblog' THEN\n                    should_send := COALESCE(user_prefs.activitypub_desktop_reblogs, true);\n                WHEN 'activitypub_mention' THEN\n                    should_send := COALESCE(user_prefs.activitypub_desktop_mentions, true);\n                WHEN 'activitypub_reply' THEN\n                    should_send := COALESCE(user_prefs.activitypub_desktop_replies, true);\n                ELSE\n                    should_send := true; -- Default to sending for unknown types\n            END CASE;\n\n            -- Apply DND restrictions if configured\n            IF user_prefs.dnd_enabled IS TRUE THEN\n                IF current_timestamp::time BETWEEN \n                   COALESCE(user_prefs.dnd_start_time, '22:00'::time) AND \n                   COALESCE(user_prefs.dnd_end_time, '08:00'::time) THEN\n                    should_send := false;\n                END IF;\n            END IF;\n        END IF;\n\n        -- Create enhanced notification data with context\n        enhanced_data := notification_data;\n        \n        -- Add context information to the data field since we can't use separate columns\n        IF server_id IS NOT NULL THEN\n            enhanced_data := enhanced_data || jsonb_build_object('server_id', server_id);\n        END IF;\n        \n        IF channel_id IS NOT NULL THEN\n            enhanced_data := enhanced_data || jsonb_build_object('channel_id', channel_id);\n        END IF;\n        \n        IF conversation_id IS NOT NULL THEN\n            enhanced_data := enhanced_data || jsonb_build_object('conversation_id', conversation_id);\n        END IF;\n        \n        IF from_user_id IS NOT NULL THEN\n            enhanced_data := enhanced_data || jsonb_build_object('from_user_id', from_user_id);\n        END IF;\n        \n        IF priority IS NOT NULL THEN\n            enhanced_data := enhanced_data || jsonb_build_object('priority', priority);\n        END IF;\n\n        -- Create notification if should send - using ONLY existing columns\n        IF should_send THEN\n            INSERT INTO notifications (\n                type,\n                user_id,\n                data,\n                created_at\n            ) VALUES (\n                notification_type,\n                recipient_id,\n                enhanced_data,\n                current_timestamp\n            ) RETURNING id INTO notification_id;\n\n            created_notification_ids := array_append(created_notification_ids, notification_id);\n            \n            RAISE NOTICE '✅ Notification sent: type=% to_user=% id=%', notification_type, recipient_id, notification_id;\n        ELSE\n            RAISE NOTICE '🔇 Notification skipped (user preferences): type=% to_user=%', notification_type, recipient_id;\n        END IF;\n\n    END LOOP;\n\n    RETURN created_notification_ids;\nEND;\n$function$\n"
    }
  },
  {
    "function_json": {
      "function_name": "send_notification_to_followers",
      "return_type": "uuid[]",
      "arguments": "notification_type character varying, target_user_id uuid, notification_data jsonb DEFAULT '{}'::jsonb, from_user_id uuid DEFAULT NULL::uuid, priority character varying DEFAULT 'normal'::character varying",
      "definition": "CREATE OR REPLACE FUNCTION public.send_notification_to_followers(notification_type character varying, target_user_id uuid, notification_data jsonb DEFAULT '{}'::jsonb, from_user_id uuid DEFAULT NULL::uuid, priority character varying DEFAULT 'normal'::character varying)\n RETURNS uuid[]\n LANGUAGE plpgsql\nAS $function$\nDECLARE\n    follower_ids uuid[];\nBEGIN\n    -- Get all followers\n    SELECT array_agg(follower_id)\n    INTO follower_ids\n    FROM follows f\n    WHERE f.following_id = target_user_id\n    AND f.status = 'accepted';\n\n    -- Send notifications to all followers\n    RETURN send_notification(\n        notification_type,\n        follower_ids,\n        notification_data,\n        NULL,\n        NULL,\n        NULL,\n        from_user_id,\n        priority\n    );\nEND;\n$function$\n"
    }
  },
  {
    "function_json": {
      "function_name": "send_notification_to_server_members",
      "return_type": "uuid[]",
      "arguments": "notification_type character varying, target_server_id uuid, notification_data jsonb DEFAULT '{}'::jsonb, channel_id uuid DEFAULT NULL::uuid, from_user_id uuid DEFAULT NULL::uuid, exclude_user_ids uuid[] DEFAULT '{}'::uuid[], priority character varying DEFAULT 'normal'::character varying",
      "definition": "CREATE OR REPLACE FUNCTION public.send_notification_to_server_members(notification_type character varying, target_server_id uuid, notification_data jsonb DEFAULT '{}'::jsonb, channel_id uuid DEFAULT NULL::uuid, from_user_id uuid DEFAULT NULL::uuid, exclude_user_ids uuid[] DEFAULT '{}'::uuid[], priority character varying DEFAULT 'normal'::character varying)\n RETURNS uuid[]\n LANGUAGE plpgsql\nAS $function$\nDECLARE\n    server_member_ids uuid[];\nBEGIN\n    -- Get all server members\n    SELECT array_agg(user_id)\n    INTO server_member_ids\n    FROM user_servers us\n    WHERE us.server_id = target_server_id\n    AND (exclude_user_ids IS NULL OR NOT (us.user_id = ANY(exclude_user_ids)));\n\n    -- Send notifications to all members\n    RETURN send_notification(\n        notification_type,\n        server_member_ids,\n        notification_data,\n        target_server_id,\n        channel_id,\n        NULL,\n        from_user_id,\n        priority\n    );\nEND;\n$function$\n"
    }
  },
  {
    "function_json": {
      "function_name": "send_notification_to_user",
      "return_type": "uuid",
      "arguments": "notification_type character varying, to_user_id uuid, notification_data jsonb DEFAULT '{}'::jsonb, server_id uuid DEFAULT NULL::uuid, channel_id uuid DEFAULT NULL::uuid, conversation_id uuid DEFAULT NULL::uuid, from_user_id uuid DEFAULT NULL::uuid, priority character varying DEFAULT 'normal'::character varying",
      "definition": "CREATE OR REPLACE FUNCTION public.send_notification_to_user(notification_type character varying, to_user_id uuid, notification_data jsonb DEFAULT '{}'::jsonb, server_id uuid DEFAULT NULL::uuid, channel_id uuid DEFAULT NULL::uuid, conversation_id uuid DEFAULT NULL::uuid, from_user_id uuid DEFAULT NULL::uuid, priority character varying DEFAULT 'normal'::character varying)\n RETURNS uuid\n LANGUAGE sql\n SECURITY DEFINER\nAS $function$\n    SELECT (send_notification(\n        notification_type,\n        ARRAY[to_user_id],\n        notification_data,\n        server_id,\n        channel_id,\n        conversation_id,\n        from_user_id,\n        priority\n    ))[1];\n$function$\n"
    }
  },
  {
    "function_json": {
      "function_name": "set_activitypub_conversation_root_id",
      "return_type": "trigger",
      "arguments": "",
      "definition": "CREATE OR REPLACE FUNCTION public.set_activitypub_conversation_root_id()\n RETURNS trigger\n LANGUAGE plpgsql\nAS $function$\nBEGIN\n    IF NEW.in_reply_to IS NULL THEN\n        -- This is a root post, set conversation_root_id to its own ID\n        NEW.conversation_root_id = NEW.id;\n    ELSE\n        -- This is a reply, inherit conversation_root_id from parent\n        SELECT conversation_root_id \n        INTO NEW.conversation_root_id\n        FROM posts \n        WHERE id = NEW.in_reply_to;\n        \n        -- If parent doesn't exist or has no conversation_root_id, make this the root\n        IF NEW.conversation_root_id IS NULL THEN\n            NEW.conversation_root_id = NEW.id;\n        END IF;\n    END IF;\n    \n    RETURN NEW;\nEND;\n$function$\n"
    }
  },
  {
    "function_json": {
      "function_name": "set_instance_config",
      "return_type": "boolean",
      "arguments": "p_admin_id uuid, p_key text, p_value jsonb, p_description text DEFAULT NULL::text",
      "definition": "CREATE OR REPLACE FUNCTION public.set_instance_config(p_admin_id uuid, p_key text, p_value jsonb, p_description text DEFAULT NULL::text)\n RETURNS boolean\n LANGUAGE plpgsql\n SECURITY DEFINER\nAS $function$\nDECLARE\n    old_value JSONB;\nBEGIN\n    -- Check if admin has permission\n    IF NOT EXISTS (SELECT 1 FROM profiles WHERE id = p_admin_id AND is_admin = TRUE) THEN\n        RAISE EXCEPTION 'Insufficient permissions';\n    END IF;\n    \n    -- Get old value for logging\n    SELECT config_value INTO old_value FROM instance_config WHERE config_key = p_key;\n    \n    -- Update or insert configuration\n    INSERT INTO instance_config (config_key, config_value, description, updated_by, updated_at)\n    VALUES (p_key, p_value, p_description, p_admin_id, NOW())\n    ON CONFLICT (config_key) DO UPDATE SET\n        config_value = p_value,\n        description = COALESCE(p_description, instance_config.description),\n        updated_by = p_admin_id,\n        updated_at = NOW();\n    \n    -- Log the action\n    PERFORM log_admin_action(\n        p_admin_id,\n        'config_change',\n        'config',\n        p_key,\n        json_build_object(\n            'old_value', old_value,\n            'new_value', p_value,\n            'key', p_key\n        )\n    );\n    \n    RETURN TRUE;\nEND;\n$function$\n"
    }
  },
  {
    "function_json": {
      "function_name": "setup_activitypub_federation",
      "return_type": "trigger",
      "arguments": "",
      "definition": "CREATE OR REPLACE FUNCTION public.setup_activitypub_federation()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\nAS $function$\nDECLARE\n    v_domain TEXT;\n    v_metadata RECORD;\nBEGIN\n    -- Only set up federation for local users\n    -- Remote federated users already have their own federation setup\n    IF NEW.is_local = true OR NEW.is_local IS NULL THEN\n        \n        -- Get the instance domain (cast JSONB to TEXT and remove quotes if present)\n        SELECT trim(both '\"' from config_value::text) INTO v_domain \n        FROM instance_config \n        WHERE config_key = 'domain' \n        LIMIT 1;\n        \n        -- Only proceed if we have a domain configured\n        IF v_domain IS NOT NULL AND v_domain != '' THEN\n            \n            -- Generate ActivityPub metadata including RSA keys\n            SELECT * INTO v_metadata\n            FROM generate_activitypub_metadata(\n                NEW.id,\n                NEW.username,\n                v_domain\n            );\n            \n            -- Update the profile with federation data\n            -- Use UPDATE instead of modifying NEW to avoid infinite triggers\n            UPDATE profiles SET\n                domain = v_domain,\n                federated_id = v_metadata.federated_id,\n                inbox_url = v_metadata.inbox_url,\n                outbox_url = v_metadata.outbox_url,\n                followers_url = v_metadata.followers_url,\n                following_url = v_metadata.following_url,\n                featured_url = v_metadata.featured_url,\n                public_key = v_metadata.public_key,\n                private_key = v_metadata.private_key,\n                last_synced_at = NOW()\n            WHERE id = NEW.id;\n            \n            RAISE NOTICE 'Set up ActivityPub federation for local user: %', NEW.username;\n            \n        ELSE\n            RAISE WARNING 'No domain configured in instance_config, skipping ActivityPub setup for user: %', NEW.username;\n        END IF;\n        \n    ELSE\n        -- Remote user - no federation setup needed\n        RAISE NOTICE 'Skipping ActivityPub setup for remote user: %@%', NEW.username, NEW.domain;\n    END IF;\n    \n    RETURN NEW;\nEND;\n$function$\n"
    }
  },
  {
    "function_json": {
      "function_name": "should_create_notification",
      "return_type": "boolean",
      "arguments": "p_user_id uuid, p_type character varying, p_server_id uuid DEFAULT NULL::uuid, p_channel_id uuid DEFAULT NULL::uuid, p_conversation_id uuid DEFAULT NULL::uuid",
      "definition": "CREATE OR REPLACE FUNCTION public.should_create_notification(p_user_id uuid, p_type character varying, p_server_id uuid DEFAULT NULL::uuid, p_channel_id uuid DEFAULT NULL::uuid, p_conversation_id uuid DEFAULT NULL::uuid)\n RETURNS boolean\n LANGUAGE plpgsql\nAS $function$\nBEGIN\n    -- For now, always allow notifications\n    -- This can be enhanced later with user preferences\n    RETURN TRUE;\nEND;\n$function$\n"
    }
  },
  {
    "function_json": {
      "function_name": "strip_dm_mentions",
      "return_type": "jsonb",
      "arguments": "content jsonb, local_instance_domain text",
      "definition": "CREATE OR REPLACE FUNCTION public.strip_dm_mentions(content jsonb, local_instance_domain text)\n RETURNS jsonb\n LANGUAGE plpgsql\n IMMUTABLE\nAS $function$\nDECLARE\n    result jsonb := '[]'::jsonb;\n    part jsonb;\n    is_first_mention boolean := true;\nBEGIN\n    -- For DMs, we want to strip mentions at the beginning since they're contextual\n    -- This is APPLICATION logic, not CONVERSION logic!\n    \n    FOR part IN SELECT jsonb_array_elements(content)\n    LOOP\n        -- Skip leading mentions in DMs (they're implied by conversation context)\n        IF (part->>'type') = 'mention' AND is_first_mention THEN\n            -- Check if this is a local mention (recipient)\n            IF (part->>'domain') = local_instance_domain OR (part->>'isLocal')::boolean = true THEN\n                CONTINUE; -- Skip local mentions at start of DMs\n            END IF;\n        END IF;\n        \n        -- Once we hit non-mention content, stop skipping mentions\n        IF (part->>'type') != 'mention' THEN\n            is_first_mention := false;\n        END IF;\n        \n        -- Add this part to result\n        result := result || part;\n    END LOOP;\n    \n    RETURN result;\nEND;\n$function$\n"
    }
  },
  {
    "function_json": {
      "function_name": "strip_mentions_from_dm_content",
      "return_type": "jsonb",
      "arguments": "content jsonb",
      "definition": "CREATE OR REPLACE FUNCTION public.strip_mentions_from_dm_content(content jsonb)\n RETURNS jsonb\n LANGUAGE plpgsql\n IMMUTABLE\nAS $function$\nDECLARE\n    result_array jsonb := '[]'::jsonb;\n    content_item jsonb;\nBEGIN\n    -- Handle null or non-array content\n    IF content IS NULL OR jsonb_typeof(content) != 'array' THEN\n        RETURN content;\n    END IF;\n    \n    -- Filter out mention objects, keep everything else\n    FOR content_item IN SELECT jsonb_array_elements(content)\n    LOOP\n        IF content_item->>'type' != 'mention' THEN\n            result_array := result_array || jsonb_build_array(content_item);\n        END IF;\n    END LOOP;\n    \n    RETURN result_array;\nEND;\n$function$\n"
    }
  },
  {
    "function_json": {
      "function_name": "trigger_process_post_hashtags",
      "return_type": "trigger",
      "arguments": "",
      "definition": "CREATE OR REPLACE FUNCTION public.trigger_process_post_hashtags()\n RETURNS trigger\n LANGUAGE plpgsql\nAS $function$\nBEGIN\n    -- Process hashtags for new posts\n    PERFORM process_post_hashtags(NEW.id, NEW.content);\n    RETURN NEW;\nEND;\n$function$\n"
    }
  },
  {
    "function_json": {
      "function_name": "update_emoji_updated_at",
      "return_type": "trigger",
      "arguments": "",
      "definition": "CREATE OR REPLACE FUNCTION public.update_emoji_updated_at()\n RETURNS trigger\n LANGUAGE plpgsql\nAS $function$\nBEGIN\n    NEW.updated_at = now();\n    RETURN NEW;\nEND;\n$function$\n"
    }
  },
  {
    "function_json": {
      "function_name": "update_follow_counters",
      "return_type": "trigger",
      "arguments": "",
      "definition": "CREATE OR REPLACE FUNCTION public.update_follow_counters()\n RETURNS trigger\n LANGUAGE plpgsql\nAS $function$\nBEGIN\n    -- Handle different trigger events\n    IF TG_OP = 'INSERT' THEN\n        -- New follow relationship\n        IF NEW.status = 'accepted' THEN\n            -- Increment follower count for the followed user\n            UPDATE profiles \n            SET followers_count = followers_count + 1 \n            WHERE id = NEW.following_id;\n            \n            -- Increment following count for the follower\n            UPDATE profiles \n            SET following_count = following_count + 1 \n            WHERE id = NEW.follower_id;\n        END IF;\n        RETURN NEW;\n        \n    ELSIF TG_OP = 'UPDATE' THEN\n        -- Follow status changed\n        IF OLD.status != NEW.status THEN\n            IF OLD.status = 'accepted' AND NEW.status != 'accepted' THEN\n                -- Follow was accepted, now it's not (unfriend/reject)\n                UPDATE profiles \n                SET followers_count = followers_count - 1 \n                WHERE id = NEW.following_id;\n                \n                UPDATE profiles \n                SET following_count = following_count - 1 \n                WHERE id = NEW.follower_id;\n                \n            ELSIF OLD.status != 'accepted' AND NEW.status = 'accepted' THEN\n                -- Follow was not accepted, now it is\n                UPDATE profiles \n                SET followers_count = followers_count + 1 \n                WHERE id = NEW.following_id;\n                \n                UPDATE profiles \n                SET following_count = following_count + 1 \n                WHERE id = NEW.follower_id;\n            END IF;\n        END IF;\n        RETURN NEW;\n        \n    ELSIF TG_OP = 'DELETE' THEN\n        -- Follow relationship deleted\n        IF OLD.status = 'accepted' THEN\n            UPDATE profiles \n            SET followers_count = followers_count - 1 \n            WHERE id = OLD.following_id;\n            \n            UPDATE profiles \n            SET following_count = following_count - 1 \n            WHERE id = OLD.follower_id;\n        END IF;\n        RETURN OLD;\n    END IF;\n    \n    RETURN NULL;\nEND;\n$function$\n"
    }
  },
  {
    "function_json": {
      "function_name": "update_follower_timelines",
      "return_type": "trigger",
      "arguments": "",
      "definition": "CREATE OR REPLACE FUNCTION public.update_follower_timelines()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\nAS $function$\nBEGIN\n  -- Update home timelines for all followers\n  INSERT INTO pg_background_job (\n    job_type,\n    payload\n  ) VALUES (\n    'update_follower_timelines',\n    jsonb_build_object(\n      'post_id', NEW.id,\n      'author_id', NEW.author_id,\n      'post_data', to_jsonb(NEW)\n    )\n  );\n  \n  RETURN NEW;\nEND;\n$function$\n"
    }
