  {
    "function_json": {
      "function_name": "update_group_icon",
      "return_type": "jsonb",
      "arguments": "conversation_uuid uuid, user_profile_id uuid, icon_path text",
      "definition": "CREATE OR REPLACE FUNCTION public.update_group_icon(conversation_uuid uuid, user_profile_id uuid, icon_path text)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\nAS $function$\nDECLARE\n  is_participant BOOLEAN := false;\n  conversation_exists BOOLEAN := false;\nBEGIN\n  -- Check if user is a participant in the conversation\n  SELECT can_manage_group_icon(conversation_uuid, user_profile_id) INTO is_participant;\n  \n  IF NOT is_participant THEN\n    RETURN jsonb_build_object(\n      'success', false,\n      'error', 'User is not a participant in this conversation'\n    );\n  END IF;\n  \n  -- Check if conversation exists and is a group\n  SELECT EXISTS(\n    SELECT 1 FROM conversations \n    WHERE id = conversation_uuid AND type = 'group'\n  ) INTO conversation_exists;\n  \n  IF NOT conversation_exists THEN\n    RETURN jsonb_build_object(\n      'success', false,\n      'error', 'Group conversation not found'\n    );\n  END IF;\n  \n  -- Update the conversation metadata with the new icon path\n  UPDATE conversations \n  SET \n    metadata = COALESCE(metadata, '{}'::jsonb) || jsonb_build_object('icon_url', icon_path),\n    updated_at = CURRENT_TIMESTAMP\n  WHERE id = conversation_uuid\n    AND type = 'group';\n  \n  RETURN jsonb_build_object(\n    'success', true,\n    'message', 'Group icon updated successfully'\n  );\nEND;\n$function$\n"
    }
  },
  {
    "function_json": {
      "function_name": "update_group_name",
      "return_type": "jsonb",
      "arguments": "conversation_uuid uuid, user_profile_id uuid, new_name text",
      "definition": "CREATE OR REPLACE FUNCTION public.update_group_name(conversation_uuid uuid, user_profile_id uuid, new_name text)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\nAS $function$\nDECLARE\n  is_participant BOOLEAN := false;\n  conversation_exists BOOLEAN := false;\nBEGIN\n  -- Check if user is a participant in the conversation\n  SELECT can_manage_group_icon(conversation_uuid, user_profile_id) INTO is_participant;\n  \n  IF NOT is_participant THEN\n    RETURN jsonb_build_object(\n      'success', false,\n      'error', 'User is not a participant in this conversation'\n    );\n  END IF;\n  \n  -- Check if conversation exists and is a group\n  SELECT EXISTS(\n    SELECT 1 FROM conversations \n    WHERE id = conversation_uuid AND type = 'group'\n  ) INTO conversation_exists;\n  \n  IF NOT conversation_exists THEN\n    RETURN jsonb_build_object(\n      'success', false,\n      'error', 'Group conversation not found'\n    );\n  END IF;\n  \n  -- Update the conversation name\n  UPDATE conversations \n  SET \n    name = new_name,\n    updated_at = CURRENT_TIMESTAMP\n  WHERE id = conversation_uuid\n    AND type = 'group';\n  \n  RETURN jsonb_build_object(\n    'success', true,\n    'message', 'Group name updated successfully'\n  );\nEND;\n$function$\n"
    }
  },
  {
    "function_json": {
      "function_name": "update_hashtag_trending_scores",
      "return_type": "integer",
      "arguments": "",
      "definition": "CREATE OR REPLACE FUNCTION public.update_hashtag_trending_scores()\n RETURNS integer\n LANGUAGE plpgsql\nAS $function$\nDECLARE\n    updated_count INTEGER := 0;\nBEGIN\n    -- Update trending scores for all hashtags\n    UPDATE hashtags \n    SET \n        trending_score = calculate_hashtag_trending_score(\n            daily_uses,\n            weekly_uses,\n            total_uses,\n            EXTRACT(EPOCH FROM (NOW() - last_used_at)) / 3600\n        ),\n        last_trending_update = NOW(),\n        updated_at = NOW()\n    WHERE last_used_at >= NOW() - INTERVAL '7 days'; -- Only update recently used hashtags\n    \n    GET DIAGNOSTICS updated_count = ROW_COUNT;\n    \n    -- Update trending ranks\n    UPDATE hashtags \n    SET trending_rank = ranked.rank_num\n    FROM (\n        SELECT id, ROW_NUMBER() OVER (ORDER BY trending_score DESC) as rank_num\n        FROM hashtags \n        WHERE trending_score > 0\n        ORDER BY trending_score DESC\n        LIMIT 100\n    ) ranked\n    WHERE hashtags.id = ranked.id;\n    \n    -- Clear ranks for non-trending hashtags\n    UPDATE hashtags \n    SET trending_rank = NULL\n    WHERE trending_score <= 0 OR trending_rank > 100;\n    \n    RETURN updated_count;\nEND;\n$function$\n"
    }
  },
  {
    "function_json": {
      "function_name": "update_post_counters",
      "return_type": "trigger",
      "arguments": "",
      "definition": "CREATE OR REPLACE FUNCTION public.update_post_counters()\n RETURNS trigger\n LANGUAGE plpgsql\nAS $function$\nBEGIN\n    IF TG_OP = 'INSERT' THEN\n        -- New post created\n        UPDATE profiles \n        SET posts_count = posts_count + 1 \n        WHERE id = NEW.author_id;\n        RETURN NEW;\n        \n    ELSIF TG_OP = 'UPDATE' THEN\n        -- Post updated (might be soft delete)\n        IF OLD.deleted_at IS NULL AND NEW.deleted_at IS NOT NULL THEN\n            -- Post was soft deleted\n            UPDATE profiles \n            SET posts_count = posts_count - 1 \n            WHERE id = NEW.author_id;\n        ELSIF OLD.deleted_at IS NOT NULL AND NEW.deleted_at IS NULL THEN\n            -- Post was restored\n            UPDATE profiles \n            SET posts_count = posts_count + 1 \n            WHERE id = NEW.author_id;\n        END IF;\n        RETURN NEW;\n        \n    ELSIF TG_OP = 'DELETE' THEN\n        -- Post hard deleted\n        IF OLD.deleted_at IS NULL THEN\n            UPDATE profiles \n            SET posts_count = posts_count - 1 \n            WHERE id = OLD.author_id;\n        END IF;\n        RETURN OLD;\n    END IF;\n    \n    RETURN NULL;\nEND;\n$function$\n"
    }
  },
  {
    "function_json": {
      "function_name": "update_reply_counts",
      "return_type": "trigger",
      "arguments": "",
      "definition": "CREATE OR REPLACE FUNCTION public.update_reply_counts()\n RETURNS trigger\n LANGUAGE plpgsql\nAS $function$\nBEGIN\n    IF TG_OP = 'INSERT' AND NEW.in_reply_to IS NOT NULL THEN\n        UPDATE posts SET replies_count = replies_count + 1\n        WHERE id = NEW.in_reply_to;\n        RETURN NEW;\n    ELSIF TG_OP = 'DELETE' AND OLD.in_reply_to IS NOT NULL THEN\n        UPDATE posts SET replies_count = replies_count - 1\n        WHERE id = OLD.in_reply_to;\n        RETURN OLD;\n    END IF;\n    RETURN COALESCE(NEW, OLD);\nEND;\n$function$\n"
    }
  },
  {
    "function_json": {
      "function_name": "update_timeline_cache",
      "return_type": "boolean",
      "arguments": "p_user_id uuid, p_timeline_type text, p_action text, p_post_data jsonb DEFAULT NULL::jsonb",
      "definition": "CREATE OR REPLACE FUNCTION public.update_timeline_cache(p_user_id uuid, p_timeline_type text, p_action text, p_post_data jsonb DEFAULT NULL::jsonb)\n RETURNS boolean\n LANGUAGE plpgsql\nAS $function$DECLARE\n  current_posts jsonb;\n  new_posts jsonb;\nBEGIN\n  -- Get current cache\n  SELECT posts_data INTO current_posts\n  FROM user_timeline_cache \n  WHERE user_id = p_user_id AND timeline_type = p_timeline_type;\n  \n  -- Initialize if not exists\n  IF current_posts IS NULL THEN\n    current_posts := '[]'::jsonb;\n  END IF;\n  \n  -- Perform action\n  CASE p_action\n    WHEN 'add' THEN\n      -- Add new post to beginning, keep max 100 posts\n      new_posts := jsonb_build_array(p_post_data) || current_posts;\n      new_posts := (\n        SELECT jsonb_agg(post_data)\n        FROM (\n          SELECT value as post_data\n          FROM jsonb_array_elements(new_posts) \n          LIMIT 100\n        ) limited\n      );\n      \n    WHEN 'remove' THEN\n      -- Remove post by ID\n      new_posts := (\n        SELECT COALESCE(jsonb_agg(post_data), '[]'::jsonb)\n        FROM (\n          SELECT value as post_data\n          FROM jsonb_array_elements(current_posts)\n          WHERE value->>'id' != p_post_data->>'id'\n        ) filtered\n      );\n      \n    WHEN 'rebuild' THEN\n      -- Full rebuild from timeline view\n      SELECT jsonb_agg(\n        to_jsonb(tp.*) ORDER BY tp.created_at DESC\n      ) INTO new_posts\n      FROM timeline_posts tp\n      WHERE \n        CASE p_timeline_type\n          WHEN 'home' THEN \n            (tp.author->>'id')::uuid = p_user_id OR \n            (tp.author->>'id')::uuid IN (\n              SELECT following_id FROM follows \n              WHERE follower_id = p_user_id\n            )\n          WHEN 'local' THEN (tp.author->>'is_local')::boolean = true AND tp.visibility = 'public'\n          WHEN 'public' THEN tp.visibility = 'public'\n        END\n      LIMIT 100;\n      \n    ELSE\n      RETURN false;\n  END CASE;\n  \n  -- Upsert cache\n  INSERT INTO user_timeline_cache (user_id, timeline_type, posts_data)\n  VALUES (p_user_id, p_timeline_type, COALESCE(new_posts, '[]'::jsonb))\n  ON CONFLICT (user_id, timeline_type) \n  DO UPDATE SET \n    posts_data = EXCLUDED.posts_data,\n    last_updated = now();\n    \n  RETURN true;\nEND;$function$\n"
    }
  },
  {
    "function_json": {
      "function_name": "update_trending_posts",
      "return_type": "integer",
      "arguments": "",
      "definition": "CREATE OR REPLACE FUNCTION public.update_trending_posts()\n RETURNS integer\n LANGUAGE plpgsql\nAS $function$\nDECLARE\n    updated_count INTEGER := 0;\nBEGIN\n    -- Clear old trending posts data\n    DELETE FROM trending_posts \n    WHERE period_start < NOW() - INTERVAL '7 days';\n    \n    -- Insert/update trending posts for today\n    INSERT INTO trending_posts (\n        post_id, trending_score, engagement_score, period_type, \n        period_start, period_end, likes_count, reblogs_count, replies_count\n    )\n    SELECT \n        p.id,\n        calculate_post_engagement_score(\n            p.favorites_count, \n            p.reblogs_count, \n            p.replies_count,\n            EXTRACT(EPOCH FROM (NOW() - p.created_at)) / 3600\n        ),\n        (p.favorites_count + p.reblogs_count + p.replies_count)::DECIMAL,\n        'daily',\n        date_trunc('day', NOW()),\n        date_trunc('day', NOW()) + INTERVAL '1 day',\n        p.favorites_count,\n        p.reblogs_count,\n        p.replies_count\n    FROM posts p\n    WHERE \n        p.created_at >= NOW() - INTERVAL '2 days'\n        AND p.visibility IN ('public', 'unlisted')\n        AND p.is_deleted = false\n        AND (p.favorites_count + p.reblogs_count + p.replies_count) > 0\n    ON CONFLICT (post_id, period_type, period_start) DO UPDATE SET\n        trending_score = EXCLUDED.trending_score,\n        engagement_score = EXCLUDED.engagement_score,\n        likes_count = EXCLUDED.likes_count,\n        reblogs_count = EXCLUDED.reblogs_count,\n        replies_count = EXCLUDED.replies_count,\n        updated_at = NOW();\n    \n    GET DIAGNOSTICS updated_count = ROW_COUNT;\n    \n    -- Update trending ranks\n    UPDATE trending_posts \n    SET trending_rank = ranked.rank_num\n    FROM (\n        SELECT id, ROW_NUMBER() OVER (ORDER BY trending_score DESC) as rank_num\n        FROM trending_posts \n        WHERE period_type = 'daily' \n          AND period_start = date_trunc('day', NOW())\n        ORDER BY trending_score DESC\n        LIMIT 100\n    ) ranked\n    WHERE trending_posts.id = ranked.id;\n    \n    RETURN updated_count;\nEND;\n$function$\n"
    }
  },
  {
    "function_json": {
      "function_name": "update_unread_count",
      "return_type": "void",
      "arguments": "p_user_id uuid, p_server_id uuid DEFAULT NULL::uuid, p_channel_id uuid DEFAULT NULL::uuid, p_conversation_id uuid DEFAULT NULL::uuid, p_increment_messages integer DEFAULT 0, p_increment_mentions integer DEFAULT 0, p_last_read_message_id uuid DEFAULT NULL::uuid",
      "definition": "CREATE OR REPLACE FUNCTION public.update_unread_count(p_user_id uuid, p_server_id uuid DEFAULT NULL::uuid, p_channel_id uuid DEFAULT NULL::uuid, p_conversation_id uuid DEFAULT NULL::uuid, p_increment_messages integer DEFAULT 0, p_increment_mentions integer DEFAULT 0, p_last_read_message_id uuid DEFAULT NULL::uuid)\n RETURNS void\n LANGUAGE plpgsql\nAS $function$\nBEGIN\n    INSERT INTO unread_counts (\n        user_id, server_id, channel_id, conversation_id,\n        unread_messages, unread_mentions, last_read_message_id\n    )\n    VALUES (\n        p_user_id, p_server_id, p_channel_id, p_conversation_id,\n        p_increment_messages, p_increment_mentions, p_last_read_message_id\n    )\n    ON CONFLICT (user_id, server_id, channel_id, conversation_id)\n    DO UPDATE SET\n        unread_messages = unread_counts.unread_messages + p_increment_messages,\n        unread_mentions = unread_counts.unread_mentions + p_increment_mentions,\n        last_read_message_id = COALESCE(p_last_read_message_id, unread_counts.last_read_message_id),\n        last_read_at = CASE WHEN p_last_read_message_id IS NOT NULL THEN NOW() ELSE unread_counts.last_read_at END,\n        updated_at = NOW();\nEND;\n$function$\n"
    }
  },
