  {
    "function_json": {
      "function_name": "upsert_ap_activity",
      "return_type": "record",
      "arguments": "p_ap_id text, p_ap_type text, p_actor_ap_id text, p_activity_data jsonb, p_origin_domain text DEFAULT NULL::text, p_to_addresses text[] DEFAULT '{}'::text[], p_cc_addresses text[] DEFAULT '{}'::text[], p_bto_addresses text[] DEFAULT '{}'::text[], p_bcc_addresses text[] DEFAULT '{}'::text[], p_is_local boolean DEFAULT false",
      "definition": "CREATE OR REPLACE FUNCTION public.upsert_ap_activity(p_ap_id text, p_ap_type text, p_actor_ap_id text, p_activity_data jsonb, p_origin_domain text DEFAULT NULL::text, p_to_addresses text[] DEFAULT '{}'::text[], p_cc_addresses text[] DEFAULT '{}'::text[], p_bto_addresses text[] DEFAULT '{}'::text[], p_bcc_addresses text[] DEFAULT '{}'::text[], p_is_local boolean DEFAULT false)\n RETURNS TABLE(activity_id uuid, was_updated boolean)\n LANGUAGE plpgsql\n SECURITY DEFINER\nAS $function$\nDECLARE\n    v_activity_id UUID;\n    v_was_updated BOOLEAN := FALSE;\n    v_existing_status TEXT;\nBEGIN\n    -- Check if activity already exists\n    SELECT id, status INTO v_activity_id, v_existing_status\n    FROM ap_activities \n    WHERE ap_id = p_ap_id;\n    \n    IF v_activity_id IS NOT NULL THEN\n        -- Activity exists, check its status\n        CASE v_existing_status\n            WHEN 'completed', 'processed' THEN\n                -- Already processed successfully, return idempotent success\n                RAISE NOTICE 'Activity % already processed, returning existing ID', p_ap_id;\n                v_was_updated := FALSE;\n            WHEN 'failed', 'pending' THEN\n                -- Failed or pending, update with fresh data for retry\n                UPDATE ap_activities \n                SET \n                    activity_data = p_activity_data,\n                    status = 'received',\n                    to_addresses = p_to_addresses,\n                    cc_addresses = p_cc_addresses,\n                    bto_addresses = p_bto_addresses,\n                    bcc_addresses = p_bcc_addresses,\n                    updated_at = NOW(),\n                    error_message = NULL,\n                    next_attempt_at = NULL,\n                    attempts = 0\n                WHERE ap_id = p_ap_id;\n                \n                RAISE NOTICE 'Updated existing activity % for retry', p_ap_id;\n                v_was_updated := TRUE;\n            WHEN 'processing', 'received' THEN\n                -- Currently being processed or just received, update data but keep status\n                UPDATE ap_activities \n                SET \n                    activity_data = p_activity_data,\n                    to_addresses = p_to_addresses,\n                    cc_addresses = p_cc_addresses,\n                    bto_addresses = p_bto_addresses,\n                    bcc_addresses = p_bcc_addresses,\n                    updated_at = NOW()\n                WHERE ap_id = p_ap_id;\n                \n                RAISE NOTICE 'Updated activity data for currently processing activity %', p_ap_id;\n                v_was_updated := TRUE;\n        END CASE;\n    ELSE\n        -- Activity doesn't exist, insert new one\n        INSERT INTO ap_activities (\n            ap_id,\n            ap_type,\n            actor_ap_id,\n            activity_data,\n            origin_domain,\n            status,\n            is_local,\n            to_addresses,\n            cc_addresses,\n            bto_addresses,\n            bcc_addresses\n        ) VALUES (\n            p_ap_id,\n            p_ap_type,\n            p_actor_ap_id,\n            p_activity_data,\n            p_origin_domain,\n            'received',\n            p_is_local,\n            p_to_addresses,\n            p_cc_addresses,\n            p_bto_addresses,\n            p_bcc_addresses\n        )\n        RETURNING id INTO v_activity_id;\n        \n        RAISE NOTICE 'Inserted new activity %', p_ap_id;\n        v_was_updated := FALSE;\n    END IF;\n    \n    RETURN QUERY SELECT v_activity_id, v_was_updated;\nEND;\n$function$\n"
    }
  },
  {
    "function_json": {
      "function_name": "upsert_hashtag",
      "return_type": "uuid",
      "arguments": "p_hashtag_text text",
      "definition": "CREATE OR REPLACE FUNCTION public.upsert_hashtag(p_hashtag_text text)\n RETURNS uuid\n LANGUAGE plpgsql\nAS $function$\nDECLARE\n    v_hashtag_id UUID;\n    v_normalized TEXT;\nBEGIN\n    v_normalized := normalize_hashtag(p_hashtag_text);\n    \n    -- Insert or update hashtag\n    INSERT INTO hashtags (tag, normalized_tag, total_uses, daily_uses, weekly_uses, last_used_at)\n    VALUES (p_hashtag_text, v_normalized, 1, 1, 1, NOW())\n    ON CONFLICT (normalized_tag) \n    DO UPDATE SET\n        total_uses = hashtags.total_uses + 1,\n        daily_uses = hashtags.daily_uses + 1,\n        weekly_uses = hashtags.weekly_uses + 1,\n        last_used_at = NOW(),\n        updated_at = NOW()\n    RETURNING id INTO v_hashtag_id;\n    \n    RETURN v_hashtag_id;\nEND;\n$function$\n"
    }
  }
